def _share_text(value, limit=180):
    """공유 메타태그용 DB 문자열 정리 — 줄바꿈을 제거하고 길이를 제한한다."""
    return " ".join(str(value or "").split())[:limit]


def _default_share_meta():
    origin = request.url_root.rstrip("/")
    return {
        "title": _HOME_SHARE_TITLE,
        "description": _HOME_SHARE_DESCRIPTION,
        "url": request.url,
        # 매물 사진 유무와 관계없이 공유 카드에는 브랜드 로고를 사용한다.
        # 메신저의 링크 미리보기에서 발신처가 분명하게 보이게 하는 용도다.
        "image": f"{origin}/static/home_stay_share.png?v=3",
    }


def _public_base_url():
    """외부 알림·공유에 쓸 신뢰된 공식 사이트 origin만 반환한다.

    요청 Host 헤더는 사용자가 제어할 수 있으므로, 문자나 이메일 같은 외부
    발송 URL에 절대 사용하지 않는다.
    """
    configured = os.environ.get("PUBLIC_BASE_URL", "").strip().rstrip("/")
    try:
        parsed = urlparse(configured)
        if (
            parsed.scheme == "https"
            and parsed.hostname
            and not parsed.username
            and not parsed.password
            and parsed.path in ("", "/")
            and not parsed.params
            and not parsed.query
            and not parsed.fragment
            and not any(char.isspace() for char in parsed.netloc)
        ):
            return configured
    except (TypeError, ValueError):
        pass
    return "https://homenstay.com"


def _building_share_meta(building_id, listing_id=None):
    """공유 크롤러용 건물/매물 메타태그 값. 실패 시 홈페이지 기본값으로 폴백한다."""
    meta = _default_share_meta()
    conn = cur = None
    try:
        conn = get_conn()
        cur = conn.cursor()
        if listing_id:
            # 제한공개 건물전체는 추측한 /building/<id>?listing=<id> 링크에서도
            # 건물명·주소·가격을 담은 OG 메타로 역추적되면 안 된다.
            cur.execute("""
                SELECT 1
                FROM listing_requests
                WHERE id = %s
                  AND master_building_id = %s
                  AND deal_mode = 'direct'
                  AND COALESCE(status, '') NOT IN ('withdrawn', '철회됨', '보류')
                  AND COALESCE(transaction_target, 'unit') = 'whole'
                  AND COALESCE(disclosure_scope, 'limited') = 'limited'
            """, [listing_id, building_id])
            if cur.fetchone():
                return meta
        cur.execute("""
            SELECT building_name,
                   COALESCE(NULLIF(road_address, ''), NULLIF(jibun_address, ''), NULLIF(sgg_text, '')) AS address
            FROM master_buildings
            WHERE id = %s
        """, [building_id])
        building = cur.fetchone()
        if not building:
            return meta

        building_name = _share_text(building.get("building_name"), 80)
        address = _share_text(building.get("address"), 130)
        if not building_name:
            return meta
        meta["title"] = f"{building_name} 직거래 매물 | 홈앤스테이"
        meta["description"] = (
            f"{address} · {building_name}의 직거래 매물과 실거래가를 확인하세요."
            if address else f"{building_name}의 직거래 매물과 실거래가를 확인하세요."
        )
        if not listing_id:
            return meta

        cur.execute("""
            SELECT id, deal_type, price_krw, price_krw_max, monthly_rent_krw, area_sqm, yield_rate
            FROM listing_requests
            WHERE id = %s
              AND master_building_id = %s
              AND deal_mode = 'direct'
              AND COALESCE(status, '') NOT IN ('withdrawn', '철회됨', '보류')
        """, [listing_id, building_id])
        listing = cur.fetchone()
        if not listing:
            return meta

        summary = _share_text(format_lr_summary(
            listing.get("deal_type"), listing.get("price_krw"), listing.get("monthly_rent_krw"),
            listing.get("area_sqm"), listing.get("yield_rate"), listing.get("price_krw_max"),
        ), 90)
        if summary:
            meta["title"] = f"{building_name} {summary} 직거래 매물 | 홈앤스테이"
            meta["description"] = (
                f"{address} · {summary} 직거래 매물입니다."
                if address else f"{building_name} {summary} 직거래 매물입니다."
            )

        return meta
    except Exception:
        app.logger.warning("공유 메타태그 조회 실패 (building_id=%s)", building_id, exc_info=True)
        return meta
    finally:
        if cur is not None:
            cur.close()
        if conn is not None:
            conn.close()


app = Flask(__name__, static_folder="static")
Compress(app)   # gzip 응답 압축 (API JSON + HTML 전체)


@app.before_request
def _block_unminified_frontend_sources():
    """배포 모드에서는 원본 JS와 raw HTML의 정적 직접 접근을 막는다."""
    if not _minified_assets_enabled():
        return None
    path = request.path
    if path.startswith("/static/js/") and path.endswith(".js") and not path.endswith(".min.js"):
        abort(404)
    if path.startswith("/static/") and path.lower().endswith((".html", ".htm")):
        abort(404)
    return None


def _mark_master_stats_invalidated_safely(source):
    """커밋된 원본 변경의 통계 캐시 표식 실패가 본 요청을 되돌리지 않게 한다."""
    try:
        mark_master_stats_invalidated(source)
        # 같은 앱 워커에서 바로 이어지는 데이터랩 요청은 10초 폴링을 기다리지
        # 않고, 방금 기록한 DB 무효화 표식을 다시 읽어 최신 집계를 사용한다.
        state = globals().get("_MASTER_STATS_INVALIDATION_STATE")
        if state is not None:
            state["checked_at"] = 0.0
    except Exception as e:
        app.logger.warning("[stats-cache] invalidation failed (%s): %s", source, str(e)[:200])


