_AUTHORITY_INDEX = None


def get_authority_index():
    """lodging_authority_contacts(135행)로 담당부서 매칭 인덱스를 1회 만들어 캐시한다.

    데이터가 정적(엑셀 적재본)이고 gunicorn 자동 리로드가 없어 프로세스 단위 캐시로 충분.
    적재를 다시 하면(load_authority_contacts.py) 앱을 재시작해야 새 값이 반영된다.
    """
    global _AUTHORITY_INDEX
    if _AUTHORITY_INDEX is None:
        conn = get_conn()
        cur = conn.cursor()
        cur.execute("SELECT region_name_raw, dept, phone FROM lodging_authority_contacts")
        rows = [dict(r) for r in cur.fetchall()]
        cur.close()
        conn.close()
        _AUTHORITY_INDEX = build_authority_index(rows)
    return _AUTHORITY_INDEX


def _fetch_and_cache_building_detail(building_id, sgg_cd, umd_nm, jibun):
    """건물 첫 방문 시 표제부·지역지구구역·정기점검을 백그라운드로 조회해
    캐싱한다. 요청 스레드를 안 막기 위해 별도 스레드에서 실행됨 — 이번
    방문자는 못 보고, 다음 방문자부터 채워진 값을 본다."""
    try:
        bjd = _get_bjdong_map().find_bjdong_cd(sgg_cd, umd_nm)
        if not bjd:
            return
        plat_gb, bun, ji = parse_jibun(jibun)
        rows_title = building_registry._fetch_title_rows(sgg_cd, bjd, plat_gb, bun, ji)
        rep = max(rows_title, key=lambda r: int(r.get("hoCnt") or 0)) if rows_title else None
        jj_rows = building_registry.fetch_jijigu_rows(sgg_cd, bjd, plat_gb, bun, ji) if rep else []
        insp_rows = building_registry.fetch_maintenance_history(sgg_cd, bjd, plat_gb, bun, ji)

        updates = {"detail_fetched_at": datetime.now()}
        if rep:
            updates.update({
                "plat_area":          _to_float(rep.get("platArea")),
                "arch_area":          _to_float(rep.get("archArea")),
                "tot_area":           _to_float(rep.get("totArea")),
                "bc_rat":             _to_float(rep.get("bcRat")),
                "vl_rat":             _to_float(rep.get("vlRat")),
                "heit":               _to_float(rep.get("heit")),
                "grnd_flr_cnt":       _to_int(rep.get("grndFlrCnt")),
                "ugrnd_flr_cnt":      _to_int(rep.get("ugrndFlrCnt")),
                "ride_use_elvt_cnt":  _to_int(rep.get("rideUseElvtCnt")),
                "emgen_use_elvt_cnt": _to_int(rep.get("emgenUseElvtCnt")),
                "main_purps_nm":      rep.get("mainPurpsCdNm") or None,
                "strct_nm":           rep.get("strctCdNm") or None,
                "hhld_cnt":           _to_int(rep.get("hhldCnt")),
                "indr_auto_utcnt":    _to_int(rep.get("indrAutoUtcnt")),
                "oudr_auto_utcnt":    _to_int(rep.get("oudrAutoUtcnt")),
                "indr_mech_utcnt":    _to_int(rep.get("indrMechUtcnt")),
                "oudr_mech_utcnt":    _to_int(rep.get("oudrMechUtcnt")),
                "use_apr_day":        _fmt_date(rep.get("useAprDay")),
                "permit_day":         _fmt_date(rep.get("pmsDay")),
                "actual_start_day":   _fmt_date(rep.get("stcnsDay")),
            })
        if jj_rows:
            updates["jiyuk_nm"]  = next((r.get("jiyukNm")  for r in jj_rows if r.get("jiyukNm")),  None)
            updates["jigu_nm"]   = next((r.get("jiguNm")   for r in jj_rows if r.get("jiguNm")),   None)
            updates["guyuk_nm"]  = next((r.get("guyukNm")  for r in jj_rows if r.get("guyukNm")),  None)
        if insp_rows:
            latest = max(insp_rows, key=lambda r: r.get("chkStrtDay") or "")
            updates["last_inspection_agency"]     = latest.get("chkCoNm") or None
            updates["last_inspection_start_day"]  = _fmt_date(latest.get("chkStrtDay"))
            updates["last_inspection_submit_day"] = _fmt_date(latest.get("submitDe"))

        conn = get_conn()
        cur = conn.cursor()
        set_sql = ", ".join(f"{k}=%s" for k in updates)
        cur.execute(f"UPDATE master_buildings SET {set_sql} WHERE id=%s",
                    list(updates.values()) + [building_id])
        conn.commit()
        cur.close()
        conn.close()
    except Exception:
        app.logger.warning("건축정보 백그라운드 조회 실패 (building_id=%s)", building_id, exc_info=True)


@app.route("/api/building/<int:building_id>")
@limiter.limit("120 per minute")
def get_building(building_id):
    """건물 상세페이지용 단건 조회 — master_buildings 기준."""
    conn = get_conn()
    cur = conn.cursor()
    cur.execute("""
        SELECT mb.id AS building_id,
               mb.building_name, mb.name_pending, mb.building_name_source,
               mb.building_name_candidate_count,
               mb.road_address, mb.jibun_address,
               mb.lodging_type, mb.lodging_type_detail, mb.lodging_subtype,
               mb.building_status, mb.completion_expected_date,
               mb.permit_day, mb.actual_start_day,
               mb.arch_area, mb.bc_rat, mb.vl_rat,
               mb.sgg_cd, mb.umd_nm, mb.jibun,
               mb.units, mb.biz_units AS biz_units_snapshot_legacy, mb.lat, mb.lng, mb.sgg_text,
               mb.use_apr_day, mb.tot_pkng_cnt, mb.grnd_flr_cnt, mb.ugrnd_flr_cnt,
               mb.tot_area, mb.plat_area, mb.hhld_cnt, mb.strct_nm,
               mb.heit, mb.ride_use_elvt_cnt, mb.emgen_use_elvt_cnt, mb.main_purps_nm,
               mb.indr_auto_utcnt, mb.oudr_auto_utcnt, mb.indr_mech_utcnt, mb.oudr_mech_utcnt,
               mb.jiyuk_nm, mb.jigu_nm, mb.guyuk_nm,
               mb.last_inspection_agency, mb.last_inspection_start_day, mb.last_inspection_submit_day,
               mb.detail_fetched_at,
               mb.booking_url,
               mb.booking_url_expires_at,
               mb.zip_code,
                 mb.jibun_address AS address
        FROM master_buildings mb
        WHERE mb.id = %s
    """, [building_id])
    row = cur.fetchone()
    if not row:
        cur.close()
        conn.close()
        return jsonify({"error": "not found"}), 404

    building = dict(row)  # mutable — 즉시조회 결과를 이번 응답에도 반영

    # 첫 방문 시 표제부·지역지구구역·정기점검을 백그라운드 스레드로 조회해 캐싱.
    # 요청 스레드를 블로킹하지 않으므로 이번 방문자는 "-"로 보이고,
    # 다음 방문자부터 채워진 값을 본다.
    if (not building.get("detail_fetched_at")
            and building.get("sgg_cd") and building.get("umd_nm") and building.get("jibun")):
        threading.Thread(
            target=_fetch_and_cache_building_detail,
            args=(building_id, building["sgg_cd"], building["umd_nm"], building["jibun"]),
            daemon=True,
        ).start()

    # 단지뱃지 중개사: 건물별 활성 정원과 동일하게 최대 2명.
    # 정렬: priority_score DESC(유료 우선노출 자리, 현재 전부 0) → 동점자는 RANDOM().
    # 단일 쿼리 한 줄로 처리해야 전원 0점일 때도 매번 완전 랜덤이 된다 (2단계 분리 금지).
    # 매물 건수(sale/jeonse/wolse/shortterm_count)는 agent_buildings 기준 = "이 건물 한정" 값 (중개사 통산치 아님).
    # 1차: 프리미엄(단지뱃지) 보유 중개사만 — 무료등록 중개사는 메인 3자리에 노출 안 함
    cur.execute("""
        SELECT a.id, a.office_name, a.owner_name, a.phone, a.office_phone,
               a.subdomain_slug, a.photo_url, a.intro_title,
               ab.sale_count, ab.jeonse_count, ab.wolse_count, ab.shortterm_count,
               TRUE AS has_priority_badge
        FROM agent_buildings ab
        JOIN agents a ON a.id = ab.agent_id
        WHERE ab.master_building_id = %s
          AND a.status = 'approved'
          AND COALESCE(a.is_visible, TRUE)
          AND ab.has_priority_badge
          AND (ab.premium_expires_at IS NULL OR ab.premium_expires_at > NOW())
        ORDER BY COALESCE(a.priority_score, 0) DESC, RANDOM()
        LIMIT %s
    """, [building_id, AGENT_BUILDING_BADGE_SLOT_CAP])
    agent_rows = cur.fetchall()

    # 지역Master 보충: 전체 담당중개사 3명 미만일 때 같은 시군구의 지역담당으로 빈 자리를 채운다.
    if len(agent_rows) < 3:
        cur.execute("""
            SELECT a.id, a.office_name, a.owner_name, a.phone, a.office_phone,
                   a.subdomain_slug, a.photo_url, a.intro_title,
                   NULL AS sale_count, NULL AS jeonse_count, NULL AS wolse_count, NULL AS shortterm_count,
                   FALSE AS has_priority_badge, TRUE AS is_region_agent
            FROM agent_service_regions sr
            JOIN agents a ON a.id = sr.agent_id
            WHERE sr.expires_at > NOW()
              AND sr.sgg_text = %s
              AND a.status = 'approved'
              AND COALESCE(a.is_visible, TRUE)
              AND a.id NOT IN (
                  SELECT agent_id FROM agent_buildings
                  WHERE master_building_id = %s AND has_priority_badge
                    AND (premium_expires_at IS NULL OR premium_expires_at > NOW())
              )
            ORDER BY RANDOM()
            LIMIT %s
        """, [
            (building.get("sgg_text") or "").strip(),
            building_id,
            3 - len(agent_rows),
        ])
        agent_rows = list(agent_rows) + list(cur.fetchall())

    # 무료등록 중개사 — 메인 3자리에는 안 넣고 "더보기"용으로 따로 모은다
    cur.execute("""
        SELECT a.id, a.office_name, a.owner_name, a.phone, a.office_phone,
               a.subdomain_slug, a.photo_url, a.intro_title,
               ab.sale_count, ab.jeonse_count, ab.wolse_count, ab.shortterm_count
        FROM agent_buildings ab
        JOIN agents a ON a.id = ab.agent_id
        WHERE ab.master_building_id = %s
          AND a.status = 'approved'
          AND COALESCE(a.is_visible, TRUE)
          AND NOT (ab.has_priority_badge
                   AND (ab.premium_expires_at IS NULL OR ab.premium_expires_at > NOW()))
          AND a.id NOT IN %s
        ORDER BY RANDOM()
        LIMIT 20
    """, [building_id, tuple(r["id"] for r in agent_rows) or (-1,)])
    more_agent_rows = cur.fetchall()

    # 담당 운영업체: operator_buildings에 이 건물이 등록된 approved 운영업체 목록.
    # 화면(B화면 위탁운영/하우스키핑 카드)에서 category별로 골라 최대 3곳씩 표시한다.
    # 정렬은 중개사와 동일하게 priority_score DESC, RANDOM() (카드별 LIMIT은 화면에서 적용).
    cur.execute("""
        SELECT o.id, o.company_name, o.category, o.subdomain_slug, o.intro_text, o.phone, o.website_url,
               (COALESCE(ob.has_priority_badge, FALSE)
                AND (ob.premium_expires_at IS NULL OR ob.premium_expires_at > NOW())) AS is_premium
        FROM operator_buildings ob
        JOIN operators o ON o.id = ob.operator_id
        WHERE ob.master_building_id = %s
          AND o.status = 'approved'
          AND COALESCE(o.is_visible, TRUE)
        ORDER BY is_premium DESC, COALESCE(o.priority_score, 0) DESC, RANDOM()
    """, [building_id])
    operator_rows = [dict(r) for r in cur.fetchall()]

    _o_sgg_cd = str(building.get("sgg_cd") or "")
    _o_prov_prefix = _o_sgg_cd[:2]
    _o_prov_nm = _PROV_SGG_MAP.get(_o_prov_prefix)
    _o_region_match = ["전국"]
    if _o_prov_prefix in _SUDO_PREFIXES:
        _o_region_match.append("수도권")
    if _o_prov_nm:
        _o_region_match.append(_o_prov_nm)
    _o_sgg_text = (building.get("sgg_text") or "").strip()
    cur.execute("""
        SELECT DISTINCT o.id, o.company_name, o.category, o.subdomain_slug, o.phone
        FROM operator_service_regions osr
        JOIN operators o ON o.id = osr.operator_id
        WHERE osr.sgg_text = %s
          AND osr.expires_at > NOW()
          AND o.status = 'approved' AND COALESCE(o.is_visible, TRUE)
    """, [_o_sgg_text])
    operator_region_rows = [dict(r) for r in cur.fetchall()]

    operator_by_category = []
    for cat in ("위탁", "청소", "세탁", "용품", "소독", "세무", "인테리어"):
        def _same_operator_category(row):
            row_cat = "위탁" if row["category"] == "위탁운영" else row["category"]
            return row_cat == cat

        picks = [
            (row, "premium")
            for row in operator_rows
            if _same_operator_category(row) and row["is_premium"]
        ][:OPERATOR_BUILDING_BADGE_SLOT_CAP]
        picked_ids = {row["id"] for row, _tier in picks}
        for row in operator_region_rows:
            if len(picks) >= OPERATOR_BUILDING_BADGE_SLOT_CAP:
                break
            if _same_operator_category(row) and row["id"] not in picked_ids:
                picks.append((row, "region"))
                picked_ids.add(row["id"])
        if not picks:
            operator_by_category.append({
                "category": cat, "company_name": None, "subdomain_slug": None,
                "phone": None, "tier": None,
            })
            continue
        for pick, tier in picks:
            operator_by_category.append({
                "category": cat,
                "company_name": pick["company_name"],
                "subdomain_slug": pick["subdomain_slug"],
                "phone": pick["phone"],
                "tier": tier,
            })

    # 담당 대출상담사 — 활성 단지뱃지 2명을 먼저 노출하고, 빈 자리는 지역 매칭으로 채운다.
    sgg_cd = str(building.get("sgg_cd") or "")
    prov_prefix = sgg_cd[:2]
    prov_nm = _PROV_SGG_MAP.get(prov_prefix)
    region_match = ["전국"]
    if prov_prefix in _SUDO_PREFIXES:
        region_match.append("수도권")
    if prov_nm:
        region_match.append(prov_nm)
    loan_consultant_rows = []
    cur.execute("""
        SELECT lc.id, lc.office_name, lc.owner_name, lc.phone, lc.subdomain_slug,
               lc.logo_url, lc.intro_text, lc.consultant_products,
               lc.kakao_chat_url, lc.license_number, lc.service_region
        FROM loan_consultant_buildings lcb
        JOIN loan_consultants lc ON lc.id = lcb.loan_consultant_id
        WHERE lcb.master_building_id = %s
          AND lcb.has_priority_badge
          AND (lcb.premium_expires_at IS NULL OR lcb.premium_expires_at > NOW())
          AND lc.status = 'approved'
          AND COALESCE(lc.is_visible, TRUE)
        ORDER BY RANDOM()
        LIMIT %s
    """, [building_id, LOAN_BUILDING_BADGE_SLOT_CAP])
    for r in cur.fetchall():
        d = dict(r)
        d["logo_src"] = f"/api/partners/loan-consultant-logo/{d['id']}" if d.pop("logo_url", None) else None
        d["registered"] = True
        loan_consultant_rows.append(d)

    cur.execute("""
        SELECT * FROM (
            SELECT DISTINCT lc.id, lc.office_name, lc.owner_name, lc.phone, lc.subdomain_slug,
                   lc.logo_url, lc.intro_text, lc.consultant_products,
                   lc.kakao_chat_url, lc.license_number, lc.service_region
            FROM loan_consultant_service_areas lsa
            JOIN loan_consultants lc ON lc.id = lsa.loan_consultant_id
            WHERE lsa.region_name = ANY(%s)
              AND lc.status = 'approved'
              AND COALESCE(lc.is_visible, TRUE)
              AND lc.id NOT IN %s
        ) sub
        ORDER BY RANDOM()
        LIMIT %s
    """, [
        region_match,
        tuple(row["id"] for row in loan_consultant_rows) or (-1,),
        max(0, 3 - len(loan_consultant_rows)),
    ])
    for r in cur.fetchall():
        d = dict(r)
        d["logo_src"] = f"/api/partners/loan-consultant-logo/{d['id']}" if d.pop("logo_url", None) else None
        d["registered"] = False
        loan_consultant_rows.append(d)

    # 숙박업 영업신고(행안부) — 이 건물 주소(도로명+건물번호 정규화)로 매칭된 '영업/정상' 사업장.
    # 정렬: 등록 운영업체(operators approved+노출중)와 상호가 매칭되면 priority_score DESC 우선 →
    #       그 안/미등록끼리는 매번 랜덤. 신고율 = 영업/정상 객실수 합 / 총 세대수(units).
    lodgings = []
    lodging_room_total = 0
    try:
        lr_rows, _ = matched_lodgings(cur, building, active_only=True)
        if lr_rows:
            op_map = {}
            if lr_rows:
                # 상호 정규화명 → 등록 운영업체(노출중, priority 최고) 매핑
                cur.execute("""
                    SELECT o.company_name, o.subdomain_slug,
                           COALESCE(o.priority_score, 0) AS priority_score
                    FROM operators o
                    WHERE o.status = 'approved' AND COALESCE(o.is_visible, TRUE)
                """)
                for o in cur.fetchall():
                    norm = addr_norm.normalize_name(o["company_name"])
                    if norm and (norm not in op_map
                                 or o["priority_score"] > op_map[norm]["priority_score"]):
                        op_map[norm] = dict(o)
            import random as _random
            for r in lr_rows:
                d = dict(r)
                norm = d.pop("biz_name_norm", None) or addr_norm.normalize_name(d["biz_name"])
                op = op_map.get(norm) if norm else None
                d["registered"] = op is not None
                d["operator_slug"] = op["subdomain_slug"] if op else None
                d["_prio"] = op["priority_score"] if op else -1
                d["_rand"] = _random.random()
                lodging_room_total += int(d.get("room_count") or 0)
                lodgings.append(d)
            # 등록 운영업체(priority DESC) 최상단 → 나머지는 매번 랜덤
            lodgings.sort(key=lambda d: (-int(d["registered"]), -d["_prio"], d["_rand"]))
            for d in lodgings:
                d.pop("_prio", None)
                d.pop("_rand", None)
    except Exception:
        app.logger.exception("영업신고 매칭 실패 (building_id=%s)", building_id)
        lodgings = []
        lodging_room_total = 0

    # 승인된 OTA 예약 링크 전체 (다건 지원 — booking_url_requests 기반)
    cur.execute("""
        SELECT bur.booking_url, o.company_name, o.subdomain_slug
        FROM booking_url_requests bur
        JOIN operators o ON o.id = bur.operator_id
        WHERE bur.master_building_id = %s
          AND bur.status = 'approved'
          AND (bur.expires_at IS NULL OR bur.expires_at > NOW())
          AND bur.booking_url IS NOT NULL
          AND bur.booking_url ~ '^https?://'
        ORDER BY bur.reviewed_at DESC NULLS LAST
    """, [building_id])
    _booking_urls = []
    import datetime as _dt2
    for _bur in cur.fetchall():
        _url = _bur["booking_url"]
        _dom = _url.lower().split("/")[2] if "//" in _url else ""
        if "yanolja" in _dom:
            _plat = "야놀자"
        elif "yeogi" in _dom:
            _plat = "여기어때"
        elif "airbnb" in _dom:
            _plat = "에어비앤비"
        elif "booking.com" in _dom:
            _plat = "부킹닷컴"
        else:
            _plat = "예약"
        _booking_urls.append({"url": _url, "platform": _plat, "company_name": _bur["company_name"]})

    # 이 건물의 공개 직거래 매물 목록 (deal_mode='direct', withdrawn 아닌 것)
    cur.execute("""
        SELECT lr.id, lr.deal_type, lr.desired_price, lr.price_krw, lr.price_krw_max,
               lr.monthly_rent_krw, lr.room_count, lr.area_sqm, lr.verified_phone,
               lr.description, lr.yield_rate,
                lr.deal_mode, lr.display_seq, lr.registrant_type, lr.transaction_target,
                lr.succession_loan_krw, lr.key_money_krw, lr.monthly_revenue_krw,
                 lr.annual_revenue_krw, lr.short_stay_ratio, lr.ota_revenue_ratio,
                 lr.matched_permit_number, lr.operation_status, lr.closed_at,
                lr.remodeling_info, lr.is_urgent, lr.disclosure_scope, lr.building_info_overrides,
               CASE
                   WHEN lr.registrant_type = 'business'
                    AND lr.deal_type IN ('월세', '단기임대')
                    AND vacant_long_stay.has_room
                   THEN lr.price_krw
               END AS room_price_min,
               CASE
                   WHEN lr.registrant_type = 'business'
                    AND lr.deal_type IN ('월세', '단기임대')
                    AND vacant_long_stay.has_room
                   THEN COALESCE(lr.price_krw_max, lr.price_krw)
               END AS room_price_max,
               TO_CHAR(COALESCE(lr.updated_at, lr.created_at), 'YYYY-MM-DD') AS listing_date,
                COALESCE(ll.like_count, 0) AS like_count,
                 COALESCE(pv.viewer_count, 0) AS viewer_count,
                 recent_tx.price AS latest_transaction_price
        FROM listing_requests lr
        JOIN master_buildings urgent_mb ON urgent_mb.id = lr.master_building_id
        LEFT JOIN LATERAL (
            SELECT TRUE AS has_room
            FROM business_room_inventory bri
            WHERE bri.listing_request_id = lr.id
              AND bri.status = '공실'
              AND bri.channel = '장박가능'
            LIMIT 1
        ) vacant_long_stay ON TRUE
        LEFT JOIN (
            SELECT listing_request_id, COUNT(*) AS like_count
            FROM listing_likes GROUP BY listing_request_id
        ) ll ON ll.listing_request_id = lr.id
        LEFT JOIN (
            SELECT listing_request_id, COUNT(DISTINCT ip_hash) AS viewer_count
            FROM page_views
            WHERE listing_request_id IS NOT NULL
              AND viewed_at >= NOW() - INTERVAL '5 minutes'
            GROUP BY listing_request_id
        ) pv ON pv.listing_request_id = lr.id
        LEFT JOIN LATERAL (
            SELECT t.price
            FROM transactions t
            WHERE t.sgg_cd = urgent_mb.sgg_cd
              AND t.umd_nm = urgent_mb.umd_nm
              AND t.jibun = urgent_mb.jibun
              AND t.price IS NOT NULL
              AND t.price > 0
            ORDER BY t.deal_date DESC NULLS LAST, t.id DESC
            LIMIT 1
        ) recent_tx ON TRUE
        WHERE lr.master_building_id = %s
          AND lr.deal_mode = 'direct'
          AND COALESCE(lr.status, '') NOT IN ('withdrawn', '철회됨', '보류')
          AND NOT (
              COALESCE(lr.transaction_target, 'unit') = 'whole'
              AND COALESCE(lr.disclosure_scope, 'limited') = 'limited'
          )
        ORDER BY COALESCE(lr.updated_at, lr.created_at) DESC
        LIMIT 10
    """, [building_id])
    _direct_listings = []
    for _lr in cur.fetchall():
        _d = _apply_urgent_tier(_apply_public_business_listing_summary(
            dict(_lr), financial_details_visible=bool(session.get("user_id"))
        ))
        # 전화번호 마스킹 — 뒤 4자리만 노출
        _phone = _d.pop("verified_phone", None) or ""
        _d["phone_tail"] = _phone[-4:] if len(_phone) >= 4 else ""
        if _d.get("yield_rate") is not None:
            _d["yield_rate"] = float(_d["yield_rate"])
        _d["listing_number"] = format_listing_number(_d.pop("deal_mode", "direct"), _d.pop("display_seq", None))
        _direct_listings.append(_d)
    # 매물별 사진 (최대 5장, sort_order 순)
    if _direct_listings:
        _lr_ids = [d["id"] for d in _direct_listings]
        _id_ph = ",".join(["%s"] * len(_lr_ids))
        cur.execute(f"""
            SELECT listing_request_id, image_key
            FROM listing_photos
            WHERE listing_request_id IN ({_id_ph})
              AND COALESCE(is_public, TRUE)
            ORDER BY listing_request_id, sort_order, id
        """, _lr_ids)
        _photos_by_lr: dict = {}
        for _pr in cur.fetchall():
            _lrid = _pr["listing_request_id"]
            _photos_by_lr.setdefault(_lrid, []).append(
                f"/api/listing-photos/img/{_pr['image_key']}"
            )
        for _d in _direct_listings:
            _d["photos"] = _photos_by_lr.get(_d["id"], [])
            _d["liked"] = False
        _viewer = session.get("user") or {}
        if _viewer.get("id"):
            cur.execute(
                "SELECT listing_request_id FROM listing_likes "
                "WHERE user_id=%s AND listing_request_id = ANY(%s)",
                [_viewer["id"], _lr_ids],
            )
            _liked_listing_ids = {row["listing_request_id"] for row in cur.fetchall()}
            for _d in _direct_listings:
                _d["liked"] = _d["id"] in _liked_listing_ids

    # 전유부 통계 (평형별 호실수) — 캐시에 데이터가 있을 때만 집계
    cur.execute("""
        SELECT area_sqm, COUNT(*) AS ho_cnt
        FROM building_unit_areas
        WHERE master_building_id = %s AND area_sqm IS NOT NULL
        GROUP BY area_sqm ORDER BY area_sqm
    """, [building_id])
    _unit_area_stats = [
        {"area_sqm": float(r["area_sqm"]), "ho_cnt": int(r["ho_cnt"])}
        for r in cur.fetchall()
    ]

    cur.close()
    conn.close()

    result = building
    agents_list = []
    for r in agent_rows:
        agent_d = dict(r)
        # 스토리지 키는 노출하지 않고, 사진이 있으면 공개 프록시 URL만 내려준다.
        agent_d["photo_src"] = f"/api/partners/agent-photo/{agent_d['id']}" if agent_d.pop("photo_url", None) else None
        agents_list.append(agent_d)
    result["agents"] = agents_list
    # 하위호환: 단일 agent를 쓰던 기존 코드용 (첫 번째 = 최우선 노출)
    result["agent"] = agents_list[0] if agents_list else None
    more_agents_list = []
    for r in more_agent_rows:
        agent_d = dict(r)
        agent_d["photo_src"] = f"/api/partners/agent-photo/{agent_d['id']}" if agent_d.pop("photo_url", None) else None
        more_agents_list.append(agent_d)
    result["more_agents"] = more_agents_list
    result["operators"] = operator_rows
    result["operator_by_category"] = operator_by_category
    result["loan_consultants"] = loan_consultant_rows
    # B화면 행정 카드용: 영업/정상 영업신고 목록 + 지표.
    # 일반숙박은 건축물대장 호실수와 실제 객실수가 비교 대상이 아니므로
    # 신고율 대신 영업신고 객실수·활성 사업장 수를 내려준다.
    result["lodgings"] = lodgings
    result["lodging_room_total"] = lodging_room_total  # 영업신고 목록의 객실수 합계 (행정 카드 목록 표시용)
    result["lodging_active_business_count"] = len(lodgings)
    result["building_name_auto"] = (
        result.get("building_name_source") == "lodging_report"
    )
    result["building_name_auto_representative"] = (
        result["building_name_auto"]
        and int(result.get("building_name_candidate_count") or 0) > 1
    )
    result["lodging_metric"] = (
        "report_rate" if uses_lodging_report_rate(result.get("lodging_type")) else "room_count"
    )
    units    = result.get("units")          # master_buildings.units — 총 호실(단일 소스)
    reported = result.get("lodging_room_total")  # 행안부 기준 실시간 영업신고호실 (폐업 제외)
    # biz_units_snapshot_legacy(엑셀 스냅샷)은 참고용으로만 보관한다.
    # 영업신고호실은 아래 lodging_registry 실시간 집계만 사용한다.
    result["lodging_report_rate"] = (
        round(reported * 100.0 / units, 1)
        if (uses_lodging_report_rate(result.get("lodging_type")) and units and reported is not None)
        else None
    )
    result["lodging_unreported"] = (
        (units - reported)
        if (uses_lodging_report_rate(result.get("lodging_type"))
            and units is not None and reported is not None)
        else None
    )
    # 총주차대수: 자주식(옥내+옥외) + 기계식(옥내+옥외) — 기존 4개 컬럼 합산, 표시 시점만 계산
    ia = result.get("indr_auto_utcnt"); oa = result.get("oudr_auto_utcnt")
    im = result.get("indr_mech_utcnt"); om = result.get("oudr_mech_utcnt")
    auto_p = ((ia or 0) + (oa or 0)) if (ia is not None or oa is not None) else None
    mech_p = ((im or 0) + (om or 0)) if (im is not None or om is not None) else None
    result["auto_pkng_cnt"]  = auto_p   # 자주식 합계
    result["mech_pkng_cnt"]  = mech_p   # 기계식 합계
    result["total_pkng_cnt"] = (
        (auto_p or 0) + (mech_p or 0)
        if (auto_p is not None or mech_p is not None) else None
    )

    # 담당부처/연락처: sgg_text를 지자체 담당부서 인덱스와 매칭.
    #   source='exact'(시군구 전용) | 'fallback'(시도 대표) → 화면에서 "(시/도 대표)" 꼬리표 판단용.
    #   매칭 실패면 dept=phone=None → 화면은 "확인중" 유지.
    #   매칭/인덱스 조회가 어떤 이유로 실패해도 건물 상세 전체가 죽지 않도록 방어(담당부처만 확인중).
    try:
        dept, phone, source = match_authority_contact(result.get("sgg_text"), get_authority_index())
    except Exception:
        app.logger.exception("담당부서 매칭 실패 (building_id=%s)", building_id)
        dept, phone, source = None, None, None
    result["authority_dept"] = dept
    result["authority_phone"] = phone
    result["authority_source"] = source if dept is not None else None
    # booking_url: javascript:/data: 등 위험 스킴 차단 + 만료 체크
    raw_bu = (result.get("booking_url") or "").strip()
    valid_bu = raw_bu if raw_bu.lower().startswith(("http://", "https://")) else None
    expires_at = result.get("booking_url_expires_at")
    import datetime as _dt
    if valid_bu and expires_at and expires_at < _dt.datetime.utcnow():
        valid_bu = None  # 만료된 운영업체 신청 링크는 미확인으로 표시
    result["booking_url"] = valid_bu
    result.pop("booking_url_expires_at", None)  # 내부값, 클라이언트 불필요
    result["booking_urls"] = _booking_urls       # OTA 다건 지원
    result["direct_listings"] = _direct_listings  # 직거래 공개 매물
    result["unit_area_stats"] = _unit_area_stats  # 평형별 호실수
    result["unit_area_sqms"] = [s["area_sqm"] for s in _unit_area_stats]  # 필터/콤보용
    return jsonify(result)


def _bg_populate_unit_areas(building_id: int) -> None:
    """area-types 폴백 시 백그라운드 daemon 스레드에서 전유부 데이터를 직접 fetch해 캐싱.

    이 함수 자체가 daemon thread에서 실행되므로 fetch_expos_area를 직접 호출한다.
    (중첩 daemon thread는 불필요하며 오히려 결과 미수신 원인이 됨)
    실제 API 결과가 없을 때만 sentinel 삽입 — 예외 발생 시는 삽입 안 해 재시도 허용.
    """
    import building_registry as br
    conn2 = None
    try:
        conn2 = get_conn()
        cur2 = conn2.cursor()
        # 7일 이내 캐시 행이 이미 있으면 skip
        cur2.execute("""
            SELECT 1 FROM building_unit_areas
            WHERE master_building_id = %s
              AND fetched_at > NOW() - INTERVAL '7 days'
            LIMIT 1
        """, [building_id])
        if cur2.fetchone():
            return
        # 위치 정보 조회
        cur2.execute(
            "SELECT sgg_cd, umd_nm, jibun FROM master_buildings WHERE id = %s",
            [building_id]
        )
        mb = cur2.fetchone()
        if not mb or not mb["sgg_cd"] or not mb["jibun"]:
            return
        bjd = _get_bjdong_map().find_bjdong_cd(mb["sgg_cd"], mb["umd_nm"])
        if not bjd:
            return
        plat_gb, bun, ji = parse_jibun(mb["jibun"])
        # daemon thread 안이므로 직접 호출 (blocking OK, gunicorn worker와 무관)
        raw = br.fetch_expos_area(mb["sgg_cd"], bjd, plat_gb, bun, ji) or []
        # DB 저장
        cur2.execute("DELETE FROM building_unit_areas WHERE master_building_id = %s", [building_id])
        if raw:
            execute_values(cur2,
                "INSERT INTO building_unit_areas (master_building_id, ho, area_sqm) VALUES %s",
                [(building_id, ho, sqm) for ho, sqm in raw]
            )
        else:
            # API 정상 응답인데 데이터가 없음 → sentinel (7일 재시도 차단)
            cur2.execute(
                "INSERT INTO building_unit_areas (master_building_id, ho, area_sqm) VALUES (%s, NULL, NULL)",
                [building_id]
            )
        conn2.commit()
    except Exception:
        try:
            if conn2: conn2.rollback()
        except Exception:
            pass
    finally:
        try:
            if conn2: conn2.close()
        except Exception:
            pass


@app.route("/api/building/<int:building_id>/area-types")
def get_building_area_types(building_id):
    """전용면적 타입 목록 — 순수 DB 조회 (외부 API 없음, 빠름).

    1차: building_unit_areas 캐시 → area_sqm별 호실수(ho_cnt) 포함
    2차: transactions DISTINCT area 폴백 (ho_cnt=null)
         + 백그라운드에서 전유부 캐시를 채워 다음번 호출엔 ho_cnt 표시
    반환: items=[{sqm, ho_cnt|null}], sqms=[...] (하위호환)
    """
    import threading as _threading
    conn = get_conn(); cur = conn.cursor()
    try:
        cur.execute("""
            SELECT area_sqm, COUNT(*) AS ho_cnt
            FROM building_unit_areas
            WHERE master_building_id = %s AND area_sqm IS NOT NULL
            GROUP BY area_sqm ORDER BY area_sqm
        """, [building_id])
        rows = cur.fetchall()
        items = [{"sqm": float(r["area_sqm"]), "ho_cnt": int(r["ho_cnt"])} for r in rows]

        if not items:
            cur.execute("""
                SELECT building_name, sgg_cd, umd_nm, jibun
                FROM master_buildings WHERE id = %s
            """, [building_id])
            mb = cur.fetchone()
            if mb and mb["sgg_cd"] and mb["umd_nm"] and mb["jibun"]:
                cur.execute("""
                    SELECT DISTINCT ROUND(area::numeric, 1) AS a
                    FROM transactions
                    WHERE sgg_cd = %s AND umd_nm = %s AND jibun = %s
                      AND area IS NOT NULL AND area > 0
                    ORDER BY a LIMIT 30
                """, [mb["sgg_cd"], mb["umd_nm"], mb["jibun"]])
                items = [{"sqm": float(r["a"]), "ho_cnt": None} for r in cur.fetchall()]
            elif mb:
                name = ((mb.get("building_name") or "")).strip()
                if name and name != "-":
                    cur.execute("""
                        SELECT DISTINCT ROUND(area::numeric, 1) AS a
                        FROM transactions
                        WHERE building_name = %s AND area IS NOT NULL AND area > 0
                        ORDER BY a LIMIT 30
                    """, [name])
                    items = [{"sqm": float(r["a"]), "ho_cnt": None} for r in cur.fetchall()]

            # building_unit_areas가 비어 있음 → 백그라운드에서 자동 채우기
            # (다음번 area-types 호출 때 ho_cnt 표시)
            _threading.Thread(
                target=_bg_populate_unit_areas,
                args=(building_id,),
                daemon=True
            ).start()

        return jsonify({"ok": True, "items": items, "sqms": [x["sqm"] for x in items]})
    except Exception as e:
        app.logger.exception("area-types 오류 building_id=%s", building_id)
        return jsonify({"ok": False, "items": [], "sqms": []})
    finally:
        cur.close(); conn.close()


@app.route("/api/building/<int:building_id>/lodging-summary")
@limiter.limit("60 per minute")
def get_building_lodging_summary(building_id):
    """사업주 매물등록용 활성 숙박업 대표 신고 정보.

    자동명명과 같은 도로명 우선·지번 보조 주소 매칭 및 대표 선정 규칙을
    재사용한다. 매칭되지 않아도 등록 자체는 가능하도록 빈 정보로 응답한다.
    """
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute("""
            SELECT id, road_address, jibun_address, sgg_text, umd_nm, jibun
            FROM master_buildings
            WHERE id = %s
        """, [building_id])
        building = cur.fetchone()
        if not building:
            return jsonify({"ok": False, "message": "등록되지 않은 건물입니다."}), 404
        rows, match_source = matched_lodgings(cur, dict(building), active_only=True)
        representative = choose_representative(rows)
        if not representative:
            return jsonify({
                "ok": True, "matched": False, "room_count": None,
                "business_name": None, "match_source": None,
            })
        room_count = representative.get("room_count")
        return jsonify({
            "ok": True,
            "matched": room_count is not None,
            "room_count": int(room_count) if room_count is not None else None,
            "business_name": representative.get("biz_name") or None,
            "match_source": match_source,
        })
    except Exception:
        app.logger.exception("lodging-summary 오류 building_id=%s", building_id)
        return jsonify({"ok": False, "matched": False, "room_count": None}), 500
    finally:
        cur.close()
        conn.close()


@app.route("/api/building/<int:building_id>/unit-areas")
def get_building_unit_areas(building_id):
    """전유부(호실별 전용면적) 온디맨드 조회 + DB 캐싱.

    캐시(7일): 있으면 즉시 반환, 없으면 건축HUB API 조회 후 저장.
    실패 시 areas:[] 반환 — 매물등록 자체는 막지 않음.
    """
    conn = get_conn(); cur = conn.cursor()
    try:
        # 캐시 확인 (7일 이내 fetched_at이 있는 행)
        cur.execute("""
            SELECT ho, area_sqm FROM building_unit_areas
            WHERE master_building_id = %s
              AND fetched_at > NOW() - INTERVAL '7 days'
            ORDER BY area_sqm NULLS LAST, ho
            LIMIT 500
        """, [building_id])
        cached = cur.fetchall()
        if cached:
            areas = [
                {"ho": r["ho"], "area_sqm": float(r["area_sqm"])}
                for r in cached if r["area_sqm"] is not None
            ]
            return jsonify({"ok": True, "areas": areas, "from_cache": True})

        # 건물 위치 정보 조회
        cur.execute("""
            SELECT sgg_cd, umd_nm, jibun FROM master_buildings WHERE id = %s
        """, [building_id])
        mb = cur.fetchone()
        if not mb or not mb["sgg_cd"] or not mb["jibun"]:
            return jsonify({"ok": True, "areas": [], "reason": "no_location"})

        bjd = _get_bjdong_map().find_bjdong_cd(mb["sgg_cd"], mb["umd_nm"])
        if not bjd:
            return jsonify({"ok": True, "areas": [], "reason": "no_bjdong"})

        plat_gb, bun, ji = parse_jibun(mb["jibun"])
        import building_registry as br
        import threading as _threading
        # fetch_expos_area 내부 _RETRY_MAX(2)×timeout(15s)=45s blocking 가능
        # → daemon thread + Event 20s cap.  daemon=True이므로 timeout 후 gunicorn은
        #   즉시 응답; 백그라운드 스레드는 OS가 정리(worker를 block하지 않음).
        # ThreadPoolExecutor.__exit__ 은 내부 스레드가 끝날 때까지 block하므로 사용불가.
        _result_box = [None]
        _done_evt   = _threading.Event()
        def _bg_fetch():
            try:
                _result_box[0] = br.fetch_expos_area(mb["sgg_cd"], bjd, plat_gb, bun, ji)
            except Exception:
                pass
            finally:
                _done_evt.set()
        _t = _threading.Thread(target=_bg_fetch, daemon=True)
        _t.start()
        _done_evt.wait(timeout=20)
        raw = _result_box[0] or []

        # DB 캐싱 (기존 캐시 교체 후 신규 삽입)
        cur.execute("DELETE FROM building_unit_areas WHERE master_building_id = %s", [building_id])
        if raw:
            execute_values(cur,
                "INSERT INTO building_unit_areas (master_building_id, ho, area_sqm) VALUES %s",
                [(building_id, ho, sqm) for ho, sqm in raw]
            )
        else:
            # API 결과 없음 — sentinel 행을 삽입해 7일간 재호출 방지
            cur.execute(
                "INSERT INTO building_unit_areas (master_building_id, ho, area_sqm) VALUES (%s, NULL, NULL)",
                [building_id]
            )
        conn.commit()

        areas = [{"ho": ho, "area_sqm": float(sqm)} for ho, sqm in raw]
        return jsonify({"ok": True, "areas": areas, "from_cache": False})
    except Exception as e:
        app.logger.exception("unit-areas 조회 오류 building_id=%s", building_id)
        try: conn.rollback()
        except Exception: pass
        return jsonify({"ok": False, "areas": [], "error": str(e)})
    finally:
        cur.close(); conn.close()


# ── 상거래정보(주변 상가업소) ───────────────────────────────────────────
# 법정동코드 매핑은 zip 로딩이 무거워서 앱 프로세스당 1회만 lazy 로딩한다.
_bjdong_map = None
_bjdong_lock = threading.Lock()


def _to_int(v):
    if v is None or str(v).strip() == "":
        return None
    try:
        return int(float(str(v).replace(",", "").strip()))
    except (ValueError, TypeError):
        return None


def _to_float(v):
    if v is None or str(v).strip() == "":
        return None
    try:
        return float(str(v).replace(",", "").strip())
    except (ValueError, TypeError):
        return None


def _fmt_date(v):
    """'20231130' → '2023-11-30'. 형식이 다르면 원문 그대로(공백은 None)."""
    if v is None:
        return None
    s = str(v).strip()
    if not s:
        return None
    if len(s) == 8 and s.isdigit():
        return f"{s[0:4]}-{s[4:6]}-{s[6:8]}"
    return s


def _get_bjdong_map():
    global _bjdong_map
    if _bjdong_map is None:
        with _bjdong_lock:
            if _bjdong_map is None:
                _bjdong_map = BjdongMap(os.environ.get("BJDONG_CODE_CSV", "법정동코드_전체자료.zip"))
    return _bjdong_map


# 건물별 상가업소 결과 1시간 메모리 캐시 — 같은 건물 반복 조회 시 외부 API 호출 절약.
# (gunicorn 워커별 캐시. 정확성보다 호출량 절감 목적이라 워커 간 공유 안 해도 충분)
_STORES_CACHE_TTL = 3600
_STORES_CACHE_TTL_EMPTY = 300  # 실패/0건은 일시 장애일 수 있어 5분만 캐시(곧 재시도)
_stores_cache = {}
_stores_cache_lock = threading.Lock()

# 상가정보 API(STORE_INFO_SERVICE_KEY) 일일 한도 분리 카운터
# data.go.kr 총 한도 10,000건을 배치/실시간으로 나눠 실시간 조회를 항상 보호한다.
# ┌──────────────────────────────────────────────┐
# │  총 10,000  = 실시간 4,000  +  배치 6,000   │
# └──────────────────────────────────────────────┘
STORE_DAILY_CALLS_REALTIME_KEY = "store_daily_calls_realtime"  # app_meta 키
STORE_DAILY_CALLS_BATCH_KEY    = "store_daily_calls_batch"     # app_meta 키
_STORE_REALTIME_DAILY_CAP      = 4_000   # 실시간 전용 일일 쿼터
_STORE_BATCH_DAILY_CAP         = 6_000   # 배치 최대 일일 쿼터 (sync_stores.py 참조용)


def _stores_result_from_rows(db_rows):
    """building_stores DB 행 목록 → /nearby-stores 응답 dict."""
    if not db_rows:
        return None
    counts = {}
    stores = []
    for r in db_rows:
        name = r["store_name"] or ""
        cat  = r["category"] or "기타"
        flr  = r["floor"] or ""
        counts[cat] = counts.get(cat, 0) + 1
        stores.append({"name": name, "category": cat, "floor": flr})

    def _floor_sort_key(s):
        try:
            return (0, int(s["floor"]))
        except (ValueError, TypeError):
            return (1, 0)

    stores_sorted = sorted(stores, key=_floor_sort_key)
    categories = sorted(counts.items(), key=lambda kv: -kv[1])
    return {
        "available": True,
        "total": len(stores),
        "categories": [{"category": c, "count": n} for c, n in categories],
        "stores": stores_sorted,
    }


def _store_rt_check_and_count():
    """실시간 상가조회 카운터를 원자적으로 1 증가시키고 한도 초과 여부를 반환.

    Returns (new_count: int, over_limit: bool).
    DB 오류 시 over_limit=False(통과 허용) — DB 장애로 사용자 차단하는 것보다 API 호출을 허용.
    카운터 형식: app_meta[STORE_DAILY_CALLS_REALTIME_KEY] = {"date": "YYYY-MM-DD", "count": N}
    """
    today_str = datetime.now().strftime("%Y-%m-%d")
    fresh_val = json.dumps({"date": today_str, "count": 1}, ensure_ascii=False)
    try:
        conn = get_conn()
        cur  = conn.cursor()
        try:
            cur.execute("""
                INSERT INTO app_meta (key, value, updated_at) VALUES (%s, %s, NOW())
                ON CONFLICT (key) DO UPDATE
                  SET value = CASE
                        WHEN (app_meta.value::jsonb ->> 'date') = %s
                        THEN jsonb_set(app_meta.value::jsonb, '{count}',
                                       to_jsonb((COALESCE(app_meta.value::jsonb->>'count','0'))::int + 1))
                        ELSE %s::jsonb
                      END,
                      updated_at = NOW()
                RETURNING value
            """, (STORE_DAILY_CALLS_REALTIME_KEY, fresh_val, today_str, fresh_val))
            row = cur.fetchone()
            conn.commit()
            count = int(json.loads(row["value"]).get("count", 1)) if row else 1
        finally:
            cur.close()
            conn.close()
    except Exception:
        app.logger.exception("실시간 상가 카운터 증가 실패 — 통과 허용")
        return 1, False
    return count, count > _STORE_REALTIME_DAILY_CAP


@app.route("/api/building/<int:building_id>/nearby-stores")
@limiter.limit("60 per minute")
def get_building_nearby_stores(building_id):
    """이 건물(지번, PNU 기준)의 상가업소 목록 — 업종별 개수 + 층별 목록.

    1차: building_stores 테이블 즉시 조회 (sync_stores.py 사전 수집 데이터)
    2차: 캐시 미스 시 즉시 {"available": false, "pending": true} 를 반환하고
         백그라운드 스레드가 외부 API(data.go.kr)를 조회한 뒤 캐시를 채우며
         결과를 building_stores에도 저장한다.
    프론트(loadBuildingStores)는 pending:true 시 4초 간격 최대 4회 재조회.
    """
    # 1차: building_stores DB 캐시
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            "SELECT store_name, category, floor, ho_no, inds_mcls_nm, inds_scls_nm "
            "FROM building_stores WHERE master_building_id = %s ORDER BY ho_no NULLS LAST, id",
            [building_id],
        )
        db_rows = cur.fetchall()
    finally:
        cur.close()
        conn.close()

    if db_rows:
        result = _stores_result_from_rows(db_rows)
        if result:
            with _stores_cache_lock:
                _stores_cache[building_id] = (time.time(), result)
            return jsonify(result)

    # 2차: 메모리 캐시 확인
    now = time.time()
    with _stores_cache_lock:
        hit = _stores_cache.get(building_id)
        if hit:
            ts, payload = hit
            if payload.get("pending"):
                return jsonify({"available": False, "pending": True})
            ttl = _STORES_CACHE_TTL if payload.get("available") else _STORES_CACHE_TTL_EMPTY
            if now - ts < ttl:
                return jsonify(payload)

    # 건물 기본정보 조회
    conn = get_conn()
    cur = conn.cursor()
    cur.execute(
        "SELECT sgg_cd, umd_nm, jibun FROM master_buildings WHERE id = %s",
        [building_id],
    )
    row = cur.fetchone()
    cur.close()
    conn.close()
    if not row:
        return jsonify({"error": "not found"}), 404

    # pending 마크 후 백그라운드 스레드 기동 — 중복 기동 방지(pending이 이미 있으면 skip)
    with _stores_cache_lock:
        existing = _stores_cache.get(building_id)
        if existing and existing[1].get("pending"):
            return jsonify({"available": False, "pending": True})
        _stores_cache[building_id] = (now, {"available": False, "pending": True,
                                            "total": 0, "categories": [], "stores": []})

    def _bg_fetch(bld_id, r):
        result = {"available": False, "total": 0, "categories": [], "stores": []}
        fetched_stores = None
        try:
            # 서비스키 없음 — 가장 흔한 원인이므로 먼저 확인
            if not os.environ.get("STORE_INFO_SERVICE_KEY", "").strip():
                result["reason"] = "no_service_key"
            elif not (r["sgg_cd"] and r["umd_nm"] and r["jibun"]):
                result["reason"] = "no_bjdong_match"
            else:
                bjd = _get_bjdong_map().find_bjdong_cd(r["sgg_cd"], r["umd_nm"])
                if not bjd:
                    result["reason"] = "no_bjdong_match"
                else:
                    plat_gb, bun, ji = parse_jibun(r["jibun"])
                    pnu = build_pnu(r["sgg_cd"], bjd, plat_gb, bun, ji)
                    if not pnu:
                        stores = []
                    else:
                        # 실시간 일일쿼터 확인: 한도 초과 시 API 호출 없이 즉시 반환
                        rt_count, rt_over = _store_rt_check_and_count()
                        if rt_over:
                            result["reason"] = "realtime_daily_limit"
                            app.logger.warning(
                                "상가정보 실시간 일일한도 초과 (count=%d, cap=%d, bld_id=%s)",
                                rt_count, _STORE_REALTIME_DAILY_CAP, bld_id,
                            )
                            with _stores_cache_lock:
                                _stores_cache[bld_id] = (time.time(), result)
                            return
                        stores = get_stores_by_pnu(pnu)
                    if stores:
                        fetched_stores = stores
                        counts = {}
                        for s in stores:
                            cat = s["category"] or "기타"
                            counts[cat] = counts.get(cat, 0) + 1
                        categories = sorted(counts.items(), key=lambda kv: -kv[1])

                        def _floor_sort_key(s):
                            f = s["floor"]
                            try:
                                return (0, int(f))
                            except (ValueError, TypeError):
                                return (1, 0)

                        stores_sorted = sorted(stores, key=_floor_sort_key)
                        result = {
                            "available": True,
                            "total": len(stores),
                            "categories": [{"category": c, "count": n} for c, n in categories],
                            "stores": stores_sorted,
                        }
                    else:
                        result["reason"] = "api_error_or_empty"
        except Exception:
            app.logger.exception("상가업소 조회 실패 (building_id=%s)", bld_id)
            result["reason"] = "api_error_or_empty"
        with _stores_cache_lock:
            _stores_cache[bld_id] = (time.time(), result)
        # 실시간 조회 성공 시 building_stores에 저장 (다음 요청부터 즉시 응답)
        if fetched_stores:
            try:
                conn2 = get_conn()
                cur2 = conn2.cursor()
                try:
                    cur2.execute(
                        "DELETE FROM building_stores WHERE master_building_id = %s", [bld_id]
                    )
                    for s in fetched_stores:
                        cur2.execute(
                            """INSERT INTO building_stores
                               (master_building_id, store_name, category, floor,
                                ho_no, inds_mcls_nm, inds_scls_nm, updated_at)
                               VALUES (%s, %s, %s, %s, %s, %s, %s, NOW())""",
                            [bld_id, s.get("name", ""), s.get("category", ""), s.get("floor", ""),
                             s.get("ho_no") or None, s.get("inds_mcls_nm") or None,
                             s.get("inds_scls_nm") or None],
                        )
                    conn2.commit()
                finally:
                    cur2.close()
                    conn2.close()
            except Exception:
                app.logger.exception("building_stores 저장 실패 (building_id=%s)", bld_id)

    threading.Thread(target=_bg_fetch, args=(building_id, dict(row)), daemon=True).start()
    return jsonify({"available": False, "pending": True})


@app.route("/api/transactions")
def get_transactions():
    q = request.args.get("q", "").strip()
    si_do = request.args.get("si_do", "").strip()
    sgg_nm = request.args.get("sgg_nm", "").strip()
    umd_nm = request.args.get("umd_nm", "").strip()
    year = request.args.get("year", "").strip()
    lodging_type = request.args.get("lodging_type", "").strip()
    page = max(int(request.args.get("page", 1)), 1)
    size = min(int(request.args.get("size", 20)), 200)
    offset = (page - 1) * size

    where = ["1=1"]
    params = []

    if q:
        # address = "{umd_nm} {jibun}" 형태 — 역사적으로 umd_nm 공백 정규화 시점 차이로
        # address 내 umd_nm 부분이 현재 umd_nm 컬럼과 다를 수 있음.
        # jibun 컬럼 직접 매칭을 추가해 jibun만 입력해도 확실히 검색되도록 보완.
        # 공백 제거 후 비교(nospace) 추가 — "그레이스경희"→"더 그레이스 경희",
        # "서천동812"→"서천동 812" 등 붙여쓰기/띄어쓰기 편차 흡수.
        _q_ns = q.replace(' ', '')
        where.append(
            "(building_name ILIKE %s OR address ILIKE %s OR jibun ILIKE %s"
            " OR REPLACE(building_name,' ','') ILIKE %s OR REPLACE(address,' ','') ILIKE %s)"
        )
        params += [f"%{q}%", f"%{q}%", f"%{q}%", f"%{_q_ns}%", f"%{_q_ns}%"]
    if si_do:
        # '서울' vs '서울특별시' 표기 편차 흡수 — 지도와 동일한 코어 이름 비교 규칙 사용
        where.append(sido_match_clause("si_do"))
        params.append(sido_core(si_do))
    if sgg_nm:
        # sgg_nm은 이제 master_buildings.sgg_text 전체값(예: '경기도 수원시 팔달구').
        # transactions.sgg_nm은 시군구만 저장(예: '수원시 팔달구' 또는 '팔달구').
        # suffix LIKE: sgg_text 끝이 transactions.sgg_nm과 일치하는 행만 추출.
        # → '경기도 수원시 팔달구' LIKE '%수원시 팔달구' = TRUE ✓
        # → '경기도 수원시 팔달구' LIKE '%수원시'       = FALSE (오염 차단) ✓
        where.append("%s LIKE '%%' || sgg_nm")
        params.append(sgg_nm)
    if umd_nm:
        # transactions.umd_nm은 공백 없이 저장(예: '구좌읍김녕리') — regions API도 같은 값 반환.
        # 공백 제거 후 정규화 비교로 드롭다운 선택 값과 완전 일치 보장.
        where.append("REPLACE(umd_nm, ' ', '') = REPLACE(%s, ' ', '')")
        params.append(umd_nm)
    if year and year != "all":
        where.append("deal_date LIKE %s")
        params.append(f"{year}-%")
    if lodging_type == "복합":
        where.append("(lodging_type = '복합' OR lodging_type LIKE '%%·%%')")
    elif lodging_type == "준공전":
        where.append("building_status IN ('허가','착공') AND (use_apr_day IS NULL OR use_apr_day = '')")
    elif lodging_type == "미분류":
        where.append("(lodging_type IS NULL OR lodging_type = '') AND building_status NOT IN ('허가','착공')")
    elif lodging_type:
        where.append("lodging_type = %s")
        params.append(lodging_type)

    # 선택적 building_id → 해당 건물의 실거래만(get_buildings_geo/get_monthly_trend와 동일 전략).
    #   - 지번키(sgg_cd+umd_nm+jibun)가 모두 있으면 지번 정확 매칭(동명 건물 오염 방지)
    #   - 셋 중 하나라도 NULL이면 building_name 폴백('-'/미존재/빈값은 0매칭 처리)
    #   - 정수가 아니거나 없으면 기존 동작(q/지역/연도 등) 그대로 유지(하위호환)
    building_id = request.args.get("building_id", "").strip()
    if building_id.isdigit():
        mconn = get_conn()
        mcur = mconn.cursor()
        mcur.execute("""
            SELECT building_name, sgg_cd, umd_nm, jibun
            FROM master_buildings WHERE id = %s
        """, [int(building_id)])
        b = mcur.fetchone()
        mcur.close()
        mconn.close()
        if b and b["sgg_cd"] and b["umd_nm"] and b["jibun"]:
            where.append("sgg_cd = %s AND umd_nm = %s AND jibun = %s")
            params += [b["sgg_cd"], b["umd_nm"], b["jibun"]]
        else:
            name = (b["building_name"] if b else None) or ""
            if name and name != "-":
                where.append("building_name = %s")
                params.append(name)
            else:
                # 삭제·미존재 건물의 실거래를 의도적으로 0건 처리한다.
                # PostgreSQL TEXT에는 NUL 문자를 담을 수 없어 문자열 센티널을
                # 바인딩하는 방식도 사용하지 않는다.
                where.append("FALSE")

    # 선택적 area_sqm → 해당 전용면적 ±0.5㎡ 범위 실거래만 필터
    _area_sqm_raw = request.args.get("area_sqm", "").strip()
    if _area_sqm_raw:
        try:
            _asqm = float(_area_sqm_raw)
            where.append("area BETWEEN %s AND %s")
            params += [_asqm - 0.5, _asqm + 0.5]
        except ValueError:
            pass

    where_sql = " AND ".join(where)
    # with_total=1 이 있을 때만 COUNT(*) 실행 — 메인 위젯(size=5)은 total 불필요
    with_total = request.args.get("with_total", "").strip()

    conn = get_conn()
    cur = conn.cursor()

    if with_total:
        cur.execute(f"SELECT COUNT(*) c FROM transactions WHERE {where_sql}", params)
        total = cur.fetchone()["c"]
    else:
        total = None

    # master_building_id: 각 거래의 지번키(sgg_cd+umd_nm+jibun)로 master_buildings를
    # 역매칭(get_buildings_geo/get_monthly_trend와 동일한 지번 정확 매칭 전략).
    #   - 세 키가 모두 있고 대응 건물이 있으면 그 건물 id, 없으면 NULL.
    #   - 필터/정렬/페이지네이션(where_sql/ORDER BY/LIMIT)에는 영향 없음.
    cur.execute(f"""
        SELECT building_name, address, si_do, sgg_nm, umd_nm, jibun, sgg_cd,
               area, price, deal_date, deal_type, floor,
               lodging_type, lodging_type_detail, match_source,
               (SELECT mb.id FROM master_buildings mb
                 WHERE mb.sgg_cd = transactions.sgg_cd
                   AND mb.umd_nm = transactions.umd_nm
                   AND mb.jibun = transactions.jibun
                 ORDER BY mb.id LIMIT 1) AS master_building_id
        FROM transactions
        WHERE {where_sql}
        ORDER BY deal_date DESC, id DESC
        LIMIT %s OFFSET %s
    """, params + [size, offset])
    rows = [dict(r) for r in cur.fetchall()]
    cur.close()
    conn.close()

    return jsonify({"total": total, "page": page, "size": size, "items": rows})


# /api/buildings-geo 서버 메모리 캐시 — 필터 없는 전체 조회(약 4,700건)용 TTL 캐시.
# 키 = 필터 파라미터 문자열, 값 = (저장시각, 직렬화된 JSON 바이트)
_geo_cache: dict = {}
_GEO_CACHE_TTL = 45  # seconds

# 지도 주변정보 조회는 브라우저에 REST 키를 노출하지 않도록 서버에서만 호출한다.
_MAP_POI_CATEGORIES = {
    "education": (
        ("SC4", "학교"),
        ("AC5", "학원"),
    ),
    "convenience": (
        ("CS2", "편의점"),
        ("HP8", "병원"),
        ("PM9", "약국"),
        ("PK6", "주차장"),
    ),
}
_KAKAO_LOCAL_CATEGORY_URL = "https://dapi.kakao.com/v2/local/search/category.json"
_MAP_POI_CACHE_TTL = 30
_MAP_POI_CACHE: dict = {}
# 외부 API가 지연돼도 단일 sync worker를 길게 점유하지 않도록, 동시에 두 지도
# 요청만 외부 호출을 시작하고 카테고리는 제한된 공유 executor에서 병렬로 조회한다.
_MAP_POI_EXECUTOR = ThreadPoolExecutor(max_workers=8, thread_name_prefix="map-poi")
_MAP_POI_INFLIGHT = threading.BoundedSemaphore(2)


def _fetch_map_poi_category(client_id, category_code, lng, lat, radius):
    response = requests.get(
        _KAKAO_LOCAL_CATEGORY_URL,
        headers={"Authorization": f"KakaoAK {client_id}"},
        params={
            "category_group_code": category_code,
            "x": lng,
            "y": lat,
            "radius": radius,
            "sort": "distance",
            "size": 15,
        },
        timeout=5,
    )
    response.raise_for_status()
    return response.json().get("documents", [])


@app.route("/api/v1/m/6b4")
@limiter.limit("12 per minute")
def map_poi():
    """현재 지도 중심 주변의 교육·편의시설을 Kakao Local에서 조회한다.

    카카오 REST 키는 서버에서만 사용하고, 클라이언트에는 장소에 필요한
    표시 정보만 반환한다. category/type과 좌표를 엄격히 검증해 잘못된
    요청이나 과도한 검색 반경이 외부 API 호출로 이어지지 않게 한다.
    """
    poi_type = request.args.get("type", "").strip().lower()
    if poi_type not in _MAP_POI_CATEGORIES:
        return jsonify({
            "ok": False,
            "message": "type은 education 또는 convenience여야 합니다.",
        }), 400

    try:
        lat = float(request.args.get("lat", ""))
        lng = float(request.args.get("lng", ""))
        radius = int(request.args.get("radius", "1500"))
    except (TypeError, ValueError):
        return jsonify({
            "ok": False,
            "message": "lat, lng, radius 값을 확인해주세요.",
        }), 400
    if (
        not math.isfinite(lat) or not math.isfinite(lng)
        or not -90 <= lat <= 90
        or not -180 <= lng <= 180
        or radius < 100
        or radius > 5000
    ):
        return jsonify({
            "ok": False,
            "message": "좌표 또는 검색 반경이 올바르지 않습니다.",
        }), 400

    client_id = os.environ.get("KAKAO_REST_API_KEY", "").strip()
    if not client_id:
        app.logger.warning("[map-poi] KAKAO_REST_API_KEY 미설정")
        return jsonify({
            "ok": False,
            "message": "주변정보 기능을 사용할 수 없습니다. 카카오 API 설정을 확인해주세요.",
        }), 503

    cache_key = f"{poi_type}:{round(lat, 4)}:{round(lng, 4)}:{radius}"
    cached = _MAP_POI_CACHE.get(cache_key)
    if cached and time.time() - cached["ts"] < _MAP_POI_CACHE_TTL:
        return jsonify(cached["payload"])
    if not _MAP_POI_INFLIGHT.acquire(blocking=False):
        return jsonify({
            "ok": False,
            "message": "주변정보 요청이 많습니다. 잠시 후 다시 시도해주세요.",
        }), 503

    items = []
    seen_ids = set()
    try:
        futures = {
            _MAP_POI_EXECUTOR.submit(
                _fetch_map_poi_category,
                client_id,
                category_code,
                lng,
                lat,
                radius,
            ): category_label
            for category_code, category_label in _MAP_POI_CATEGORIES[poi_type]
        }
        completed, pending = wait(futures, timeout=2.5)
        if pending:
            for future in pending:
                future.cancel()
            app.logger.warning(
                "[map-poi] Kakao Local 응답 제한 시간 초과 (%s, %d/%d 완료)",
                poi_type,
                len(completed),
                len(futures),
            )
            return jsonify({
                "ok": False,
                "message": "주변정보를 불러오는 데 시간이 걸립니다. 잠시 후 다시 시도해주세요.",
            }), 502
        for future, category_label in futures.items():
            for document in future.result():
                place_id = str(document.get("id") or "").strip()
                if place_id and place_id in seen_ids:
                    continue
                if place_id:
                    seen_ids.add(place_id)
                try:
                    item_lng = float(document.get("x"))
                    item_lat = float(document.get("y"))
                except (TypeError, ValueError):
                    continue
                if not math.isfinite(item_lat) or not math.isfinite(item_lng):
                    continue
                items.append({
                    "id": place_id,
                    "name": str(document.get("place_name") or "").strip(),
                    "category": category_label,
                    "category_name": str(document.get("category_name") or "").strip(),
                    "address": str(document.get("road_address_name") or document.get("address_name") or "").strip(),
                    "phone": str(document.get("phone") or "").strip(),
                    "url": str(document.get("place_url") or "").strip(),
                    "lat": item_lat,
                    "lng": item_lng,
                    "distance": str(document.get("distance") or "").strip(),
                })
    except requests.RequestException as exc:
        app.logger.warning("[map-poi] Kakao Local 요청 실패: %s", str(exc)[:160])
        return jsonify({
            "ok": False,
            "message": "주변정보를 불러오지 못했습니다. 잠시 후 다시 시도해주세요.",
        }), 502
    except (ValueError, TypeError, KeyError, AttributeError):
        app.logger.warning("[map-poi] Kakao Local 응답 형식 오류", exc_info=True)
        return jsonify({
            "ok": False,
            "message": "주변정보 응답을 처리하지 못했습니다.",
        }), 502
    finally:
        _MAP_POI_INFLIGHT.release()

    items.sort(key=lambda item: (
        float(item["distance"]) if item["distance"].isdigit() else float("inf")
    ))
    payload = {
        "ok": True,
        "type": poi_type,
        "center": {"lat": lat, "lng": lng},
        "radius": radius,
        "items": items,
    }
    if len(_MAP_POI_CACHE) >= 200:
        now = time.time()
        for key, entry in list(_MAP_POI_CACHE.items()):
            if now - entry["ts"] >= _MAP_POI_CACHE_TTL:
                _MAP_POI_CACHE.pop(key, None)
    _MAP_POI_CACHE[cache_key] = {"ts": time.time(), "payload": payload}
    return jsonify(payload)

# /api/buildings-cluster 서버 메모리 TTL 캐시 — GROUP BY 집계 결과 재사용
_cluster_cache: dict = {}
_CLUSTER_CACHE_TTL = 60  # seconds


def _sido_norm_sql(col_expr: str) -> str:
    """sido 첫 토큰 약칭 → 공식 전체명 정규화 SQL CASE 식.

    sgg_text에 '서울 강남구'처럼 약칭이 들어온 경우도 클러스터 집계 시
    '서울특별시'로 통합되도록 한다. 알 수 없는 토큰은 그대로 반환.
    """
    return f"""CASE {col_expr}
        WHEN '서울' THEN '서울특별시'
        WHEN '부산' THEN '부산광역시'
        WHEN '대구' THEN '대구광역시'
        WHEN '인천' THEN '인천광역시'
        WHEN '광주' THEN '광주광역시'
        WHEN '대전' THEN '대전광역시'
        WHEN '울산' THEN '울산광역시'
        WHEN '세종' THEN '세종특별자치시'
        WHEN '경기' THEN '경기도'
        WHEN '강원' THEN '강원특별자치도'
        WHEN '충북' THEN '충청북도'
        WHEN '충남' THEN '충청남도'
        WHEN '전북' THEN '전북특별자치도'
        WHEN '전남' THEN '전라남도'
        WHEN '경북' THEN '경상북도'
        WHEN '경남' THEN '경상남도'
        WHEN '제주' THEN '제주특별자치도'
        ELSE {col_expr}
    END"""


_SIDO_DISPLAY_NAMES = {
    "서울": "서울특별시", "부산": "부산광역시", "대구": "대구광역시",
    "인천": "인천광역시", "광주": "광주광역시", "대전": "대전광역시",
    "울산": "울산광역시", "세종": "세종특별자치시", "경기": "경기도",
    "강원": "강원특별자치도", "충북": "충청북도", "충남": "충청남도",
    "전북": "전북특별자치도", "전남": "전라남도", "경북": "경상북도",
    "경남": "경상남도", "제주": "제주특별자치도",
}
_GWANGJU_JACHIGU = frozenset({"동구", "서구", "남구", "북구", "광산구"})


def _canonical_sido_name(sgg_text) -> str:
    """주소 첫 토큰을 데이터랩·지도와 같은 공식 시도명으로 표시한다."""
    parts = str(sgg_text or "").strip().split()
    if not parts:
        return ""
    first = parts[0]
    if first == "전남광주통합특별시":
        return "광주광역시" if len(parts) > 1 and parts[1] in _GWANGJU_JACHIGU else "전라남도"
    return _SIDO_DISPLAY_NAMES.get(sido_core(first), first)


@app.route("/api/buildings-cluster")
@limiter.limit("60 per minute")
def get_buildings_cluster():
    """행정구역 단위 클러스터 집계 — level=sido|sgg|umd.

    지도 줌아웃 시 개별 마커 대신 집계 배지를 표시하기 위한 데이터.
    필터(q/si_do/sgg_nm/umd_nm/lodging_type)는 /api/buildings-geo와 동일하게 지원.
    """
    level = request.args.get("level", "sido").strip()
    if level not in ("sido", "sgg", "umd"):
        return jsonify({"ok": False, "message": "level은 sido|sgg|umd 중 하나여야 합니다."}), 400

    q           = request.args.get("q", "").strip()
    si_do       = request.args.get("si_do", "").strip()
    sgg_nm      = request.args.get("sgg_nm", "").strip()
    umd_nm      = request.args.get("umd_nm", "").strip()
    lodging_type = request.args.get("lodging_type", "").strip()
    # bounds 파라미터 — sgg/umd 레벨에서 화면 범위로 집계 제한
    sw_lat = request.args.get("sw_lat", "").strip()
    sw_lng = request.args.get("sw_lng", "").strip()
    ne_lat = request.args.get("ne_lat", "").strip()
    ne_lng = request.args.get("ne_lng", "").strip()

    _cache_key = f"cluster:{level}|{q}|{si_do}|{sgg_nm}|{umd_nm}|{lodging_type}|{sw_lat},{sw_lng},{ne_lat},{ne_lng}"
    _cached = _cluster_cache.get(_cache_key)
    if _cached and (time.time() - _cached[0]) < _CLUSTER_CACHE_TTL:
        return Response(_cached[1], mimetype="application/json")

    # 클러스터 집계는 전체 등록 건물(범례와 동일 기준) — 좌표 없는 건물도 카운트에 포함.
    # 배지 위치는 좌표 있는 건물의 AVG로만 계산, 좌표 있는 건물이 하나도 없으면 배지 미표시.
    where  = ["lodging_type IS DISTINCT FROM 'mixed_use_excluded'"]
    params = []

    if q:
        # jibun 컬럼 직접 매칭 추가 — jibun_address = NULL인 건물도 지번 검색으로 발견.
        # 공백 제거 후 비교(nospace) 추가 — "그레이스경희"→"더 그레이스 경희",
        # "서천동812"→"서천동 812" 등 붙여쓰기/띄어쓰기 편차 흡수.
        _q_ns = q.replace(' ', '')
        where.append(
            "(building_name ILIKE %s OR road_address ILIKE %s OR jibun_address ILIKE %s OR jibun ILIKE %s"
            " OR REPLACE(building_name,' ','') ILIKE %s OR REPLACE(road_address,' ','') ILIKE %s)"
        )
        params += [f"%{q}%", f"%{q}%", f"%{q}%", f"%{q}%", f"%{_q_ns}%", f"%{_q_ns}%"]
    if si_do:
        where.append(sido_match_clause("split_part(sgg_text, ' ', 1)"))
        params.append(sido_core(si_do))
    if sgg_nm:
        # sgg_nm은 master_buildings.sgg_text 전체값 — exact match로 와일드카드 오염 차단.
        # ('경기도 수원시' LIKE '%경기도 수원시%'가 '경기도 수원시 팔달구'까지 매칭하는 문제 방지)
        where.append("sgg_text = %s")
        params.append(sgg_nm)
    if umd_nm:
        where.append("REPLACE(umd_nm, ' ', '') ILIKE %s")
        params.append(f"%{umd_nm.replace(' ', '')}%")
    if lodging_type == "복합":
        where.append("(lodging_type = '복합' OR lodging_type LIKE '%%·%%')")
    elif lodging_type == "준공전":
        where.append("building_status IN ('허가','착공') AND (use_apr_day IS NULL OR use_apr_day = '')")
    elif lodging_type == "미분류":
        where.append("(lodging_type IS NULL OR lodging_type = '') AND building_status NOT IN ('허가','착공')")
    elif lodging_type:
        where.append("lodging_type = %s")
        params.append(lodging_type)

    where_sql = " AND ".join(where)

    # HAVING 조건 — 좌표 있는 건물이 반드시 1개 이상이어야 배지 표시 가능
    # bounds(sgg/umd): WHERE 대신 HAVING으로 적용 — 카운트는 지역 전체, 표시만 뷰포트 내
    having_parts  = ["COUNT(*) FILTER (WHERE lat IS NOT NULL AND lng IS NOT NULL) > 0"]
    having_params = []

    if level in ("sgg", "umd") and sw_lat and sw_lng and ne_lat and ne_lng:
        try:
            having_parts.append(
                "COUNT(*) FILTER (WHERE lat BETWEEN %s AND %s AND lng BETWEEN %s AND %s) > 0"
            )
            having_params += [float(sw_lat), float(ne_lat), float(sw_lng), float(ne_lng)]
        except ValueError:
            pass  # 잘못된 bounds 무시

    having_sql = " AND ".join(having_parts)

    # GROUP BY 기준: sido=시도 첫 토큰(약칭 정규화 포함), sgg=시군구 전체, umd=시군구+읍면동
    _sido_expr = _sido_norm_sql("split_part(sgg_text, ' ', 1)")
    if level == "sido":
        select_extra = f"{_sido_expr} AS region_name, NULL::text AS sgg_text_full"
        group_by     = _sido_expr
    elif level == "sgg":
        select_extra = "sgg_text AS region_name, sgg_text AS sgg_text_full"
        group_by     = "sgg_text"
    else:  # umd — 같은 동 이름이 다른 시군구에 있을 수 있어 시군구까지 묶어 그룹핑
        select_extra = "COALESCE(umd_nm, '') AS region_name, sgg_text AS sgg_text_full"
        group_by     = "sgg_text, umd_nm"

    conn = None
    cur = None
    try:
        conn = get_conn()
        cur = conn.cursor()
        cur.execute(f"""
            WITH grouped_buildings AS (
                SELECT *,
                       CASE
                         WHEN lodging_type = '생활' THEN '생활'
                         WHEN lodging_type = '관광' THEN '관광'
                         WHEN lodging_type = '일반' THEN '일반'
                         WHEN lodging_type = '복합' OR lodging_type LIKE '%%·%%' THEN '복합'
                         WHEN (lodging_type IS NULL OR lodging_type = '')
                              AND building_status IN ('허가','착공')
                              AND (use_apr_day IS NULL OR use_apr_day = '') THEN '준공전'
                         ELSE '미분류'
                       END AS map_type
                FROM master_buildings
                WHERE {where_sql}
            )
            SELECT {select_extra},
                   AVG(lat) FILTER (WHERE lat IS NOT NULL AND lng IS NOT NULL) AS lat,
                   AVG(lng) FILTER (WHERE lat IS NOT NULL AND lng IS NOT NULL) AS lng,
                   COUNT(*)  AS total,
                   COUNT(*) FILTER (WHERE map_type = '생활')   AS cnt_live,
                   COUNT(*) FILTER (WHERE map_type = '관광')   AS cnt_tour,
                   COUNT(*) FILTER (WHERE map_type = '일반')   AS cnt_gen,
                   COUNT(*) FILTER (WHERE map_type = '복합')   AS cnt_mixed,
                   COUNT(*) FILTER (WHERE map_type = '준공전') AS cnt_pre_completion,
                   COUNT(*) FILTER (WHERE map_type = '미분류') AS cnt_unknown
            FROM grouped_buildings
            GROUP BY {group_by}
            HAVING {having_sql}
            ORDER BY total DESC
        """, params + having_params)
        rows = cur.fetchall()
    finally:
        # 커서 close가 실패해도 연결 반환은 반드시 실행되어야 한다.
        try:
            if cur is not None:
                cur.close()
        finally:
            if conn is not None:
                release_conn(conn)

    items = []
    for r in rows:
        name = r["region_name"] or ""
        # umd 레벨은 "시군구 읍면동" 형식으로 표시 (같은 동 이름 구분)
        if level == "umd" and r["sgg_text_full"]:
            display = f"{r['sgg_text_full']} {name}".strip()
        else:
            display = name
        items.append({
            "name":    display,
            "lat":     float(r["lat"])  if r["lat"]  is not None else None,
            "lng":     float(r["lng"])  if r["lng"]  is not None else None,
            "total":   int(r["total"]),
            "by_type": {
                "생활":   int(r["cnt_live"]            or 0),
                "관광":   int(r["cnt_tour"]            or 0),
                "일반":   int(r["cnt_gen"]             or 0),
                "복합":   int(r["cnt_mixed"]           or 0),
                "준공전": int(r["cnt_pre_completion"]  or 0),
                "미분류": int(r["cnt_unknown"]         or 0),
            },
        })

    payload = json.dumps({"level": level, "items": items}, ensure_ascii=False)
    _cluster_cache[_cache_key] = (time.time(), payload.encode("utf-8"))
    return Response(payload.encode("utf-8"), mimetype="application/json")


@app.route("/api/ranking")
@limiter.limit("20 per minute")
def get_ranking(_as_payload=False):
    """재방문 유인용 랭킹 — 이번 주 신고가 갱신 TOP5 + 거래량 TOP5.
    결과는 1시간 캐시(서버 재시작 시 초기화).
    """
    master_payload = _master_stats_section("transaction_stats")
    if master_payload and master_payload.get("ranking"):
        return jsonify(master_payload["ranking"])

    if _master_stats_cold_starting():
        return jsonify({
            "ok": False,
            "status": "warming",
            "price_highs": [],
            "most_traded": [],
        })

    # [LEGACY] 원본 캐시가 비어 있거나 거래 섹션이 실패한 경우의 기존 랭킹 쿼리.
    import time as _time
    _cache = getattr(get_ranking, "_cache", None)
    if (
        not _master_stats_is_rebuilding()
        and _cache
        and _time.time() - _cache[0] < 3600
    ):
        return Response(_cache[1], mimetype="application/json")

    conn = None
    try:
        conn = get_conn()
        with conn.cursor() as cur:
            # ── 신고가 갱신 TOP 5 ──────────────────────────────────────────
            # 최근 7일 안에 들어온 거래 중 그 건물의 과거 최고가를 넘긴 건들
            cur.execute("""
                WITH recent AS (
                    SELECT DISTINCT ON (building_name, address)
                        building_name, address, sgg_cd, umd_nm, jibun, price, deal_date
                    FROM transactions
                    WHERE deal_date >= TO_CHAR(CURRENT_DATE - INTERVAL '7 days', 'YYYY-MM-DD')
                      AND price > 0
                    ORDER BY building_name, address, price DESC
                ),
                prev_max AS (
                    SELECT building_name, address, MAX(price) AS old_max
                    FROM transactions
                    WHERE deal_date < TO_CHAR(CURRENT_DATE - INTERVAL '7 days', 'YYYY-MM-DD')
                      AND price > 0
                    GROUP BY building_name, address
                    HAVING MAX(price) > 0
                )
                SELECT
                    r.building_name, r.address,
                    r.price            AS new_price,
                    p.old_max,
                    ROUND(100.0 * (r.price - p.old_max) / p.old_max, 1) AS pct_gain,
                    r.deal_date,
                    (SELECT id FROM master_buildings
                     WHERE building_name = r.building_name
                       AND sgg_cd = r.sgg_cd
                       AND umd_nm = r.umd_nm
                       AND jibun = r.jibun
                     ORDER BY id LIMIT 1) AS building_id,
                    (SELECT lat FROM master_buildings
                     WHERE building_name = r.building_name
                       AND sgg_cd = r.sgg_cd
                       AND umd_nm = r.umd_nm
                       AND jibun = r.jibun
                     ORDER BY id LIMIT 1) AS lat,
                    (SELECT lng FROM master_buildings
                     WHERE building_name = r.building_name
                       AND sgg_cd = r.sgg_cd
                       AND umd_nm = r.umd_nm
                       AND jibun = r.jibun
                     ORDER BY id LIMIT 1) AS lng
                FROM recent r
                JOIN prev_max p
                  ON r.building_name = p.building_name AND r.address = p.address
                WHERE r.price > p.old_max
                ORDER BY pct_gain DESC
                LIMIT 5
            """)
            price_highs = [
                {
                    "building_name": row["building_name"],
                    "address": row["address"],
                    "sgg_cd": row["sgg_cd"],
                    "umd_nm": row["umd_nm"],
                    "jibun": row["jibun"],
                    "new_price": row["new_price"],
                    "old_max": row["old_max"],
                    "pct_gain": float(row["pct_gain"]) if row["pct_gain"] is not None else 0,
                    "deal_date": row["deal_date"],
                    "building_id": row["building_id"],
                    "lat": float(row["lat"]) if row["lat"] is not None else None,
                    "lng": float(row["lng"]) if row["lng"] is not None else None,
                }
                for row in cur.fetchall()
            ]

            # ── 거래량 TOP 5 ───────────────────────────────────────────────
            cur.execute("""
                SELECT
                    building_name, address, sgg_nm, sgg_cd, umd_nm, jibun,
                    COUNT(*)        AS deal_count,
                    MAX(price)      AS max_price,
                    MAX(deal_date)  AS latest_date,
                    (SELECT id FROM master_buildings
                     WHERE building_name = t.building_name
                       AND sgg_cd = t.sgg_cd
                       AND umd_nm = t.umd_nm
                       AND jibun = t.jibun
                     ORDER BY id LIMIT 1) AS building_id,
                    (SELECT lat FROM master_buildings
                     WHERE building_name = t.building_name
                       AND sgg_cd = t.sgg_cd
                       AND umd_nm = t.umd_nm
                       AND jibun = t.jibun
                     ORDER BY id LIMIT 1) AS lat,
                    (SELECT lng FROM master_buildings
                     WHERE building_name = t.building_name
                       AND sgg_cd = t.sgg_cd
                       AND umd_nm = t.umd_nm
                       AND jibun = t.jibun
                     ORDER BY id LIMIT 1) AS lng
                FROM transactions t
                WHERE deal_date >= TO_CHAR(CURRENT_DATE - INTERVAL '7 days', 'YYYY-MM-DD')
                  AND price > 0
                GROUP BY building_name, address, sgg_nm, sgg_cd, umd_nm, jibun
                ORDER BY deal_count DESC
                LIMIT 5
            """)
            most_traded = [
                {
                    "building_name": row["building_name"],
                    "address": row["address"],
                    "sgg_nm": row["sgg_nm"],
                    "sgg_cd": row["sgg_cd"],
                    "umd_nm": row["umd_nm"],
                    "jibun": row["jibun"],
                    "deal_count": row["deal_count"],
                    "max_price": row["max_price"],
                    "latest_date": row["latest_date"],
                    "building_id": row["building_id"],
                    "lat": float(row["lat"]) if row["lat"] is not None else None,
                    "lng": float(row["lng"]) if row["lng"] is not None else None,
                }
                for row in cur.fetchall()
            ]

        payload = {"ok": True, "price_highs": price_highs, "most_traded": most_traded}
        if _as_payload:
            return payload
        result = json.dumps(payload, ensure_ascii=False, default=str).encode("utf-8")
        get_ranking._cache = (_time.time(), result)
        return Response(result, mimetype="application/json")

    except Exception as e:
        app.logger.error("[ranking] %s", e)
        return jsonify({"ok": False, "error": str(e)}), 500
    finally:
        if conn:
            try: conn.close()
            except Exception: pass


@app.route("/api/buildings-geo")
@limiter.limit("30 per minute")
def get_buildings_geo():
    """지도 마커용 — 좌표(lat/lng)가 있는 마스터 건물.

    선택적 필터(지역/건물명/용도)를 /api/transactions와 동일한 파라미터
    이름으로 지원한다. 단, 기간(year)은 건물 위치와 무관하므로 지도에는
    적용하지 않는다(게시판 전용).

    master_buildings에는 si_do/sgg_nm 컬럼이 없고 sgg_text('서울특별시 서초구')
    와 umd_nm만 있으므로:
      - si_do  : 표기 편차('서울' vs '서울특별시')로 인한 누락을 막기 위해
                 양쪽 모두 행정접미사를 떼어낸 코어 이름으로 정확 비교
      - sgg_nm : sgg_text 포함 매칭
      - umd_nm : 공백 유무 차이('손양면 동호리' vs '손양면동호리')를 흡수하기
                 위해 공백 제거 후 포함 매칭
    """
    q = request.args.get("q", "").strip()
    si_do = request.args.get("si_do", "").strip()
    sgg_nm = request.args.get("sgg_nm", "").strip()
    umd_nm = request.args.get("umd_nm", "").strip()
    lodging_type = request.args.get("lodging_type", "").strip()

    # 뷰포트 bounds — 마커 모드에서 화면에 보이는 범위만 반환
    sw_lat = request.args.get("sw_lat", "").strip()
    sw_lng = request.args.get("sw_lng", "").strip()
    ne_lat = request.args.get("ne_lat", "").strip()
    ne_lng = request.args.get("ne_lng", "").strip()

    # 만료된 캐시 항목 주기적 정리 — bounds 요청이 늘어도 메모리 무한 증가 방지
    _now = time.time()
    if len(_geo_cache) > 200:
        expired = [k for k, (ts, _) in _geo_cache.items() if _now - ts >= _GEO_CACHE_TTL]
        for k in expired:
            _geo_cache.pop(k, None)

    # bounds가 없는 필터 전용 요청만 캐시 — bounds는 뷰포트마다 달라 고카디낼리티
    _has_bounds = bool(sw_lat and sw_lng and ne_lat and ne_lng)
    _cache_key = f"{q}|{si_do}|{sgg_nm}|{umd_nm}|{lodging_type}" if not _has_bounds else None
    if _cache_key:
        _cached = _geo_cache.get(_cache_key)
        if _cached and (_now - _cached[0]) < _GEO_CACHE_TTL:
            return Response(_cached[1], mimetype="application/json")

    # mixed_use_excluded: 복합시설(주용도≠숙박) 자동 제외 — 지도/사이트 노출 금지
    where = ["lat IS NOT NULL", "lng IS NOT NULL",
             "lodging_type IS DISTINCT FROM 'mixed_use_excluded'"]
    params = []

    if q:
        # jibun 컬럼 직접 매칭 추가 — jibun_address = NULL인 건물도 지번 검색으로 발견.
        # 공백 제거 후 비교(nospace) 추가 — "그레이스경희"→"더 그레이스 경희",
        # "서천동812"→"서천동 812" 등 붙여쓰기/띄어쓰기 편차 흡수.
        _q_ns = q.replace(' ', '')
        where.append(
            "(building_name ILIKE %s OR road_address ILIKE %s OR jibun_address ILIKE %s OR jibun ILIKE %s"
            " OR REPLACE(building_name,' ','') ILIKE %s OR REPLACE(road_address,' ','') ILIKE %s)"
        )
        params += [f"%{q}%", f"%{q}%", f"%{q}%", f"%{q}%", f"%{_q_ns}%", f"%{_q_ns}%"]
    if si_do:
        # '서울' vs '서울특별시' 표기 편차 흡수 — 게시판과 동일한 코어 이름 비교 규칙 사용.
        # sgg_text('서울특별시 서초구')의 첫 토큰을 정규화해 비교한다.
        where.append(sido_match_clause("split_part(sgg_text, ' ', 1)"))
        params.append(sido_core(si_do))
    if sgg_nm:
        # sgg_nm은 master_buildings.sgg_text 전체값 — exact match로 와일드카드 오염 차단.
        where.append("sgg_text = %s")
        params.append(sgg_nm)
    if umd_nm:
        where.append("REPLACE(umd_nm, ' ', '') ILIKE %s")
        params.append(f"%{umd_nm.replace(' ', '')}%")
    if lodging_type == "복합":
        where.append("(lodging_type = '복합' OR lodging_type LIKE '%%·%%')")
    elif lodging_type == "준공전":
        where.append("building_status IN ('허가','착공') AND (use_apr_day IS NULL OR use_apr_day = '')")
    elif lodging_type == "미분류":
        where.append("(lodging_type IS NULL OR lodging_type = '') AND building_status NOT IN ('허가','착공')")
    elif lodging_type:
        where.append("lodging_type = %s")
        params.append(lodging_type)

    # 뷰포트 bounds 필터 — 화면에 보이는 범위의 건물만 반환해 응답 크기 축소
    # 파싱을 먼저 해서 실패 시 where/params를 건드리지 않는다 (IndexError 방지)
    if sw_lat and sw_lng and ne_lat and ne_lng:
        try:
            _f_sw_lat = float(sw_lat)
            _f_ne_lat = float(ne_lat)
            _f_sw_lng = float(sw_lng)
            _f_ne_lng = float(ne_lng)
            where.append("lat BETWEEN %s AND %s AND lng BETWEEN %s AND %s")
            params += [_f_sw_lat, _f_ne_lat, _f_sw_lng, _f_ne_lng]
        except (ValueError, TypeError):
            pass  # 잘못된 bounds 무시

    where_sql = " AND ".join(where)

    conn = get_conn()
    cur = conn.cursor()
    # 각 건물의 '가장 최근 실거래가'를 지번(sgg_cd+umd_nm+jibun) 기준으로 1건만 붙인다.
    # 건물명 매칭은 마스터에 건물명이 "-"처럼 여러 건물이 공유하는 플레이스홀더로
    # 채워진 경우, "-"인 실거래 1건이 "-" 이름의 모든 건물에 잘못 붙는 버그가 있어
    # 지번 튜플 매칭으로 대체한다(sync_batch.py가 transactions에 적재할 때 쓰는
    # (sgg_cd, 정규화 umd_nm, jibun)과 동일한 키).
    #   - 지번 3개 컬럼이 모두 있으면 지번으로 정확 매칭.
    #   - 셋 중 하나라도 NULL이라 지번 매칭이 불가능하면, 예외적으로 건물명으로
    #     한 번 더 시도하되 "-" 같은 플레이스홀더 이름은 제외한다.
    # 같은 지번에 여러 건물(동/호로 구분되는 단지)이 있으면 서로 다른 건물의 거래가
    # 섞일 수 있으므로, 지번이 같은 후보 안에서 건물명(t.building_name = mb.building_name)
    # 까지 정확히 일치하는 거래를 최우선으로 고르고(name_exact DESC), 그런 거래가
    # 없으면 그 지번의 최신 거래를 대체값으로 쓴다(그다음 deal_date DESC).
    #   - latest_price_exact=TRUE  : 건물명까지 정확히 일치한 확정 거래
    #   - latest_price_exact=FALSE : 같은 필지의 대체(참고) 거래
    # N+1 방지를 위해 LEFT JOIN LATERAL로 건물당 최신 1행만 조회하고,
    # 실거래 이력이 없으면 latest_price/latest_deal_date가 NULL로 반환된다.
    # txn_count는 최신 거래 선택과 같은 매칭 규칙으로 전체 거래 건수를 계산한다.
    # listing_count는 지도에서 공개하던 직거래 매물 중 철회되지 않은 것만 합산한다.
    cur.execute(f"""
        SELECT mb.id, mb.building_name, mb.name_pending,
               mb.building_name_source, mb.building_name_candidate_count,
               mb.road_address, mb.lat, mb.lng, mb.lodging_type,
               mb.building_status,
               lt.price AS latest_price, lt.deal_date AS latest_deal_date,
               lt.floor AS latest_floor, lt.area AS latest_area,
               lt.deal_type AS latest_deal_type,
               COALESCE(lt.name_exact, FALSE) AS latest_price_exact,
               lt.address AS address,
                COALESCE(
                  CASE WHEN lt.exact_count > 0 THEN lt.exact_count ELSE lt.candidate_count END,
                  0
                )::integer AS txn_count,
               COALESCE(listing_counts.listing_count, 0)::integer AS listing_count,
               (
                  COALESCE(
                    CASE WHEN lt.exact_count > 0 THEN lt.exact_count ELSE lt.candidate_count END,
                    0
                  ) +
                 COALESCE(listing_counts.listing_count, 0)
               )::integer AS total_count
        FROM master_buildings mb
        LEFT JOIN LATERAL (
            SELECT t.price, t.deal_date, t.floor, t.area, t.deal_type, t.address,
                   (t.building_name = mb.building_name) AS name_exact,
                   COUNT(*) FILTER (
                     WHERE t.building_name = mb.building_name
                   ) OVER () AS exact_count,
                   COUNT(*) OVER () AS candidate_count
            FROM transactions t
            WHERE (
                    mb.sgg_cd IS NOT NULL AND mb.umd_nm IS NOT NULL AND mb.jibun IS NOT NULL
                    AND t.sgg_cd = mb.sgg_cd
                    AND t.umd_nm = mb.umd_nm
                    AND t.jibun  = mb.jibun
                  )
               OR (
                    (mb.sgg_cd IS NULL OR mb.umd_nm IS NULL OR mb.jibun IS NULL)
                    AND mb.building_name <> '-'
                    AND t.building_name = mb.building_name
                  )
            ORDER BY (t.building_name = mb.building_name) DESC NULLS LAST, t.deal_date DESC
            LIMIT 1
        ) lt ON TRUE
        LEFT JOIN LATERAL (
            SELECT COUNT(*) AS listing_count
            FROM listing_requests lr
            WHERE lr.master_building_id = mb.id
              AND lr.deal_mode = 'direct'
              AND COALESCE(lr.status, '') NOT IN ('withdrawn', '철회됨', '보류')
              AND NOT (
                  COALESCE(lr.transaction_target, 'unit') = 'whole'
                  AND COALESCE(lr.disclosure_scope, 'limited') = 'limited'
              )
        ) listing_counts ON TRUE
        WHERE {where_sql}
        ORDER BY mb.id
    """, params)
    rows = [dict(r) for r in cur.fetchall()]
    cur.close()
    conn.close()
    for row in rows:
        row["building_name_auto"] = (
            row.get("building_name_source") == "lodging_report"
        )
        row["building_name_auto_representative"] = (
            row["building_name_auto"]
            and int(row.get("building_name_candidate_count") or 0) > 1
        )
    payload = json.dumps({"total": len(rows), "items": rows}, ensure_ascii=False)
    if _cache_key:  # bounds 요청은 캐시하지 않음 (고카디낼리티)
        _geo_cache[_cache_key] = (time.time(), payload)
    return Response(payload, mimetype="application/json")


# 실거래 추이 집계의 공통 상수/로직 — /api/monthly-trend(A/B화면)와
# /api/admin/stats(관리자 대시보드)가 동일하게 공유한다(중복 방지).
TREND_FLOOR_YM = "2020-01"  # 백필 목표 하한 — 이 이전 계약월은 집계에서 제외


def _trend_bucket_items(agg, now):
    """월별 집계 dict를 추이 차트용 버킷 목록으로 변환한다.

    agg: {"YYYY-MM": {"cnt": int, "sum_price": int}} (TREND_FLOOR_YM 이전은 이미 제외된 상태)
    반환: (items, granularity)
      - items: [{"ym": "YYYY-MM"|"YYYY-Qn", "count": int, "sum_price": int}, ...] (과거→최근, 빈 버킷 0)
      - granularity: "month" | "quarter" (기간이 24개월 초과면 분기로 자동 전환)
    데이터가 전혀 없으면 최근 12개월(전부 0) month 버킷을 반환한다(하위호환).
    """
    now_ym = f"{now.year:04d}-{now.month:02d}"

    def _month_range(start_ym_, end_ym_):
        """start~end(포함) YYYY-MM 목록 (과거 → 최근)."""
        sy, sm = int(start_ym_[:4]), int(start_ym_[5:7])
        ey, em = int(end_ym_[:4]), int(end_ym_[5:7])
        out = []
        while (sy, sm) <= (ey, em):
            out.append(f"{sy:04d}-{sm:02d}")
            sm += 1
            if sm == 13:
                sm = 1
                sy += 1
        return out

    if agg:
        start_ym = min(agg.keys())
        if start_ym > now_ym:  # 미래 계약일만 있는 극단 케이스 방어
            start_ym = now_ym
    else:
        # 데이터 없음 → 기존과 동일하게 최근 12개월(전부 0)
        y, m = now.year, now.month
        m -= 11
        while m <= 0:
            m += 12
            y -= 1
        start_ym = f"{y:04d}-{m:02d}"

    months = _month_range(start_ym, now_ym)

    if len(months) > 24:
        # 24개월 초과 → 분기별(3개월) 버킷으로 자동 전환. 라벨은 "2025-Q1" 형식.
        def _q(ym):
            return f"{ym[:4]}-Q{(int(ym[5:7]) - 1) // 3 + 1}"
        qagg = {}
        for ym, v in agg.items():
            k = _q(ym)
            cur_v = qagg.setdefault(k, {"cnt": 0, "sum_price": 0})
            cur_v["cnt"] += v["cnt"]
            cur_v["sum_price"] += v["sum_price"]
        quarters = []
        for ym in months:
            k = _q(ym)
            if not quarters or quarters[-1] != k:
                quarters.append(k)
        items = [{
            "ym": q,
            "count": qagg.get(q, {}).get("cnt", 0),
            "sum_price": qagg.get(q, {}).get("sum_price", 0),
        } for q in quarters]
        return items, "quarter"

    items = [{
        "ym": ym,
        "count": agg.get(ym, {}).get("cnt", 0),
        "sum_price": agg.get(ym, {}).get("sum_price", 0),
    } for ym in months]
    return items, "month"


@app.route("/api/monthly-trend")
def get_monthly_trend():
    """
    실거래 추세 집계 (좌측 패널 '실거래추세' 콤보차트용).
    - count     : 버킷별 거래건수 (막대)
    - sum_price : 버킷별 거래금액 합계, 만원 단위 (선)
    시작월은 실제 데이터의 최소 계약월(하한 2020-01)이며, 기간이 24개월을
    초과하면 분기("YYYY-Qn") 버킷으로 집계한다(응답 granularity: month|quarter).
    빈 버킷은 0으로 채우고, 데이터가 전혀 없으면 최근 12개월 0버킷을 반환한다.

    선택적 building_id가 있으면 해당 건물(master_buildings.building_name)의
    실거래만 집계하고, 없으면 기존처럼 전체를 집계한다(하위호환).
    """
    now = datetime.now()
    # 집계 시작월은 '실제 데이터의 최소 계약월'로 하되, 백필 목표 범위(TREND_FLOOR_YM) 이전은 잘라낸다.
    # 버킷 계산(월/분기 전환 포함)은 _trend_bucket_items 공용 헬퍼 사용.
    where = ["deal_date IS NOT NULL", "substring(deal_date, 1, 7) >= %s"]
    params = [TREND_FLOOR_YM]

    # 선택적 building_id → 해당 건물의 실거래만 집계(하위호환: 없거나 정수 아니면 전체 집계).
    # 정확도: A화면 마커(get_buildings_geo)와 동일한 키 전략을 쓴다.
    #   - 지번키(sgg_cd+umd_nm+jibun)가 모두 있으면 지번으로 정확 매칭
    #     (건물명은 유니크 키가 아니라 동명 건물 거래가 섞일 수 있어 지번을 우선).
    #   - 셋 중 하나라도 NULL이면 예외적으로 건물명 매칭('-' 플레이스홀더는 제외).
    # 정수가 아닌 값은 무시하고 전체 집계로 폴백해 500(정수 캐스팅 오류)을 막는다.
    building_id = request.args.get("building_id", "").strip()
    if building_id.isdigit():
        conn = get_conn()
        cur = conn.cursor()
        cur.execute("""
            SELECT building_name, sgg_cd, umd_nm, jibun
            FROM master_buildings WHERE id = %s
        """, [int(building_id)])
        b = cur.fetchone()
        cur.close()
        conn.close()
        if b and b["sgg_cd"] and b["umd_nm"] and b["jibun"]:
            where.append("sgg_cd = %s AND umd_nm = %s AND jibun = %s")
            params += [b["sgg_cd"], b["umd_nm"], b["jibun"]]
        else:
            # 지번키 불완전 → 건물명 폴백. 건물 미존재/이름 없음/'-'는 매칭 0으로 처리.
            # (기존 "\x00" 플레이스홀더는 psycopg2가 NUL 거부로 500을 내던 버그라 FALSE 조건으로 교체)
            name = (b["building_name"] if b else None) or ""
            if name and name != "-":
                where.append("building_name = %s")
                params.append(name)
            else:
                where.append("FALSE")

    # 선택적 area_sqm → 해당 평형 ±0.5㎡ 거래만 추세 집계
    _trend_asqm = request.args.get("area_sqm", "").strip()
    if _trend_asqm:
        try:
            _tasqm = float(_trend_asqm)
            where.append("area BETWEEN %s AND %s")
            params += [_tasqm - 0.5, _tasqm + 0.5]
        except ValueError:
            pass

    conn = get_conn()
    cur = conn.cursor()
    cur.execute(f"""
        SELECT substring(deal_date, 1, 7) AS ym,
               COUNT(*) AS cnt,
               COALESCE(SUM(price), 0) AS sum_price
        FROM transactions
        WHERE {" AND ".join(where)}
        GROUP BY ym
    """, params)
    agg = {r["ym"]: {"cnt": r["cnt"], "sum_price": int(r["sum_price"] or 0)} for r in cur.fetchall()}
    cur.close()
    conn.close()

    items, granularity = _trend_bucket_items(agg, now)
    return jsonify({"items": items, "granularity": granularity})


@app.route("/api/tx-count")
def get_tx_count():
    """전체 실거래 건수 (실시간 COUNT — 관리자 대시보드 '누적 거래' KPI와 동일 기준).
    메인 지도 상단 '실거래 N건' 표시에 사용. 백필/동기화로 늘어나므로 매 로드마다 조회."""
    conn = get_conn()
    cur = conn.cursor()
    cur.execute("SELECT COUNT(*) AS c FROM transactions")
    count = int(cur.fetchone()["c"])
    cur.close()
    conn.close()
    return jsonify({"count": count})


@app.route("/api/building-count")
@limiter.limit("60 per minute")
def get_building_count():
    """전체 생숙 단지 수 + 용도별 분포 + 실거래 건수.

    by_type: 통계 대시보드와 동일한 분류 기준
      - '생활' / '관광' / '일반' : 해당 lodging_type
      - '준공전'                  : building_status IN ('허가','착공')
      - '복합'                    : 나머지 전부(mixed_use_excluded·NULL·실제복합 포함)
    count   : 통계 대시보드의 '등록 건물' 총수 (분류 합계)
    tx_count: 현재 실거래 건수
    """
    # /api/building-count는 _MASTER_STATS_CACHE가 있으면 지도와 관리자 통계가 같은 시점의 건물 수를
    # 사용한다. 만료·무효화된 캐시는 stale 값을 즉시 사용하고 백그라운드
    # 재검증만 예약한다. 최초 캐시가 없을 때만 아래의 실시간 쿼리를 실행한다.
    cached_lodging = (
        _MASTER_STATS_CACHE.get("data", {}).get("lodging_stats")
        if "_MASTER_STATS_CACHE" in globals()
        else None
    )
    if cached_lodging is not None:
        if not _master_stats_cache_is_valid():
            _MASTER_STATS_NEEDS_REFRESH.set()
        cached_rows = cached_lodging.get("rows") or []
        by_type = cached_lodging.get("building_count_by_type") or {
            row.get("type"): int(row.get("building_count") or 0)
            for row in cached_rows
            if row.get("type") not in (None, "전체")
            and int(row.get("building_count") or 0) > 0
        }
        cached_total = cached_lodging.get("total_building_cnt")
        total = (
            int(cached_total)
            if cached_total is not None
            else sum(by_type.values())
        )
    else:
        conn = get_conn()
        cur = conn.cursor()

        # 용도별 건물 수 — 지도 필터와 동일한 기준 (클릭 결과와 숫자 일치 보장)
        # mixed_use_excluded: 지도 노출 금지 → 범례에도 카운트 제외
        # 준공전: building_status IN ('허가','착공') AND use_apr_day 없음 — lodging_type NULL보다 우선
        #   use_apr_day가 있으면 이미 완공된 건물이므로 준공전에서 제외 (backfill이 채웠지만
        #   building_status 미갱신된 오분류 112건 방어)
        # 복합: lodging_type = '복합' 또는 '·' 포함 (지도 복합 필터와 동일)
        # 미분류: lodging_type NULL/'' 이면서 준공전이 아닌 건물
        cur.execute("""
            SELECT
                CASE
                    WHEN building_status IN ('허가','착공')
                         AND (use_apr_day IS NULL OR use_apr_day = '') THEN '준공전'
                    WHEN lodging_type = '생활'                               THEN '생활'
                    WHEN lodging_type = '관광'                               THEN '관광'
                    WHEN lodging_type = '일반'                               THEN '일반'
                    WHEN lodging_type = '복합' OR lodging_type LIKE '%·%'   THEN '복합'
                    WHEN lodging_type IS NULL OR lodging_type = ''           THEN '미분류'
                    ELSE NULL   -- mixed_use_excluded 등 → 제외
                END AS t,
                COUNT(*) AS c
            FROM master_buildings
            WHERE lodging_type IS DISTINCT FROM 'mixed_use_excluded'
            GROUP BY 1
        """)
        by_type = {r["t"]: int(r["c"]) for r in cur.fetchall() if r["t"] is not None}
        # total: mixed_use_excluded 제외 건물 수 (범례에 표시할 건물 수와 동일)
        total = sum(by_type.values())
        cur.close()
        conn.close()

    # 실거래 건수
    conn = get_conn()
    cur = conn.cursor()
    cur.execute("SELECT COUNT(*) AS c FROM transactions")
    tx_count = int(cur.fetchone()["c"])

    cur.close()
    conn.close()
    return jsonify({"count": total, "by_type": by_type, "tx_count": tx_count})


@app.route("/api/regions")
@limiter.limit("30 per minute")
def get_regions():
    """시도 > 시군구 > 읍면동 계층 트리 (계층 검색 드롭다운용).

    buildings-cluster와 동일한 기준(master_buildings, mixed_use_excluded 제외)으로
    집계해 드롭다운 건물 수와 지도 배지 숫자를 정확히 일치시킨다.
    - si_do: _sido_norm_sql로 약칭 정규화(서울 → 서울특별시 등)
    - sgg_nm: master_buildings.sgg_text 전체값(예: '경기도 수원시 팔달구')
    - umd_nm: master_buildings.umd_nm
    """
    sido_expr = _sido_norm_sql("split_part(sgg_text, ' ', 1)")
    conn = get_conn()
    cur = conn.cursor()
    cur.execute(f"""
        SELECT
            {sido_expr}  AS si_do,
            sgg_text     AS sgg_nm,
            umd_nm,
            COUNT(*)     AS c
        FROM master_buildings
        WHERE lodging_type IS DISTINCT FROM 'mixed_use_excluded'
        GROUP BY sgg_text, umd_nm
    """)
    rows = cur.fetchall()
    cur.close()
    conn.close()

    tree = {}
    for r in rows:
        sd = r["si_do"] or ""
        sg = r["sgg_nm"] or ""
        um = r["umd_nm"] or ""   # umd_nm = NULL 건물은 빈 문자열로 처리
        c  = r["c"]
        if not sd or not sg:     # sgg_text = NULL 이상 건물은 드롭다운 제외
            continue
        tree.setdefault(sd, {"count": 0, "sgg": {}})
        tree[sd]["count"] += c
        tree[sd]["sgg"].setdefault(sg, {"count": 0, "umd": {}})
        tree[sd]["sgg"][sg]["count"] += c
        tree[sd]["sgg"][sg]["umd"][um] = tree[sd]["sgg"][sg]["umd"].get(um, 0) + c

    return jsonify(tree)


@app.route("/api/years")
def get_years():
    """
    실거래 연도 목록 (기간 필터 드롭다운용).
    - 실제 데이터에 존재하는 연도만 노출 (데이터 없는 연도는 드롭다운에서 제외)
    - 데이터가 하나도 없으면 현재 연도만 표시
    - 새 연도 데이터가 들어오면 자동으로 목록에 추가됨 (하드코딩 아님)
    """
    conn = get_conn()
    cur = conn.cursor()
    cur.execute("SELECT DISTINCT LEFT(deal_date, 4) y FROM transactions WHERE deal_date IS NOT NULL")
    data_years = {r["y"] for r in cur.fetchall() if r["y"]}
    cur.close()
    conn.close()

    current_year = datetime.now().year
    years = sorted(data_years, reverse=True) if data_years else [str(current_year)]

    return jsonify({"years": years, "current_year": str(current_year)})


@app.route("/api/favorites")
def get_favorites():
    """
    관심단지 전용 조회 — /api/transactions의 size 상한(200)과 무관하게
    저장된 관심단지 키(building_name|address) 전체를 한 번에 정확히 조회한다.
    쿼리파라미터: keys = "건물명|주소" 쌍을 쉼표(,)로 연결
    """
    raw_keys = request.args.get("keys", "").strip()
    if not raw_keys:
        return jsonify({"items": [], "total": 0})

    pairs = []
    for token in raw_keys.split(","):
        if "|" not in token:
            continue
        name, addr = token.split("|", 1)
        pairs.append((name, addr))

    if not pairs:
        return jsonify({"items": [], "total": 0})

    conn = get_conn()
    cur = conn.cursor()
    # 미매칭 거래는 building_name이 NULL이고, 프론트 favKey는 이를 문자열 "null"로 저장한다.
    # SQL에서 = 'null'은 실제 NULL과 매칭되지 않으므로 그런 항목은 IS NULL로 조회한다.
    conditions = []
    params = []
    for name, addr in pairs:
        if name in ("null", "undefined", ""):
            conditions.append("(building_name IS NULL AND address = %s)")
            params.append(addr)
        else:
            conditions.append("(building_name = %s AND address = %s)")
            params.extend([name, addr])
    conditions = " OR ".join(conditions)
    cur.execute(f"""
        SELECT building_name, address, si_do, sgg_nm, umd_nm, jibun, sgg_cd,
               area, price, deal_date, deal_type, floor,
               lodging_type, lodging_type_detail, match_source,
               (SELECT mb.id FROM master_buildings mb
                 WHERE mb.sgg_cd = transactions.sgg_cd
                   AND mb.umd_nm = transactions.umd_nm
                   AND mb.jibun = transactions.jibun
                 ORDER BY mb.id LIMIT 1) AS master_building_id
        FROM transactions
        WHERE {conditions}
        ORDER BY deal_date DESC, id DESC
    """, params)
    rows = [dict(r) for r in cur.fetchall()]

    # 실거래가 없는 관심단지 fallback — transactions에서 못 찾은 키는 master_buildings를
    # 직접 매칭(도로명주소 일치 또는 "읍면동+지번" 공백제거 비교)해 거래 없이도
    # 이름/지역/상세링크(master_building_id)를 돌려준다. (홈 좌측 관심단지 위젯용)
    covered = {(r["building_name"], r["address"]) for r in rows}
    for name, addr in pairs:
        norm_name = None if name in ("null", "undefined", "") else name
        if (norm_name, addr) in covered:
            continue
        cur.execute("""
            SELECT id, building_name, sgg_text, umd_nm, jibun
            FROM master_buildings
            WHERE lodging_type IS DISTINCT FROM 'mixed_use_excluded'
              AND (road_address = %s
               OR REPLACE(umd_nm || jibun, ' ', '') = REPLACE(%s, ' ', ''))
            ORDER BY (building_name = %s) DESC NULLS LAST, id
            LIMIT 1
        """, (addr, addr, norm_name))
        mb = cur.fetchone()
        if not mb:
            continue
        rows.append({
            "building_name": norm_name, "address": addr,
            "si_do": None, "sgg_nm": mb["sgg_text"], "umd_nm": mb["umd_nm"],
            "jibun": mb["jibun"], "sgg_cd": None,
            "area": None, "price": None, "deal_date": None, "deal_type": None,
            "floor": None, "lodging_type": None, "lodging_type_detail": None,
            "match_source": "master_fallback",
            "master_building_id": mb["id"],
        })
    cur.close()
    conn.close()
    return jsonify({"items": rows, "total": len(rows)})


def _fill_master_coords(cur, master_id, road_address):
    """신규 master_buildings 행에 카카오 지오코딩(geocode_buildings.geocode_address)으로
    lat/lng을 채운다. 이미 열려 있는 커서를 받아 UPDATE만 수행하고 커밋은 호출측에 맡긴다.

    주소 미인식/카카오 API 오류/키 미설정 등으로 실패해도 예외를 밖으로 던지지 않아
    건물 등록 자체는 막지 않는다(좌표만 NULL로 남기고 넘어감)."""
    if not road_address:
        return
    try:
        from geocode_buildings import geocode_address
        result = geocode_address(road_address)
        if not result:
            return
        lat, lng = result
        # 보조 UPDATE는 SAVEPOINT로 감싼다. UPDATE 자체가 DB 오류를 내도
        # 메인 INSERT 트랜잭션이 aborted 상태로 오염되지 않아, 호출측 commit이
        # 정상 진행되고 건물 등록은 좌표 NULL로라도 유지된다.
        cur.execute("SAVEPOINT geocode_sp")
        try:
            cur.execute(
                "UPDATE master_buildings SET lat=%s, lng=%s WHERE id=%s",
                (lat, lng, master_id),
            )
            cur.execute("RELEASE SAVEPOINT geocode_sp")
        except Exception:
            cur.execute("ROLLBACK TO SAVEPOINT geocode_sp")
            raise
    except Exception as e:
        app.logger.warning(
            "신규 건물 지오코딩 실패(등록은 계속) id=%s: %s / %s",
            master_id, road_address, e,
        )


@app.route("/api/submit-building", methods=["POST"])
@limiter.limit("3 per minute; 10 per hour; 100 per day")
def submit_building():
    """
    사용자가 "내 건물이 목록에 없다"며 도로명주소를 제출하면:
      1) building_requests에 요청 기록
      2) 도로명→지번 변환(JUSO) → building_registry.classify_lodging_type()로 실시간 재검증
      3) 사용자가 고른 용도(suggested)는 참고용으로만 기록하고, 실제 반영은 검증 결과만 사용.
         검증 통과 시에만 master_buildings(신마스터)에 편입(source='user_submitted').
         판정 불가 시 사유와 함께 거절 (요청 기록에 남김)
    """
    from address_utils import road_to_jibun, BjdongMap, parse_jibun
    from building_registry import classify_lodging_type, resolve_api_building_name
    import os as _os

    data = request.get_json(force=True) or {}
    road_address = (data.get("road_address") or "").strip()
    jibun_address_input = (data.get("jibun_address_input") or "").strip()
    building_name_hint = (data.get("building_name_hint") or "").strip()
    suggested_lodging_type = (data.get("suggested_lodging_type") or "").strip()  # 참고용, 신뢰 안 함
    requester_note = (data.get("requester_note") or "").strip()

    if not road_address:
        return jsonify({"status": "error", "message": "주소를 입력해주세요."}), 400

    conn = get_conn()
    cur = conn.cursor()

    cur.execute("""
        INSERT INTO building_requests (request_type, road_address, building_name_hint, suggested_lodging_type, requester_note, jibun_address_input)
        VALUES ('new', %s, %s, %s, %s, %s) RETURNING id
    """, (road_address, building_name_hint, suggested_lodging_type, requester_note, jibun_address_input or None))
    request_id = cur.fetchone()["id"]
    conn.commit()

    def fail(reason, http_code=200):
        cur.execute("""
            UPDATE building_requests SET status='rejected', reject_reason=%s, processed_at=NOW()
            WHERE id=%s
        """, (reason, request_id))
        conn.commit()
        cur.close()
        conn.close()
        return jsonify({"status": "rejected", "message": reason}), http_code

    bjdong_csv = _os.environ.get("BJDONG_CODE_CSV", "법정동코드 전체자료.csv")
    bjdong = BjdongMap(bjdong_csv)

    zip_code_val = ""  # 도로명→JUSO 경로에서만 채워짐; 지번직접입력은 백필 배치가 나중에 채운다
    # ── 지번주소 직접 입력 경로 (road_to_jibun 우회) ─────────────────────────────
    # 입력 형식: "[읍면동] [번지]"  예) 서천동 812  또는 서천동 812-4
    # 하위호환: 사용자가 실수로 시도·시군구까지 풀세트 입력해도 뒤 2토큰만 사용
    # 시도·시군구는 도로명주소 앞부분에서 longest-prefix 매칭으로 자동 추출
    if jibun_address_input:
        # [1] 시도·시군구를 도로명주소에서 추출 (BjdongMap 최장일치)
        sgg_match = bjdong.extract_sgg_from_address(road_address)
        if not sgg_match:
            return fail(
                "도로명주소에서 시도·시군구를 인식할 수 없습니다. "
                "도로명주소 앞부분을 '경기도 용인시 기흥구 서천로…' 형식으로 입력해주세요."
            )
        si_do_j, sgg_nm_j, sgg_cd_j = sgg_match

        # [2] 지번주소 입력값: 뒤에서 번지 1개, 그 앞 읍면동 1개 — 나머지 앞토큰은 무시(하위호환)
        j_tokens = jibun_address_input.split()
        if len(j_tokens) < 2:
            return fail(
                "입력하신 지번주소를 파악할 수 없습니다. "
                "[읍면동] [번지] 형식(예: 서천동 812-4)으로 입력해주세요. "
                "시도·시군구는 도로명주소에서 자동으로 인식됩니다."
            )
        bun_ji_str = j_tokens[-1]
        umd_raw = j_tokens[-2]
        umd_nm_j = normalize_umd_nm(umd_raw)

        # [3] sgg_cd + umd_nm → bjdong_cd
        bjdong_cd_j = bjdong.find_bjdong_cd(sgg_cd_j, umd_nm_j)
        if not bjdong_cd_j:
            bjdong_cd_j = bjdong.find_bjdong_cd(sgg_cd_j, umd_raw)
            if bjdong_cd_j:
                umd_nm_j = normalize_umd_nm(umd_raw)
        if not bjdong_cd_j:
            return fail(
                f"입력하신 읍면동 '{umd_raw}'을(를) {si_do_j} {sgg_nm_j} 안에서 찾지 못했습니다. "
                "읍면동명을 다시 확인해주세요."
            )

        plat_gb_j, bun_j, ji_j = parse_jibun(bun_ji_str)
        jibun_str_j = f"{bun_j}-{ji_j}" if ji_j not in ("0", "", None) else bun_j

        si_do = si_do_j; sgg_nm = sgg_nm_j
        sgg_cd = sgg_cd_j; sgg_text_val = f"{si_do_j} {sgg_nm_j}".strip()
        umd_nm = umd_nm_j; bjdong_cd = bjdong_cd_j
        plat_gb, bun2, ji2 = plat_gb_j, bun_j, ji_j
        jibun_str = jibun_str_j

    else:
        # ── 기존 경로: 도로명주소 → road_to_jibun 변환 ─────────────────────────
        try:
            juso = road_to_jibun(road_address)
        except Exception as e:
            return fail(f"주소 변환 중 오류: {e}")

        if not juso:
            return fail("입력하신 주소로 지번 정보를 찾지 못했습니다. 도로명주소를 다시 확인해주세요.")

        si_do = juso.get("siNm", "")
        sgg_nm = juso.get("sggNm", "")
        # umd_nm은 마스터/실거래 매칭키다. sync_batch가 emdNm+liNm을 공백제거해 저장하므로
        # 여기서도 동일한 표준 함수로 정규화해야 이후 실거래 sync에서 이 건물이 누락되지 않는다.
        umd_nm = normalize_umd_nm(juso.get("emdNm", "") + juso.get("liNm", ""))
        bun = juso.get("lnbrMnnm", "0")
        ji = juso.get("lnbrSlno", "0")
        jibun_str = f"{bun}-{ji}" if ji not in ("0", "", None) else bun
        zip_code_val = (juso.get("zipNo") or "").strip()

        sgg_cd = bjdong.find_sgg_cd(si_do, sgg_nm)
        if not sgg_cd:
            return fail("법정동코드 매칭에 실패했습니다. 주소 표기를 확인해주세요.")

        bjdong_cd = bjdong.find_bjdong_cd(sgg_cd, umd_nm)
        if not bjdong_cd:
            return fail("읍/면/동 코드 매칭에 실패했습니다.")

        sgg_text_val = f"{si_do} {sgg_nm}".strip()
        plat_gb, bun2, ji2 = parse_jibun(jibun_str)

    sgg_text = sgg_text_val

    # ── 1순위: 이미 마스터에 있는 건물이면 외부 API 호출 없이 즉시 처리 ──────────
    cur.execute(
        """SELECT id, building_name, lodging_type, lodging_type_detail, lodging_subtype,
                  road_address, name_pending
           FROM master_buildings WHERE sgg_cd=%s AND umd_nm=%s AND jibun=%s""",
        (sgg_cd, umd_nm, jibun_str),
    )
    existing = cur.fetchone()

    if existing and existing["lodging_type"]:
        # 이미 용도가 확정된 건물 → API 호출 불필요
        master_id = existing["id"]
        label     = existing["lodging_type"]
        detail    = existing["lodging_type_detail"] or ""
        subtype   = existing["lodging_subtype"] or ""
        building_name = existing["building_name"] or f"{umd_nm} {jibun_str}"
        name_pending  = bool(existing["name_pending"])
        road_addr_final = existing["road_address"] or road_address

        # building_name_hint가 있고 name_pending 상태면 힌트로 갱신
        if building_name_hint and name_pending:
            cur.execute("""
                UPDATE master_buildings
                   SET building_name=%s, name_pending=FALSE,
                       building_name_source='user', building_name_candidate_count=0
                 WHERE id=%s
            """, (building_name_hint, master_id))
            building_name = building_name_hint
            name_pending  = False

        mismatch_note = ""
        if suggested_lodging_type and suggested_lodging_type != label:
            mismatch_note = f" (제출하신 예상 용도 '{suggested_lodging_type}'와 다르게, 건축물대장 확인 결과는 '{label}'입니다.)"

        cur.execute("""
            UPDATE building_requests
            SET status='verified', verified_lodging_type=%s, master_building_id=%s, processed_at=NOW()
            WHERE id=%s
        """, (label, master_id, request_id))
        conn.commit()
        cur.close(); conn.close()

        if name_pending:
            return jsonify({
                "status": "verified",
                "message": (
                    f"용도는 '{label}'(으)로 확인되어 등록되었습니다.{mismatch_note} "
                    f"건물명은 아직 임시명({building_name})입니다. "
                    "추후 관리자 검토 후 확정됩니다."
                ),
                "lodging_type": label, "building_name": building_name, "name_pending": True,
            })
        return jsonify({
            "status": "verified",
            "message": f"'{building_name}'이(가) '{label}'(으)로 확인되어 등록되었습니다.{mismatch_note} "
                       "다음 실거래 갱신부터 이 건물의 거래가 표시됩니다.",
            "lodging_type": label, "building_name": building_name, "name_pending": False,
        })

    # ── 2순위: DB에 없거나 용도 미확정 → 건축물대장 API 실시간 조회 ───────────────
    try:
        label, detail, subtype, title, reason = classify_lodging_type(sgg_cd, bjdong_cd, plat_gb, bun2, ji2)
    except Exception as e:
        # data.go.kr 일일 쿼터 소진 → 사용자에게 명확한 안내
        if "429" in str(e):
            return fail(
                "건축물대장 API 일일 조회 한도에 도달했습니다. "
                "내일 오전에 다시 시도해주세요. (매일 자정 이후 초기화됩니다)"
            )
        return fail("건축물대장 조회 중 오류가 발생했습니다. 잠시 후 다시 시도해주세요.")

    if label is None:
        return fail(f"건축물대장으로 확인한 결과 판정이 어렵습니다 ({reason}). "
                     "집합건축물(생숙/호텔/콘도)이 맞는지 다시 확인해주세요.")

    # 검증 통과 → 사용자가 뭐라고 골랐든 상관없이, 여기서 확정된 label만 반영
    api_bld_nm = resolve_api_building_name(title)
    if api_bld_nm:
        building_name = api_bld_nm
        name_pending  = False
    else:
        building_name = f"{umd_nm} {jibun_str}"
        name_pending  = True
    road_addr_final = title["new_plat_plc"] or title["plat_plc"] or road_address

    if existing:
        # 용도 미확정 상태로 있던 기존 행 갱신
        master_id = existing["id"]
        cur.execute("""
            UPDATE master_buildings
            SET lodging_type=%s, lodging_type_detail=%s, lodging_subtype=%s, verified_at=NOW(),
                zip_code=COALESCE(zip_code, NULLIF(%s,''))
            WHERE id=%s
        """, (label, detail, subtype, zip_code_val, master_id))
        if api_bld_nm:
            cur.execute("""
                UPDATE master_buildings
                   SET building_name=%s, name_pending=FALSE,
                       building_name_source='official', building_name_candidate_count=0
                WHERE id=%s AND name_pending IS TRUE
            """, (api_bld_nm, master_id))
        else:
            existing_name = (existing["building_name"] or "").strip()
            if existing_name in ("", "-", "(이름 미상)"):
                cur.execute("""
                    UPDATE master_buildings
                       SET building_name=%s, name_pending=TRUE,
                           building_name_source='pending', building_name_candidate_count=0,
                           building_name_pending_base=%s
                     WHERE id=%s
                """, (f"{umd_nm} {jibun_str}", f"{umd_nm} {jibun_str}", master_id))
    else:
        cur.execute("""
            INSERT INTO master_buildings
                (building_name, road_address, sgg_text, sgg_cd, umd_nm, jibun, units, source,
                 lodging_type, lodging_type_detail, lodging_subtype, verified_at, name_pending,
                 building_name_source, building_name_candidate_count, building_name_pending_base, zip_code)
            VALUES (%s, %s, %s, %s, %s, %s, %s, 'user_submitted', %s, %s, %s, NOW(), %s,
                    %s, 0, %s, NULLIF(%s,''))
            RETURNING id
        """, (building_name, road_addr_final, sgg_text, sgg_cd, umd_nm, jibun_str,
              title["ho_cnt"], label, detail, subtype, name_pending,
              "official" if api_bld_nm else "pending",
              None if api_bld_nm else building_name, zip_code_val))
        master_id = cur.fetchone()["id"]
        _fill_master_coords(cur, master_id, road_addr_final)

    mismatch_note = ""
    if suggested_lodging_type and suggested_lodging_type != label:
        mismatch_note = f" (제출하신 예상 용도 '{suggested_lodging_type}'와 다르게, 건축물대장 확인 결과는 '{label}'입니다.)"

    cur.execute("""
        UPDATE building_requests
        SET status='verified', verified_lodging_type=%s, master_building_id=%s, processed_at=NOW()
        WHERE id=%s
    """, (label, master_id, request_id))
    # 응답 문구/필드는 추정값이 아니라 DB에 실제 저장된 최종 상태를 기준으로 한다.
    # (기존 건물이 이미 확정명인데 이번 API 응답만 비어 있는 경우 등 분기 오류 방지.)
    cur.execute("SELECT building_name, name_pending FROM master_buildings WHERE id=%s", (master_id,))
    final = cur.fetchone()
    building_name = final["building_name"]
    name_pending = bool(final["name_pending"])
    conn.commit()
    cur.close()
    conn.close()
    try:
        mark_master_stats_invalidated("user_verified_building")
    except Exception as e:
        # 건물 승인 커밋은 통계 표식 기록 실패와 분리해 보존한다.
        print(f"[building-request] 통계 원본 캐시 표식 갱신 실패: {repr(e)[:200]}")

    # 명칭 미확정(name_pending)이면 이름까지 확정된 것처럼 오해하지 않도록 문구를 분리한다.
    if name_pending:
        result_message = (
            f"용도는 '{label}'(으)로 확인되어 등록되었습니다.{mismatch_note} "
            f"건물명은 아직 공식 확인 전이라 임시로 '{building_name}'으로 표시됩니다. "
            f"정확한 명칭을 아신다면 건물상세 페이지에서 '건물명 제안하기'로 알려주세요. "
            f"다음 실거래 갱신부터 이 건물의 거래가 표시됩니다."
        )
    else:
        result_message = (
            f"'{building_name}'이(가) '{label}'(으)로 확인되어 등록되었습니다.{mismatch_note} "
            f"다음 실거래 갱신부터 이 건물의 거래가 표시됩니다."
        )
    return jsonify({
        "status": "verified",
        "message": result_message,
        "name_pending": name_pending,
        "building_name": building_name,
        "lodging_type": label,
        "units": title["ho_cnt"],
    })


@app.route("/apply/agent")
def apply_agent_page():
    """중개사 회원신청(C화면) 정적 폼 HTML 서빙.

    카카오맵이 필요 없는 단순 정적 폼이므로 키 주입 없이 그대로 서빙한다.
    """
    html_path = _frontend_html_path("apply_agent.html")
    with open(html_path, encoding="utf-8") as f:
        html = f.read()
    html = _inject_asset_version(html)
    resp = Response(html, mimetype="text/html")
    resp.headers["Cache-Control"] = "no-cache, no-store, must-revalidate"
    return resp


def _handle_apply_upload(applicant_type, allowed_doc_types):
    """C/D 신청서 서류 업로드 공통 처리.

    - multipart/form-data: file(파일) + doc_type(문서 종류)
    - 확장자 pdf/jpg/jpeg/png, 파일당 5MB, 매직 바이트로 실제 내용 검증
    - 저장 후 내부 참조 키(applications/{type}/{uuid}/{doc_type}.{ext})를 반환.
      URL이 아니므로 서명 없이는 외부에서 접근할 수 없다.
    """
    f = request.files.get("file")
    doc_type = (request.form.get("doc_type") or "").strip()
    if not f or not f.filename:
        return jsonify({"ok": False, "message": "파일을 선택해주세요."}), 400
    if doc_type not in allowed_doc_types:
        return jsonify({"ok": False, "message": "허용되지 않은 문서 종류입니다."}), 400

    filename = f.filename
    ext = filename.rsplit(".", 1)[-1].lower() if "." in filename else ""
    if ext not in storage_util.ALLOWED_EXTENSIONS:
        return jsonify({"ok": False, "message": "PDF, JPG, PNG 파일만 업로드할 수 있습니다."}), 400

    data = f.read(storage_util.MAX_FILE_BYTES + 1)
    if len(data) > storage_util.MAX_FILE_BYTES:
        return jsonify({"ok": False, "message": "파일 크기는 5MB 이하여야 합니다."}), 400
    if len(data) < 16:
        return jsonify({"ok": False, "message": "파일이 비어 있거나 손상되었습니다."}), 400
    if not storage_util.check_magic_bytes(data, ext):
        return jsonify({"ok": False, "message": "파일 내용이 확장자와 일치하지 않습니다. 실제 PDF/JPG/PNG 파일만 업로드해주세요."}), 400

    key = storage_util.build_doc_key(applicant_type, doc_type, ext)
    try:
        storage_util.upload_doc(key, data)
    except Exception:
        app.logger.exception("서류 업로드 실패 (%s/%s)", applicant_type, doc_type)
        return jsonify({"ok": False, "message": "파일 저장 중 오류가 발생했습니다. 잠시 후 다시 시도해주세요."}), 500

    return jsonify({"ok": True, "doc_ref": key})


@app.route("/api/apply/agent/upload", methods=["POST"])
@limiter.limit("10 per hour")
def apply_agent_upload():
    """중개사 신청 서류 업로드 (비로그인, IP 기준 rate limit)."""
    # 여권용 사진은 화면에 <img>로 노출되므로 이미지 파일만 허용 (PDF 차단 — 운영업체 로고와 동일)
    if (request.form.get("doc_type") or "").strip() == "photo":
        f = request.files.get("file")
        ext = f.filename.rsplit(".", 1)[-1].lower() if f and f.filename and "." in f.filename else ""
        if ext not in storage_util.LOGO_EXTENSIONS:
            return jsonify({"ok": False, "message": "사진은 JPG 또는 PNG 이미지 파일만 업로드할 수 있습니다."}), 400
    return _handle_apply_upload("agent", storage_util.AGENT_DOC_TYPES)


