    data = request.get_json(force=True, silent=True) or {}
    current_pw = data.get("current_password") or ""
    new_pw = data.get("new_password") or ""
    if len(new_pw) < 8:
        return jsonify({"ok": False, "message": "비밀번호는 8자 이상이어야 합니다."}), 400

    conn = get_conn()
