@app.route("/api/favorites/mine/urgent-alert", methods=["PUT", "DELETE"])
def favorites_mine_urgent_alert():
    """관심단지와 별도로 급매 알림을 켜거나 끈다."""
    u = current_user()
    if not u:
        return jsonify({"ok": False, "message": "로그인이 필요합니다."}), 401
    data = request.get_json(force=True, silent=True) or {}
    try:
        favorite_id = int(data.get("favorite_id") or 0)
    except (TypeError, ValueError):
        favorite_id = 0
    if not favorite_id:
        return jsonify({"ok": False, "message": "관심단지 정보가 올바르지 않습니다."}), 400

    conn = get_conn()
    cur = conn.cursor()
    try:
        if request.method == "DELETE":
            cur.execute("""
                UPDATE user_favorites
                   SET urgent_alert_enabled = FALSE
                 WHERE id = %s AND user_id = %s
             RETURNING id
            """, [favorite_id, u["id"]])
        else:
            try:
                building_id = int(data.get("building_id") or 0)
            except (TypeError, ValueError):
                building_id = 0
            cur.execute("""
                UPDATE user_favorites uf
                   SET urgent_alert_enabled = TRUE,
                       master_building_id = COALESCE(uf.master_building_id, %s)
                 WHERE uf.id = %s
                   AND uf.user_id = %s
                   AND (
                       uf.master_building_id IS NOT NULL
                       OR EXISTS (SELECT 1 FROM master_buildings mb WHERE mb.id = %s)
                   )
             RETURNING id, master_building_id
            """, [building_id or None, favorite_id, u["id"], building_id])
        row = cur.fetchone()
        if not row:
            conn.rollback()
            return jsonify({
                "ok": False,
                "message": "건물 상세와 연결된 관심단지에서만 급매알림을 설정할 수 있습니다.",
            }), 400
        conn.commit()
        return jsonify({
            "ok": True,
            "favorite_id": favorite_id,
            "enabled": request.method != "DELETE",
        })
    finally:
        cur.close()
        conn.close()


@app.route("/api/favorites/mine/signal-alert", methods=["PUT", "DELETE"])
def favorites_mine_signal_alert():
    """숙박알리미 통합 토글 — 실거래·급매·신규매물·신고변동을 함께 관리한다."""
    u = current_user()
    if not u:
        return jsonify({"ok": False, "message": "로그인이 필요합니다."}), 401
    data = request.get_json(force=True, silent=True) or {}
    try:
        favorite_id = int(data.get("favorite_id") or 0)
    except (TypeError, ValueError):
        favorite_id = 0
    if not favorite_id:
        return jsonify({"ok": False, "message": "관심단지 정보가 올바르지 않습니다."}), 400
    try:
        building_id = int(data.get("building_id") or 0)
    except (TypeError, ValueError):
        building_id = 0

    conn = get_conn()
    cur = conn.cursor()
    try:
        if request.method == "PUT":
            cur.execute("""
                UPDATE user_favorites uf
                   SET urgent_alert_enabled = TRUE,
                       new_listing_alert_enabled = TRUE,
                       permit_change_alert_enabled = TRUE,
                       master_building_id = COALESCE(uf.master_building_id, %s)
                 WHERE uf.id = %s
                   AND uf.user_id = %s
                   AND (
                       uf.master_building_id IS NOT NULL
                       OR EXISTS (SELECT 1 FROM master_buildings mb WHERE mb.id = %s)
                   )
             RETURNING id, building_name, address, master_building_id
            """, [building_id or None, favorite_id, u["id"], building_id])
            favorite = cur.fetchone()
            if not favorite:
                conn.rollback()
                return jsonify({
                    "ok": False,
                    "message": "건물 상세와 연결된 관심단지에서만 숙박알리미를 설정할 수 있습니다.",
                }), 400
            # 기존 실거래 알림은 별도 테이블을 유지하되, 통합 버튼은 이를 함께 켠다.
            cur.execute("""
                INSERT INTO user_alert_subscriptions (user_id, building_name, address)
                VALUES (%s, %s, %s)
                ON CONFLICT (user_id, COALESCE(building_name, ''), address) DO NOTHING
            """, [u["id"], favorite["building_name"], favorite["address"]])
            # 사용자의 명시적인 통합 알림 켜기이므로 과거 수신거부 상태도 새 동의로 갱신한다.
            cur.execute("""
                UPDATE users
                   SET weekly_email_enabled = TRUE, updated_weekly_email_at = NOW()
                 WHERE id = %s
            """, [u["id"]])
        else:
            cur.execute("""
                UPDATE user_favorites
                   SET urgent_alert_enabled = FALSE,
                       new_listing_alert_enabled = FALSE,
                       permit_change_alert_enabled = FALSE
                 WHERE id = %s AND user_id = %s
             RETURNING id, building_name, address
            """, [favorite_id, u["id"]])
            favorite = cur.fetchone()
            if not favorite:
                conn.rollback()
                return jsonify({"ok": False, "message": "관심단지를 찾을 수 없습니다."}), 404
            # 통합 버튼으로 끈 경우에만 해당 관심단지의 실거래 구독도 함께 해제한다.
            cur.execute("""
                DELETE FROM user_alert_subscriptions
                 WHERE user_id = %s
                   AND COALESCE(building_name, '') = COALESCE(%s, '')
                   AND address = %s
            """, [u["id"], favorite["building_name"], favorite["address"]])
        conn.commit()
        return jsonify({
            "ok": True,
            "favorite_id": favorite_id,
            "enabled": request.method == "PUT",
        })
    finally:
        cur.close()
        conn.close()


@app.route("/api/favorites/migrate", methods=["POST"])
def favorites_migrate():
    """로그인 직후 1회 호출용. localStorage favKey 배열을 받아 없는 것만 채우고,
    합쳐진 최종 관심키 목록을 돌려준다(프론트가 localStorage를 이 값으로 동기화)."""
    u = current_user()
    if not u:
        return jsonify({"ok": False, "message": "로그인이 필요합니다."}), 401
    data = request.get_json(force=True, silent=True) or {}
    keys = data.get("keys") or []
    pairs = []
    if isinstance(keys, list):
        for token in keys:
            if not isinstance(token, str) or "|" not in token:
                continue
            name, addr = token.split("|", 1)
            addr = addr.strip()
            if not addr:
                continue
            pairs.append((_norm_fav_name(name), addr))
    conn = get_conn()
    cur = conn.cursor()
    try:
        for name, addr in pairs:
            # 표현식 UNIQUE 인덱스 기준 원자적 dedup — 동시요청/중복키 안전
            cur.execute(
                "INSERT INTO user_favorites (user_id, building_name, address) VALUES (%s, %s, %s) "
                "ON CONFLICT (user_id, COALESCE(building_name, ''), address) DO NOTHING",
                (u["id"], name, addr),
            )
        if pairs:
            _best_effort_weekly_email_opt_in(cur, u["id"], "favorites_migrate")
        # migrate 후 MAX_FAVORITES 초과분 제거 — created_at 오래된 순으로 상위 N개만 유지.
        # "가장 오래 저장한 관심단지 우선" 원칙: 최근 추가분(rn > MAX_FAVORITES)을 삭제.
        cur.execute(
            """
            DELETE FROM user_favorites
            WHERE id IN (
                SELECT id FROM (
                    SELECT id,
                           ROW_NUMBER() OVER (
                               PARTITION BY user_id ORDER BY created_at ASC, id ASC
                           ) AS rn
                    FROM user_favorites
                    WHERE user_id = %s
                ) sub
                WHERE rn > %s
            )
            """,
            (u["id"], MAX_FAVORITES),
        )
        conn.commit()
        cur.execute(
            "SELECT building_name, address FROM user_favorites "
            "WHERE user_id = %s ORDER BY created_at ASC, id ASC",
            (u["id"],),
        )
        rows = cur.fetchall()
    finally:
        cur.close()
        conn.close()
    merged = []
    for r in rows:
        nm = r["building_name"]
        merged.append(f"{nm if nm is not None else 'null'}|{r['address']}")
    return jsonify({"ok": True, "keys": merged})


# =====================================================================
# 실거래 알림 구독(user_alert_subscriptions) — user_favorites 와 동일 패턴.
#   관심저장과 독립적으로 켜고 끌 수 있는 별도 테이블. 새 실거래가 들어오면
#   sync_batch.py 가 이 구독을 조회해 notifications 를 만든다.
# =====================================================================

@app.route("/api/alerts/mine")
def alerts_mine():
    """로그인 회원의 실거래 알림 구독 목록 + 각 단지 최신 실거래가 + building_id."""
    u = current_user()
    if not u:
        return jsonify({"ok": False, "message": "로그인이 필요합니다."}), 401
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute("""
            SELECT us.building_name, us.address, us.created_at,
                   lt.price, lt.deal_date, lt.area, lt.floor, lt.deal_type,
                   lt.lodging_type, lt.lodging_type_detail,
                   bid.id AS building_id
            FROM user_alert_subscriptions us
            LEFT JOIN LATERAL (
                SELECT t.price, t.deal_date, t.area, t.floor, t.deal_type,
                       t.lodging_type, t.lodging_type_detail
                FROM transactions t
                WHERE ((us.building_name IS NULL AND t.building_name IS NULL)
                       OR t.building_name = us.building_name)
                  AND t.address = us.address
                ORDER BY t.deal_date DESC, t.id DESC
                LIMIT 1
            ) lt ON TRUE
            LEFT JOIN LATERAL (
                SELECT mb.id
                FROM transactions t2
                JOIN master_buildings mb
                  ON mb.sgg_cd = t2.sgg_cd AND mb.umd_nm = t2.umd_nm AND mb.jibun = t2.jibun
                WHERE ((us.building_name IS NULL AND t2.building_name IS NULL)
                       OR t2.building_name = us.building_name)
                  AND t2.address = us.address
                ORDER BY (mb.building_name = us.building_name) DESC NULLS LAST, mb.id
                LIMIT 1
            ) bid ON TRUE
            WHERE us.user_id = %s
            ORDER BY us.created_at DESC, us.id DESC
        """, (u["id"],))
        rows = [dict(r) for r in cur.fetchall()]
    finally:
        cur.close()
        conn.close()
    # 프론트가 구독 여부 판정에 쓰는 favKey 목록도 함께 내려준다.
    keys = [f"{(r['building_name'] if r['building_name'] is not None else 'null')}|{r['address']}" for r in rows]
    return jsonify({"ok": True, "items": rows, "keys": keys, "total": len(rows)})


