@app.route("/api/agent/profile/<slug>")
def agent_public_profile(slug):
    """중개사 공개 프로필 API — 인증 불필요. approved 상태만 노출."""
    conn = get_conn()
    cur = conn.cursor()
    cur.execute("""
        SELECT id, office_name, owner_name, phone, office_phone, photo_url, intro_text,
               reg_number, office_address
        FROM agents
        WHERE subdomain_slug = %s AND status = 'approved'
    """, [slug])
    agent = cur.fetchone()
    if not agent:
        cur.close()
        conn.close()
        return jsonify({"error": "not found"}), 404
    cur.execute("""
        SELECT ab.master_building_id, mb.building_name, mb.lodging_type,
               COALESCE(ab.sale_count, 0)      AS sale_count,
               COALESCE(ab.jeonse_count, 0)    AS jeonse_count,
               COALESCE(ab.wolse_count, 0)     AS wolse_count,
               COALESCE(ab.shortterm_count, 0) AS shortterm_count,
               (COALESCE(ab.has_priority_badge, FALSE)
                AND (ab.premium_expires_at IS NULL OR ab.premium_expires_at > NOW())) AS is_premium
        FROM agent_buildings ab
        JOIN master_buildings mb ON mb.id = ab.master_building_id
        WHERE ab.agent_id = %s
        ORDER BY mb.building_name
    """, [agent["id"]])
    buildings = [dict(r) for r in cur.fetchall()]
    for b in buildings:
        b["badge_type"] = "premium" if b["is_premium"] else None

    cur.execute("""
        SELECT arb.master_building_id, mb.building_name, mb.lodging_type,
               0 AS sale_count, 0 AS jeonse_count, 0 AS wolse_count, 0 AS shortterm_count
        FROM agent_region_buildings arb
        JOIN master_buildings mb ON mb.id = arb.master_building_id
        JOIN agent_service_regions sr
          ON sr.agent_id = arb.agent_id AND sr.sgg_text = mb.sgg_text
        WHERE arb.agent_id = %s AND sr.expires_at > NOW()
        ORDER BY mb.building_name
    """, [agent["id"]])
    existing_ids = {b["master_building_id"] for b in buildings}
    for r in cur.fetchall():
        if r["master_building_id"] in existing_ids:
            continue
        row = dict(r)
        row["badge_type"] = "region"
        buildings.append(row)

    cur.close()
    conn.close()
    total_listings = sum(
        b["sale_count"] + b["jeonse_count"] + b["wolse_count"] + b["shortterm_count"]
        for b in buildings
    )
    return jsonify({
        "office_name": agent["office_name"],
        "owner_name": agent["owner_name"],
        "phone": agent["phone"],
        "office_phone": agent["office_phone"],
        "office_address": agent["office_address"],
        "reg_number": agent["reg_number"],
        "photo_src": f"/api/partners/agent-photo/{agent['id']}" if agent["photo_url"] else None,
        "intro_text": _render_markdown_safe(agent["intro_text"] or ""),
        "buildings": buildings,
        "building_count": len(buildings),
        "total_listings": total_listings,
    })


@app.route("/api/agent/login", methods=["POST"])
@limiter.limit("5 per minute; 20 per hour")
def agent_login():
    """agents 테이블 기반 이메일/비밀번호 로그인. status='approved'만 허용.
    실패 시 이메일 존재 여부를 드러내지 않도록 통일된 메시지로 401을 반환한다."""
    data = request.get_json(force=True, silent=True) or {}
    email = (data.get("email") or "").strip()
    password = data.get("password") or ""
    fail = jsonify({"ok": False, "message": "이메일 또는 비밀번호가 올바르지 않습니다."}), 401
    if not email or not password:
        return fail

    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            "SELECT id, password_hash, status FROM agents WHERE LOWER(email) = LOWER(%s)",
            (email,),
        )
        row = cur.fetchone()
        if not row or not row["password_hash"] or not check_password_hash(row["password_hash"], password):
            return fail
        if row["status"] != "approved":
            return jsonify({"ok": False, "message": "승인된 중개사 계정이 아닙니다."}), 403
    finally:
        cur.close()
        conn.close()

    session["agent_id"] = row["id"]
    session.permanent = True
    return jsonify({"ok": True})


