def _agent_me_data(agent_id):
    """중개사 대시보드 데이터 조회 — agent_me() 라우트와 관리자 열람 라우트 공용."""
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute("""
            SELECT office_name, owner_name, phone, photo_url, intro_text, intro_title, subdomain_slug,
                   email, reg_number, biz_reg_number, status, office_address, office_phone,
                   COALESCE(is_visible, TRUE) AS is_visible
            FROM agents WHERE id = %s
        """, [agent_id])
        me = cur.fetchone()
        if not me:
            return None
        cur.execute("""
            SELECT ab.master_building_id, mb.building_name, mb.lodging_type,
                   COALESCE(ab.sale_count, 0)      AS sale_count,
                   COALESCE(ab.jeonse_count, 0)    AS jeonse_count,
                   COALESCE(ab.wolse_count, 0)     AS wolse_count,
                   COALESCE(ab.shortterm_count, 0) AS shortterm_count,
                   ab.premium_granted_at,
                   (COALESCE(ab.has_priority_badge, FALSE)
                    AND (ab.premium_expires_at IS NULL OR ab.premium_expires_at > NOW())) AS has_priority_badge,
                    ((SELECT COUNT(*) FROM agent_buildings ab2
                       WHERE ab2.master_building_id = ab.master_building_id
                         AND ab2.agent_id <> ab.agent_id
                         AND ab2.has_priority_badge
                         AND (ab2.premium_expires_at IS NULL OR ab2.premium_expires_at > NOW())
                    ) >= %s) AS occupied_by_other,
                   (SELECT EXISTS(
                       SELECT 1 FROM premium_waitlist pw
                       WHERE pw.master_building_id = ab.master_building_id
                         AND pw.agent_id = ab.agent_id
                   )) AS on_waitlist,
                   (SELECT BOOL_OR(pw.notified_at IS NOT NULL)
                      FROM premium_waitlist pw
                     WHERE pw.master_building_id = ab.master_building_id
                       AND pw.agent_id = ab.agent_id
                   ) AS waitlist_notified
            FROM agent_buildings ab
            JOIN master_buildings mb ON mb.id = ab.master_building_id
            WHERE ab.agent_id = %s
            ORDER BY mb.building_name
        """, [AGENT_BUILDING_BADGE_SLOT_CAP, agent_id])
        buildings = [dict(r) for r in cur.fetchall()]
        cur.execute("""
            SELECT pw.master_building_id, mb.building_name, mb.lodging_type,
                   0 AS sale_count, 0 AS jeonse_count, 0 AS wolse_count, 0 AS shortterm_count,
                   NULL::timestamp AS premium_granted_at,
                   FALSE AS has_priority_badge,
                   TRUE AS occupied_by_other,
                   TRUE AS on_waitlist,
                   TRUE AS waitlist_only,
                   (pw.notified_at IS NOT NULL) AS waitlist_notified
            FROM premium_waitlist pw
            JOIN master_buildings mb ON mb.id = pw.master_building_id
            WHERE pw.agent_id=%s
              AND NOT EXISTS (
                  SELECT 1 FROM agent_buildings ab
                  WHERE ab.agent_id=pw.agent_id
                    AND ab.master_building_id=pw.master_building_id
              )
            ORDER BY mb.building_name
        """, [agent_id])
        buildings.extend(dict(r) for r in cur.fetchall())
    finally:
        cur.close()
        conn.close()
    out = dict(me)
    out["photo_src"] = f"/api/partners/agent-photo/{agent_id}" if out.get("photo_url") else None
    out["buildings"] = buildings
    if out.get("phone"):
        out["phone"] = format_phone(out["phone"])
    if out.get("office_phone"):
        out["office_phone"] = format_phone(out["office_phone"])
    if out.get("biz_reg_number"):
        out["biz_reg_number"] = format_biz_reg_number(out["biz_reg_number"])
    return out


@app.route("/api/agent/me")
@require_agent
def agent_me():
    data = _agent_me_data(session["agent_id"])
    if data is None:
        return jsonify({"ok": False, "message": "계정을 찾을 수 없습니다."}), 404
    return jsonify(data)


@app.route("/api/agent/photo", methods=["POST"])
@require_agent
def agent_photo_upload():
    """마이페이지에서 프로필 사진 업로드/교체 — 신청서 업로드와 동일한 검증."""
    f = request.files.get("file")
    if not f or not f.filename:
        return jsonify({"ok": False, "message": "파일을 선택해주세요."}), 400
    ext = f.filename.rsplit(".", 1)[-1].lower() if "." in f.filename else ""
    if ext not in storage_util.LOGO_EXTENSIONS:
        return jsonify({"ok": False, "message": "JPG 또는 PNG 이미지만 업로드할 수 있습니다."}), 400
    data = f.read(storage_util.MAX_FILE_BYTES + 1)
    if len(data) > storage_util.MAX_FILE_BYTES:
        return jsonify({"ok": False, "message": "파일 크기는 5MB 이하여야 합니다."}), 400
    if len(data) < 16:
        return jsonify({"ok": False, "message": "파일이 비어 있거나 손상되었습니다."}), 400
    if not storage_util.check_magic_bytes(data, ext):
        return jsonify({"ok": False, "message": "파일 내용이 확장자와 일치하지 않습니다. 실제 JPG/PNG 이미지만 업로드해주세요."}), 400
    key = storage_util.build_doc_key("agent", "photo", ext)
    try:
        storage_util.upload_doc(key, data)
    except Exception:
        app.logger.exception("중개사 프로필 사진 업로드 실패")
        return jsonify({"ok": False, "message": "파일 저장 중 오류가 발생했습니다. 잠시 후 다시 시도해주세요."}), 500
    agent_id = session["agent_id"]
    conn = get_conn()
    cur = conn.cursor()
    cur.execute("UPDATE agents SET photo_url=%s WHERE id=%s", [key, agent_id])
    conn.commit()
    cur.close()
    conn.close()
    return jsonify({"ok": True, "photo_src": f"/api/partners/agent-photo/{agent_id}"})


# 정부 인허가 기반 등록번호 필드 — 본인 수정 시 재승인 대기 전환 대상
# ▶ 확정 정책 (2026-08-11):
#   agent          → 재검토 전환 없음 (등록번호 즉시 저장·반영)
#   operator       → 사업자등록번호 변경 시 pending 전환
#   loan_consultant → 대출모집인 등록번호 변경 시 pending 전환 (사업자등록번호는 비대상)
_PARTNER_LICENSE_FIELDS = {
    "agents": {},                                                        # 재검토 없음
    "operators": {"biz_reg_number": "사업자등록번호"},
    "loan_consultants": {"license_number": "대출모집인 등록번호"},       # biz_reg_number 제외
}


def _reapply_if_license_changed(cur, table, row_id, license_changes):
    """등록번호류 필드가 실제로 달라졌으면 status='pending' 전환 + admin_memo 기록용 SET 절 반환.

    license_changes: {필드명: 새 값(숫자 정규화)} — 요청에 포함된 인허가 필드만.
    반환: (extra_sets, extra_params, 재승인 전환 여부)
    3개 PUT 라우트(agent/operator/loan_consultant _me_update)가 공통 재사용.
    """
    field_labels = _PARTNER_LICENSE_FIELDS[table]
    fields = [f for f in field_labels if f in license_changes]
    if not fields:
        return [], [], False
    cur.execute(f"SELECT {', '.join(fields)} FROM {table} WHERE id = %s", [row_id])
    old_row = cur.fetchone() or {}
    notes = []
    for f in fields:
        old_v = _digits_only(old_row.get(f) or "") or (old_row.get(f) or "").strip()
        new_v = license_changes[f] or ""
        if old_v != new_v:
            notes.append(f"[본인수정] {field_labels[f]} 변경 — 재검토 필요 (변경 전: {old_v or '없음'} → 변경 후: {new_v or '없음'})")
    if not notes:
        return [], [], False
    memo = "\n".join(notes)
    extra_sets = [
        "status = 'pending'",
        "admin_memo = CASE WHEN admin_memo IS NULL OR admin_memo = '' THEN %s "
        "ELSE admin_memo || E'\\n' || %s END",
    ]
    return extra_sets, [memo, memo], True


@app.route("/api/agent/me", methods=["PUT"])
@require_agent
def agent_me_update():
    """부분 업데이트 — 전달된 키만 수정. 등록번호류 변경 시 재승인 대기 전환."""
    agent_id = session["agent_id"]
    data = request.get_json(force=True, silent=True) or {}
    allowed = ["phone", "photo_url", "intro_text", "intro_title", "office_name", "owner_name", "email",
               "reg_number", "biz_reg_number", "office_address", "office_phone"]
    sets, params = [], []
    license_changes = {}
    for k in allowed:
        if k in data:
            v = data.get(k)
            if v is not None and not isinstance(v, str):
                return jsonify({"ok": False, "message": f"{k} 값이 올바르지 않습니다."}), 400
            v = (v or "").strip() or None
            if k == "phone":
                # 하이픈 유무와 무관하게 숫자만 저장 + 자릿수 검증 (표시할 때 재포맷)
                v = _digits_only(v) or None
                if v and not _validate_phone_digits(v):
                    return jsonify({"ok": False, "message": "전화번호 형식이 올바르지 않습니다. (숫자 10~11자리)"}), 400
            if k == "photo_url" and v and not (v.startswith("http://") or v.startswith("https://")):
                return jsonify({"ok": False, "message": "사진 URL은 http(s)://로 시작해야 합니다."}), 400
            if k == "intro_title" and v and len(v) > 16:
                return jsonify({"ok": False, "message": "소개글 제목은 16자 이내로 입력해주세요."}), 400
            if k in ("office_name", "owner_name") and not v:
                return jsonify({"ok": False, "message": ("중개사무소명" if k == "office_name" else "대표자명") + "은(는) 비울 수 없습니다."}), 400
            if k == "email":
                if not v or not _EMAIL_RE.match(v):
                    return jsonify({"ok": False, "message": "이메일 형식이 올바르지 않습니다."}), 400
                v = v.lower()
            if k in ("reg_number", "biz_reg_number"):
                v = _digits_only(v) or None
                if v and k == "biz_reg_number" and len(v) != 10:
                    return jsonify({"ok": False, "message": "사업자등록번호 형식이 올바르지 않습니다. (숫자 10자리)"}), 400
                license_changes[k] = v
            sets.append(f"{k} = %s")
            params.append(v)
    if not sets:
        return jsonify({"ok": False, "message": "수정할 항목이 없습니다."}), 400
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(f"UPDATE agents SET {', '.join(sets)} WHERE id = %s",
                    params + [agent_id])
        conn.commit()
    except psycopg2_errors.UniqueViolation:
        conn.rollback()
        return jsonify({"ok": False, "message": "이미 다른 계정에서 사용 중인 이메일 또는 등록번호입니다."}), 400
    except psycopg2_errors.NotNullViolation:
        conn.rollback()
        return jsonify({"ok": False, "message": "필수 항목이 비어 있어 저장할 수 없습니다."}), 400
    finally:
        cur.close()
        conn.close()
    return jsonify({"ok": True})


