@app.route("/api/agent/buildings", methods=["POST"])
@require_agent
def agent_building_add():
    agent_id = session["agent_id"]
    data = request.get_json(force=True, silent=True) or {}
    try:
        mbid = int(data.get("master_building_id"))
    except (TypeError, ValueError):
        return jsonify({"ok": False, "message": "건물 ID가 올바르지 않습니다."}), 400
    conn = get_conn()
    cur = conn.cursor()
    reassigned_count = 0
    try:
        # 같은 중개사의 서로 다른 단지 동시 등록도 무료 담당단지 한도를 넘지 않게 직렬화한다.
        cur.execute("SELECT pg_advisory_xact_lock(%s, %s)", [911002, agent_id])
        cur.execute("SELECT 1 FROM master_buildings WHERE id = %s", [mbid])
        if not cur.fetchone():
            return jsonify({"ok": False, "message": "존재하지 않는 건물입니다."}), 404
        # 무료 담당단지 한도는 모든 파트너 유형에 10개로 동일하다.
        cur.execute("SELECT COUNT(*) c FROM agent_buildings WHERE agent_id = %s", [agent_id])
        if cur.fetchone()["c"] >= AGENT_TRIAL_BUILDING_CAP:
            return jsonify({
                "ok": False,
                "message": f"무료 등록 가능 건물 수({AGENT_TRIAL_BUILDING_CAP}개)를 초과했습니다. 추가 등록은 준비 중입니다.",
            }), 400
        try:
            # 전속단지는 등록과 동시에 단지뱃지를 부여한다. 건물 단위 락으로
            # 동시 등록 때도 건물별 두 자리 정원을 넘지 않게 한다.
            cur.execute("SELECT pg_advisory_xact_lock(%s, %s)", [911001, mbid])
            cur.execute("""
                SELECT COUNT(*) AS count FROM agent_buildings
                WHERE master_building_id=%s
                  AND has_priority_badge
                  AND (premium_expires_at IS NULL OR premium_expires_at > NOW())
            """, [mbid])
            if cur.fetchone()["count"] >= AGENT_BUILDING_BADGE_SLOT_CAP:
                cur.execute("""
                    INSERT INTO premium_waitlist (agent_id, master_building_id)
                    VALUES (%s, %s)
                    ON CONFLICT (agent_id, master_building_id) DO NOTHING
                    RETURNING id, confirmation_sent_at
                """, [agent_id, mbid])
                waitlist_row = cur.fetchone()
                already_waitlisted = waitlist_row is None
                if waitlist_row is None:
                    cur.execute("""
                        SELECT id, confirmation_sent_at
                        FROM premium_waitlist
                        WHERE agent_id=%s AND master_building_id=%s
                        FOR UPDATE
                    """, [agent_id, mbid])
                    waitlist_row = cur.fetchone()
                if waitlist_row and not waitlist_row["confirmation_sent_at"]:
                    cur.execute("""
                        SELECT a.office_name, a.email, mb.building_name
                        FROM agents a
                        JOIN master_buildings mb ON mb.id=%s
                        WHERE a.id=%s
                    """, [mbid, agent_id])
                    recipient = cur.fetchone()
                    if recipient:
                        sent, message = _send_badge_waitlist_confirmation(
                            recipient["email"],
                            recipient["office_name"],
                            f"'{recipient['building_name']}' 단지뱃지",
                        )
                        if sent:
                            cur.execute(
                                "UPDATE premium_waitlist SET confirmation_sent_at=NOW() WHERE id=%s",
                                [waitlist_row["id"]],
                            )
                        else:
                            app.logger.warning(
                                "단지뱃지 대기 등록 확인 이메일 발송 실패 (agent_id=%s, building_id=%s): %s",
                                agent_id, mbid, message,
                            )
                conn.commit()
                return jsonify({
                    "ok": True,
                    "waitlisted": True,
                    "already_waitlisted": already_waitlisted,
                    "message": (
                        "이미 이 단지뱃지 대기 명단에 등록되어 있습니다."
                        if already_waitlisted
                        else "단지뱃지 정원이 가득 차 대기 등록되었습니다. 빈자리가 생기면 이메일로 알려드립니다."
                    ),
                })
            cur.execute("""
                INSERT INTO agent_buildings
                    (agent_id, master_building_id, has_priority_badge, premium_granted_at, premium_expires_at)
                VALUES (%s, %s, TRUE, NOW(), %s::timestamp)
            """, [agent_id, mbid, PARTNER_BADGE_FREE_EXPIRES_AT])
            cur.execute(
                "DELETE FROM premium_waitlist WHERE agent_id=%s AND master_building_id=%s",
                [agent_id, mbid],
            )
            reassigned_count = _reassign_house_requests_for_building(cur, agent_id, mbid)
            conn.commit()
        except psycopg2_errors.UniqueViolation:
            conn.rollback()
            return jsonify({"ok": False, "message": "이미 등록된 단지입니다."}), 400
    finally:
        cur.close()
        conn.close()
    if reassigned_count:
        conn2 = get_conn()
        cur2 = conn2.cursor()
        try:
            cur2.execute("SELECT phone, email FROM agents WHERE id=%s", [agent_id])
            ph = cur2.fetchone()
        finally:
            cur2.close()
            conn2.close()
        reassigned_url = _create_short_link("/agent/dashboard?tab=leads-sell")
        reassigned_notice = (
            f"확인: {reassigned_url}"
            if reassigned_url else "대시보드에서 확인해주세요"
        )
        reassigned_sms = (
            f"[홈앤스테이] 대기 중이던 매물의뢰 {reassigned_count}건이 배정되었습니다. "
            f"{reassigned_notice}"
        )
        if ph and ph["phone"]:
            sent, msg = send_sms(ph["phone"], reassigned_sms)
            app.logger.info("[lead-sms] kind=listing-reassigned agent_id=%s bytes=%d sent=%s",
                            agent_id, len(reassigned_sms.encode("utf-8")), sent)
        else:
            sent, msg = False, "중개사 전화번호 없음"
        if ph and ph.get("email"):
            safe_url = _html.escape(reassigned_url or _public_base_url(), quote=True)
            email_body = f"""
            <div style="font-family:'Apple SD Gothic Neo','Malgun Gothic',sans-serif;max-width:560px;margin:0 auto;color:#16202E;">
              <h2 style="font-size:18px;border-bottom:2px solid #B4863F;padding-bottom:8px;">홈앤스테이 (HOME &amp; STAY)</h2>
              <p style="font-size:15px;font-weight:700;">대기 중이던 매물의뢰가 배정되었습니다.</p>
              <p style="font-size:14px;">총 <b>{int(reassigned_count)}</b>건이 담당 중개사님에게 배정되었습니다.</p>
              <p><a href="{safe_url}" style="display:inline-block;background:#B4863F;color:#fff;text-decoration:none;padding:10px 16px;border-radius:6px;font-weight:700;">관리자 화면에서 확인하기</a></p>
              <p style="font-size:12px;color:#6b7280;">링크는 발송 후 72시간 동안 유효합니다.</p>
            </div>
            """
            try:
                email_sent, email_msg = send_email(
                    ph["email"], "[홈앤스테이] 대기 중인 매물의뢰가 배정되었습니다", email_body
                )
                if not email_sent:
                    app.logger.warning("재배정 매물의뢰 이메일 발송 실패 (agent_id=%s): %s",
                                       agent_id, email_msg)
            except Exception:
                email_sent, email_msg = False, "이메일 발송 중 오류"
                app.logger.exception("재배정 매물의뢰 이메일 발송 중 오류 (agent_id=%s)", agent_id)
    return jsonify({"ok": True, "reassigned": reassigned_count})


@app.route("/api/agent/buildings/<int:mbid>/claim-premium", methods=["POST"])
@require_agent
def agent_building_claim_premium(mbid):
    """구버전 대시보드 호환용: 신규 전속단지는 등록 시 이미 단지뱃지가 부여된다."""
    agent_id = session["agent_id"]
    conn = get_conn()
    cur = conn.cursor()
    cur.execute(
        "SELECT premium_granted_at FROM agent_buildings WHERE agent_id=%s AND master_building_id=%s",
        [agent_id, mbid])
    row = cur.fetchone()
    if not row:
        cur.close(); conn.close()
        return jsonify({"ok": False, "message": "본인의 전속 단지만 신청할 수 있습니다."}), 400
    if row["premium_granted_at"]:
        cur.close(); conn.close()
        return jsonify({"ok": False, "message": "이미 이 단지는 프리미엄 혜택을 사용했습니다."}), 400
    # 건물 단위로 직렬화해 동시 신청도 활성 두 자리 정원을 넘지 못하게 한다.
    cur.execute("SELECT pg_advisory_xact_lock(%s, %s)", [911001, mbid])
    cur.execute("""
        SELECT COUNT(*) AS count FROM agent_buildings
        WHERE master_building_id=%s AND agent_id<>%s
          AND has_priority_badge
          AND (premium_expires_at IS NULL OR premium_expires_at > NOW())
    """, [mbid, agent_id])
    if cur.fetchone()["count"] >= AGENT_BUILDING_BADGE_SLOT_CAP:
        cur.execute("""
            INSERT INTO premium_waitlist (agent_id, master_building_id)
            VALUES (%s, %s)
            ON CONFLICT (agent_id, master_building_id) DO NOTHING
            RETURNING id, confirmation_sent_at
        """, [agent_id, mbid])
        waitlist_row = cur.fetchone()
        already_waitlisted = waitlist_row is None
        if waitlist_row is None:
            cur.execute("""
                SELECT id, confirmation_sent_at
                FROM premium_waitlist
                WHERE agent_id=%s AND master_building_id=%s
                FOR UPDATE
            """, [agent_id, mbid])
            waitlist_row = cur.fetchone()
        if waitlist_row and not waitlist_row["confirmation_sent_at"]:
            cur.execute("""
                SELECT a.office_name, a.email, mb.building_name
                FROM agents a
                JOIN master_buildings mb ON mb.id=%s
                WHERE a.id=%s
            """, [mbid, agent_id])
            recipient = cur.fetchone()
            if recipient:
                sent, message = _send_badge_waitlist_confirmation(
                    recipient["email"],
                    recipient["office_name"],
                    f"'{recipient['building_name']}' 단지뱃지",
                )
                if sent:
                    cur.execute(
                        "UPDATE premium_waitlist SET confirmation_sent_at=NOW() WHERE id=%s",
                        [waitlist_row["id"]],
                    )
                else:
                    app.logger.warning(
                        "단지뱃지 대기 등록 확인 이메일 발송 실패 (agent_id=%s, building_id=%s): %s",
                        agent_id, mbid, message,
                    )
        conn.commit()
        cur.close()
        conn.close()
        return jsonify({
            "ok": True,
            "waitlisted": True,
            "already_waitlisted": already_waitlisted,
            "message": (
                "이미 이 단지뱃지 대기 명단에 등록되어 있습니다."
                if already_waitlisted
                else "단지뱃지 정원이 가득 차 대기 등록되었습니다. 빈자리가 생기면 이메일로 알려드립니다."
            ),
        })
    cur.execute("""
        UPDATE agent_buildings
        SET has_priority_badge = TRUE, premium_granted_at = NOW(),
            premium_expires_at = %s::timestamp
        WHERE agent_id=%s AND master_building_id=%s
    """, [PARTNER_BADGE_FREE_EXPIRES_AT, agent_id, mbid])
    # 본인이 신청에 성공한 대기 건만 정리한다. 다른 대기자는 다음 빈자리 알림 대상이다.
    cur.execute(
        "DELETE FROM premium_waitlist WHERE agent_id=%s AND master_building_id=%s",
        [agent_id, mbid],
    )
    # 이 단지가 본인의 지역담당단지 목록에 있었다면 정리(중복 방지)
    cur.execute("DELETE FROM agent_region_buildings WHERE agent_id=%s AND master_building_id=%s",
                [agent_id, mbid])
    conn.commit()
    cur.close()
    conn.close()
    return jsonify({"ok": True})


@app.route("/api/agent/service-regions", methods=["POST"])
@require_agent
def agent_service_region_claim():
    """시군구 단위 지역뱃지를 등록하고, 정원이 찼으면 대기 명단에 넣는다."""
    agent_id = session["agent_id"]
    data = request.get_json(force=True, silent=True) or {}
    sgg = (data.get("sgg_text") or "").strip()
    if not sgg:
        return jsonify({"ok": False, "message": "시·군·구를 선택해주세요."}), 400
    conn = get_conn()
    cur = conn.cursor()
    try:
        # 자유 문자열로 존재하지 않는 지역의 정원을 우회하지 못하게 마스터의 실제 시군구만 허용한다.
        cur.execute("""
            SELECT 1
            FROM master_buildings
            WHERE sgg_text=%s
            LIMIT 1
        """, [sgg])
        if not cur.fetchone():
            return jsonify({"ok": False, "message": "선택한 시·군·구를 확인할 수 없습니다."}), 400

        # 중개사별 1개 제한과 시군구별 활성 정원을 직렬화한다.
        cur.execute("SELECT pg_advisory_xact_lock(%s, %s)", [911006, agent_id])
        cur.execute("""
            SELECT 1 FROM agent_service_regions
            WHERE agent_id=%s AND sgg_text=%s AND expires_at > NOW()
        """, [agent_id, sgg])
        if cur.fetchone():
            return jsonify({"ok": False, "message": "이미 이 시·군·구의 지역뱃지를 사용 중입니다."}), 400
        cur.execute("""
            SELECT COUNT(*) AS count
            FROM agent_service_regions
            WHERE agent_id=%s AND expires_at > NOW()
        """, [agent_id])
        if cur.fetchone()["count"] >= AGENT_TRIAL_REGION_CAP:
            return jsonify({
                "ok": False,
                "message": "담당 지역은 1개만 등록할 수 있습니다. 지역을 바꾸려면 먼저 기존 지역을 삭제해주세요.",
            }), 400
        cur.execute("SELECT pg_advisory_xact_lock(%s, hashtext(%s))",
                    [911009, sgg])
        cur.execute("""
            SELECT COUNT(*) AS count
            FROM agent_service_regions
            WHERE sgg_text=%s
              AND expires_at > NOW()
              AND agent_id <> %s
        """, [sgg, agent_id])
        if cur.fetchone()["count"] >= AGENT_REGION_SGG_SLOT_CAP:
            cur.execute("""
                INSERT INTO region_badge_waitlist (agent_id, sgg_text)
                VALUES (%s, %s)
                ON CONFLICT (agent_id, sgg_text) DO NOTHING
                RETURNING id, confirmation_sent_at
            """, [agent_id, sgg])
            waitlist_row = cur.fetchone()
            already_waitlisted = waitlist_row is None
            if waitlist_row is None:
                cur.execute("""
                    SELECT id, confirmation_sent_at
                    FROM region_badge_waitlist
                    WHERE agent_id=%s AND sgg_text=%s
                    FOR UPDATE
                """, [agent_id, sgg])
                waitlist_row = cur.fetchone()
            if waitlist_row and not waitlist_row["confirmation_sent_at"]:
                cur.execute("SELECT office_name, email FROM agents WHERE id=%s", [agent_id])
                recipient = cur.fetchone()
                if recipient:
                    sent, message = _send_badge_waitlist_confirmation(
                        recipient["email"],
                        recipient["office_name"],
                        f"'{sgg}' 지역뱃지",
                    )
                    if sent:
                        cur.execute(
                            "UPDATE region_badge_waitlist SET confirmation_sent_at=NOW() WHERE id=%s",
                            [waitlist_row["id"]],
                        )
                    else:
                        app.logger.warning(
                            "지역뱃지 대기 등록 확인 이메일 발송 실패 (agent_id=%s, sgg=%s): %s",
                            agent_id, sgg, message,
                        )
            conn.commit()
            return jsonify({
                "ok": True,
                "waitlisted": True,
                "already_waitlisted": already_waitlisted,
                "message": (
                    "이미 이 지역뱃지 대기 명단에 등록되어 있습니다."
                    if already_waitlisted
                    else "지역뱃지 정원이 가득 차 대기 등록되었습니다. 빈자리가 생기면 이메일로 알려드립니다."
                ),
            })
        cur.execute("""
            INSERT INTO agent_service_regions (agent_id, sgg_text, umd_nm, granted_at, expires_at)
            VALUES (%s, %s, NULL, NOW(), %s::timestamp)
            ON CONFLICT (agent_id, sgg_text) DO UPDATE
            SET granted_at=NOW(), expires_at=EXCLUDED.expires_at, reminder_sent_at=NULL
        """, [agent_id, sgg, PARTNER_BADGE_FREE_EXPIRES_AT])
        cur.execute(
            "DELETE FROM region_badge_waitlist WHERE agent_id=%s AND sgg_text=%s",
            [agent_id, sgg],
        )
        conn.commit()
    finally:
        cur.close()
        conn.close()
    return jsonify({"ok": True})


