@app.route("/api/agent/buildings/<int:mbid>/notify-me", methods=["POST"])
@require_agent
def agent_building_notify_me(mbid):
    """단지부동산 대기 알림 등록 — 해당 단지에 다른 부동산이 입점해 있을 때
    자리가 나면 이메일로 알려준다."""
    agent_id = session["agent_id"]
    conn = get_conn()
    cur = conn.cursor()
    cur.execute(
        "SELECT 1 FROM agent_buildings WHERE agent_id=%s AND master_building_id=%s",
        [agent_id, mbid])
    if not cur.fetchone():
        cur.close(); conn.close()
        return jsonify({"ok": False, "message": "본인의 전속 단지만 알림 등록할 수 있습니다."}), 400
    try:
        cur.execute("""
            INSERT INTO premium_waitlist (agent_id, master_building_id)
            VALUES (%s, %s)
            ON CONFLICT (agent_id, master_building_id) DO NOTHING
            RETURNING id, confirmation_sent_at
        """, [agent_id, mbid])
        waitlist_row = cur.fetchone()
        already_waitlisted = waitlist_row is None
        if waitlist_row is None:
            cur.execute("""
                SELECT id, confirmation_sent_at
                FROM premium_waitlist
                WHERE agent_id=%s AND master_building_id=%s
                FOR UPDATE
            """, [agent_id, mbid])
            waitlist_row = cur.fetchone()
        if waitlist_row and not waitlist_row["confirmation_sent_at"]:
            cur.execute("""
                SELECT a.office_name, a.email, mb.building_name
                FROM agents a
                JOIN master_buildings mb ON mb.id=%s
                WHERE a.id=%s
            """, [mbid, agent_id])
            recipient = cur.fetchone()
            if recipient:
                sent, message = _send_badge_waitlist_confirmation(
                    recipient["email"],
                    recipient["office_name"],
                    f"'{recipient['building_name']}' 단지뱃지",
                )
                if sent:
                    cur.execute(
                        "UPDATE premium_waitlist SET confirmation_sent_at=NOW() WHERE id=%s",
                        [waitlist_row["id"]],
                    )
                else:
                    app.logger.warning(
                        "단지뱃지 대기 등록 확인 이메일 발송 실패 (agent_id=%s, building_id=%s): %s",
                        agent_id, mbid, message,
                    )
        conn.commit()
    finally:
        cur.close()
        conn.close()
    return jsonify({
        "ok": True,
        "waitlisted": True,
        "already_waitlisted": already_waitlisted,
        "message": (
            "이미 이 단지뱃지 대기 명단에 등록되어 있습니다."
            if already_waitlisted
            else "단지뱃지 대기 등록이 완료되었습니다. 빈자리가 생기면 이메일로 알려드립니다."
        ),
    })


@app.route("/api/agent/tier-status")
@require_agent
def agent_tier_status():
    """대시보드에서 버튼 상태(신청가능/적용중/만료) 판단용."""
    agent_id = session["agent_id"]
    conn = get_conn()
    cur = conn.cursor()
    cur.execute("""
        SELECT ab.master_building_id, ab.premium_granted_at, ab.premium_expires_at,
               mb.building_name
        FROM agent_buildings ab
        JOIN master_buildings mb ON mb.id = ab.master_building_id
        WHERE ab.agent_id=%s AND ab.premium_granted_at IS NOT NULL
    """, [agent_id])
    buildings = [dict(r) for r in cur.fetchall()]
    cur.execute(
        """SELECT sgg_text, granted_at, expires_at
           FROM agent_service_regions
           WHERE agent_id=%s AND expires_at > NOW()
           ORDER BY granted_at DESC""", [agent_id])
    regions = [dict(r) for r in cur.fetchall()]
    cur.execute("""
        SELECT arb.master_building_id, mb.building_name
        FROM agent_region_buildings arb
        JOIN master_buildings mb ON mb.id = arb.master_building_id
        WHERE arb.agent_id = %s
    """, [agent_id])
    region_buildings = [dict(r) for r in cur.fetchall()]
    cur.execute("""
        SELECT sgg_text, created_at, confirmation_sent_at, notified_at
        FROM region_badge_waitlist
        WHERE agent_id=%s
        ORDER BY created_at DESC
    """, [agent_id])
    region_waitlist = [dict(r) for r in cur.fetchall()]
    cur.close()
    conn.close()
    for r in buildings + regions + region_waitlist:
        for k in (
            "premium_granted_at", "premium_expires_at", "granted_at", "expires_at",
            "created_at", "confirmation_sent_at", "notified_at",
        ):
            if k in r and r[k]:
                r[k] = r[k].isoformat()
    return jsonify({
        "ok": True,
        "buildings": buildings,
        "regions": regions,
        "region_buildings": region_buildings,
        "region_waitlist": region_waitlist,
    })


