def _limited_whole_listing_approx_location(cur, listing):
    """제한공개 매물에만 제공할 충분히 넓은 지역 단위의 좌표를 만든다.

    한두 건의 건물 평균은 사실상 원 건물 좌표가 될 수 있으므로, 동 단위는 최소
    5건, 시군구 단위 폴백은 최소 10건의 좌표가 모인 경우에만 제공한다.
    """
    sgg_text = (listing.get("sgg_text") or "").strip()
    umd_nm = (listing.get("umd_nm") or "").strip()
    if sgg_text and umd_nm:
        cur.execute("""
            SELECT ROUND(AVG(lat)::numeric, 3) AS approx_lat,
                   ROUND(AVG(lng)::numeric, 3) AS approx_lng
              FROM master_buildings
             WHERE sgg_text = %s AND umd_nm = %s
               AND lat IS NOT NULL AND lng IS NOT NULL
            HAVING COUNT(*) >= 5
        """, [sgg_text, umd_nm])
        row = cur.fetchone()
        if row and row["approx_lat"] is not None and row["approx_lng"] is not None:
            return {
                "approx_lat": float(row["approx_lat"]),
                "approx_lng": float(row["approx_lng"]),
                "approx_location_label": "동 중심 근처",
            }
    if sgg_text:
        cur.execute("""
            SELECT ROUND(AVG(lat)::numeric, 2) AS approx_lat,
                   ROUND(AVG(lng)::numeric, 2) AS approx_lng
              FROM master_buildings
             WHERE sgg_text = %s
               AND lat IS NOT NULL AND lng IS NOT NULL
            HAVING COUNT(*) >= 10
        """, [sgg_text])
        row = cur.fetchone()
        if row and row["approx_lat"] is not None and row["approx_lng"] is not None:
            return {
                "approx_lat": float(row["approx_lat"]),
                "approx_lng": float(row["approx_lng"]),
                "approx_location_label": "시군구 중심 근처",
            }
    return None


def _apply_limited_whole_listing_privacy(listing, approx_location=None):
    """제한공개 건물전체 매물은 지역·카드 표시에 필요한 값만 남긴다.

    판매자가 공개용으로 직접 작성한 설명은 카드에 제공한다. 로그인 회원은 월
    매출과 승계융자도 볼 수 있지만, 사진·건물 보조정보처럼 정확한 건물을
    역추적할 수 있는 값은 어떤 공개 목록 응답에도 포함하지 않는다.
    """
    location_label = " ".join(
        part for part in (listing.get("sgg_text"), listing.get("umd_nm")) if part
    ).strip() or "지역 비공개"
    for key in (
        "building_id", "lat", "lng", "photo_url", "photos",
        "building_info_overrides", "key_money_krw", "annual_revenue_krw",
        "remodeling_info", "verified_phone", "phone_tail",
    ):
        listing.pop(key, None)
    listing["building_name"] = location_label
    listing["is_limited_listing"] = True
    listing["location_precision"] = "approximate"
    if approx_location:
        listing.update(approx_location)
    return listing


_LISTING_CHECKLIST_KEYS = {
    "building_violation", "building_specification", "ownership_rights", "zoning",
    "lodging_report", "fire_safety", "parking", "nearby_competition",
    "nearest_subway", "revenue", "sales_mix", "finance", "staff_transition",
    "sale_reason",
}


def _checklist_amount(value):
    """체크리스트 공개용 금액(만원 단위)을 짧은 읽기 형식으로 표시한다."""
    if value is None:
        return None
    try:
        return f"{int(value):,}만원"
    except (TypeError, ValueError):
        return None


def _whole_listing_checklist_data(cur, listing_id, user_id=None):
    """공개 건물전체 매물의 체크리스트 항목·자동값을 만든다.

    제한공개 매물은 카드만으로 정확한 건물을 특정할 수 없어 이 API에서도
    체크리스트를 제공하지 않는다. 이로써 자동값이 별도 정보 유출 경로가 되는 것을 막는다.
    """
    cur.execute("""
        SELECT lr.id, lr.master_building_id AS building_id, lr.deal_type, lr.price_krw,
               lr.succession_loan_krw, lr.monthly_revenue_krw, lr.annual_revenue_krw,
               lr.short_stay_ratio, lr.ota_revenue_ratio, lr.description,
               COALESCE(lr.building_info_overrides, '{}'::jsonb) AS building_info_overrides,
               mb.main_purps_nm, mb.strct_nm, mb.tot_area, mb.use_apr_day, mb.jiyuk_nm,
               CASE WHEN mb.tot_pkng_cnt IS NULL AND mb.indr_auto_utcnt IS NULL
                              AND mb.oudr_auto_utcnt IS NULL AND mb.indr_mech_utcnt IS NULL
                              AND mb.oudr_mech_utcnt IS NULL
                    THEN NULL
                    ELSE COALESCE(mb.tot_pkng_cnt, 0) + COALESCE(mb.indr_auto_utcnt, 0)
                       + COALESCE(mb.oudr_auto_utcnt, 0) + COALESCE(mb.indr_mech_utcnt, 0)
                       + COALESCE(mb.oudr_mech_utcnt, 0)
               END AS parking_spaces
          FROM listing_requests lr
          JOIN master_buildings mb ON mb.id = lr.master_building_id
         WHERE lr.id = %s
           AND lr.deal_mode = 'direct'
           AND COALESCE(lr.transaction_target, 'unit') = 'whole'
           AND COALESCE(lr.disclosure_scope, 'limited') = 'public'
           AND COALESCE(lr.status, '') NOT IN ('withdrawn', '철회됨', '보류')
    """, [listing_id])
    row = cur.fetchone()
    if not row:
        return None

    listing = dict(row)
    overrides = listing.get("building_info_overrides") or {}
    if not isinstance(overrides, dict):
        overrides = {}
    context = _whole_listing_context_data(cur, listing["building_id"]) or {}
    nearby = context.get("nearby_lodgings") or {}
    nearby_total = sum(int(nearby.get(kind) or 0) for kind in ("일반", "관광", "복합", "생활"))
    subway = context.get("subway") or {}
    financial_visible = bool(user_id)

    total_area = overrides.get("total_area_sqm", listing.get("tot_area"))
    parking_spaces = overrides.get("parking_spaces", listing.get("parking_spaces"))
    zoning = overrides.get("zoning", listing.get("jiyuk_nm"))
    structure = overrides.get("structure", listing.get("strct_nm"))
    approval_date = overrides.get("approval_date", listing.get("use_apr_day"))
    building_bits = []
    if listing.get("main_purps_nm"):
        building_bits.append(f"용도 {listing['main_purps_nm']}")
    if structure:
        building_bits.append(f"구조 {structure}")
    if total_area is not None:
        try:
            building_bits.append(f"연면적 {float(total_area):,.1f}㎡")
        except (TypeError, ValueError):
            building_bits.append(f"연면적 {total_area}")
    if approval_date:
        building_bits.append(f"사용승인일 {approval_date}")

    revenue_bits = [
        value for value in (
            f"월매출 {_checklist_amount(listing.get('monthly_revenue_krw'))}"
            if listing.get("monthly_revenue_krw") is not None else None,
            f"연매출 {_checklist_amount(listing.get('annual_revenue_krw'))}"
            if listing.get("annual_revenue_krw") is not None else None,
        ) if value
    ]
    sales_mix_bits = [
        value for value in (
            f"대실 비율 {float(listing['short_stay_ratio']):g}%"
            if listing.get("short_stay_ratio") is not None else None,
            f"OTA 매출 비중 {float(listing['ota_revenue_ratio']):g}%"
            if listing.get("ota_revenue_ratio") is not None else None,
        ) if value
    ]
    finance_value = None
    if listing.get("deal_type") == "매매" and listing.get("price_krw") is not None:
        loan = int(listing.get("succession_loan_krw") or 0)
        acquisition = int(listing["price_krw"]) - loan + int(round(int(listing["price_krw"]) * 0.061))
        finance_value = (
            f"승계융자 {_checklist_amount(listing.get('succession_loan_krw')) or '없음'} · "
            f"실인수가 {_checklist_amount(acquisition)}"
        )

    items = [
        {
            "key": "building_violation", "category": "건물", "question": "위반건축물 여부",
            "type": "official", "link_url": "https://www.gov.kr/portal/main/nologin",
            "link_label": "정부24 건축물대장 바로가기",
        },
        {
            "key": "building_specification", "category": "건물",
            "question": "용도·구조·연면적·사용승인일", "type": "auto",
            "value": " · ".join(building_bits) or None,
        },
        {
            "key": "ownership_rights", "category": "권리", "question": "소유권·압류·가압류",
            "type": "official", "link_url": "https://www.iros.go.kr/",
            "link_label": "대법원 인터넷등기소 바로가기",
        },
    ]
    if zoning:
        items.append({
            "key": "zoning", "category": "법적", "question": "용도지역·토지이용계획",
            "type": "auto", "value": f"용도지역 {zoning}",
        })
    items.extend([
        {
            "key": "lodging_report", "category": "법적", "question": "숙박업 영업신고·행정처분 이력",
            "type": "official", "link_url": "https://www.gov.kr/portal/main/nologin",
            "link_label": "관할 시군구 위생과 안내 바로가기",
        },
        {
            "key": "fire_safety", "category": "소방", "question": "소방점검·완비증명",
            "type": "official", "link_url": "https://www.nfa.go.kr/",
            "link_label": "관할 소방서 안내 바로가기",
        },
        {
            "key": "parking", "category": "주차", "question": "법정 주차대수",
            "type": "auto",
            "value": f"주차 {int(parking_spaces):,}대" if parking_spaces is not None else None,
        },
        {
            "key": "nearby_competition", "category": "입지", "question": "반경 500m 경쟁업소 수",
            "type": "auto", "value": f"숙박 경쟁업소 {nearby_total:,}곳",
        },
        {
            "key": "nearest_subway", "category": "입지", "question": "최근접 지하철역 도보거리",
            "type": "auto",
            "value": (
                f"{subway.get('station_name') or subway.get('name')}까지 도보 약 {subway['walk_minutes']}분"
                if subway.get("walk_minutes") is not None else None
            ),
        },
        {
            "key": "revenue", "category": "매출", "question": "월매출·연매출", "type": "seller",
            "value": " · ".join(revenue_bits) if financial_visible else None,
            "requires_login": bool(revenue_bits) and not financial_visible,
        },
        {
            "key": "sales_mix", "category": "매출", "question": "대실/숙박 비율, OTA매출비중",
            "type": "seller", "value": " · ".join(sales_mix_bits) or None,
        },
        {
            "key": "finance", "category": "금융", "question": "승계융자·실인수가", "type": "seller",
            "value": finance_value if financial_visible else None,
            "requires_login": bool(finance_value) and not financial_visible,
        },
        {
            "key": "staff_transition", "category": "운영", "question": "직원 고용승계 여부",
            "type": "seller",
            "value": "매도자 설명란의 운영 현황을 확인하세요" if listing.get("description") else None,
        },
        {
            "key": "sale_reason", "category": "출구", "question": "매도사유", "type": "seller",
            "value": "매도자 설명란을 확인하세요" if listing.get("description") else None,
        },
    ])
    return {
        "listing_id": listing["id"],
        "items": items,
        "total_items": len(_LISTING_CHECKLIST_KEYS),
        "is_authenticated": bool(user_id),
    }


@app.route("/api/listing-requests/<int:lr_id>/checklist")
@limiter.limit("60 per minute")
def public_listing_checklist(lr_id):
    """건물전체 공개매물의 체크리스트 데이터와 로그인 회원 진행 상태."""
    user = current_user()
    conn = get_conn()
    cur = conn.cursor()
    try:
        data = _whole_listing_checklist_data(cur, lr_id, user["id"] if user else None)
        if not data:
            return jsonify({"ok": False, "message": "체크리스트를 제공하지 않는 매물입니다."}), 404
        checked_keys = []
        if user:
            cur.execute("""
                SELECT item_key FROM listing_checklist_progress
                 WHERE user_id = %s AND listing_request_id = %s
            """, [user["id"], lr_id])
            checked_keys = [row["item_key"] for row in cur.fetchall()]
        return jsonify({"ok": True, **data, "checked_keys": checked_keys})
    finally:
        cur.close()
        conn.close()


@app.route("/api/listing-requests/<int:lr_id>/checklist/progress", methods=["POST"])
@limiter.limit("120 per minute")
def save_listing_checklist_progress(lr_id):
    """로그인 회원의 체크리스트 항목 상태를 항목 단위로 저장한다."""
    user = current_user()
    if not user:
        return jsonify({"ok": False, "message": "로그인이 필요합니다."}), 401
    payload = request.get_json(silent=True) or {}
    item_key = payload.get("item_key")
    checked = payload.get("checked")
    if not isinstance(item_key, str) or item_key not in _LISTING_CHECKLIST_KEYS:
        return jsonify({"ok": False, "message": "체크 항목이 올바르지 않습니다."}), 400
    if not isinstance(checked, bool):
        return jsonify({"ok": False, "message": "체크 상태가 올바르지 않습니다."}), 400
    conn = get_conn()
    cur = conn.cursor()
    try:
        if not _whole_listing_checklist_data(cur, lr_id, user["id"]):
            return jsonify({"ok": False, "message": "체크리스트를 제공하지 않는 매물입니다."}), 404
        if checked:
            cur.execute("""
                INSERT INTO listing_checklist_progress (user_id, listing_request_id, item_key)
                VALUES (%s, %s, %s)
                ON CONFLICT (user_id, listing_request_id, item_key)
                DO UPDATE SET checked_at = NOW()
            """, [user["id"], lr_id, item_key])
        else:
            cur.execute("""
                DELETE FROM listing_checklist_progress
                 WHERE user_id = %s AND listing_request_id = %s AND item_key = %s
            """, [user["id"], lr_id, item_key])
        conn.commit()
        return jsonify({"ok": True, "item_key": item_key, "checked": checked})
    finally:
        cur.close()
        conn.close()


@app.route("/api/listing-requests", methods=["POST"])
@limiter.limit("5 per hour")
def create_listing_request():
    user = current_user()
    if not user:
        return jsonify({"ok": False, "message": "로그인이 필요합니다."}), 401

    data = request.get_json(force=True, silent=True) or {}
    try:
        mb_id = int(data.get("master_building_id") or 0)
    except (TypeError, ValueError):
        mb_id = 0
    deal_type = (data.get("deal_type") or "").strip()
    transaction_target = (data.get("transaction_target") or data.get("listing_target") or "unit").strip()
    if transaction_target not in _LISTING_TARGETS:
        return jsonify({"ok": False, "message": "거래대상은 개별호실 또는 건물전체 중 하나여야 합니다."}), 400
    whole_values = None
    if transaction_target == "whole":
        whole_values, whole_error = _whole_listing_values(data)
        if whole_error:
            return jsonify({"ok": False, "message": whole_error}), 400
        deal_type = whole_values["deal_type"]
    deal_mode = (data.get("deal_mode") or "broker").strip()
    if deal_mode not in ("direct", "broker"):
        deal_mode = "broker"
    desired_price = (data.get("desired_price") or "").strip()[:100]

    # 전용면적(㎡) — 선택, 양수 숫자만 허용
    try:
        area_sqm = float(data.get("area_sqm") or 0)
        area_sqm = round(area_sqm, 2) if 0 < area_sqm < 100000 else None
    except (TypeError, ValueError):
        area_sqm = None
    dong = (str(data.get("dong") or "").strip()[:20]) or None
    ho = (str(data.get("ho") or "").strip()[:20]) or None
    registrant_type_raw = (data.get("registrant_type") or "owner").strip()
    registrant_type = registrant_type_raw if registrant_type_raw in (
        "owner", "building_owner", "business", "agent", "other"
    ) else "owner"

    # 거래유형별 구조화 희망가(만원 단위 정수, 선택) — 단기임대는 자유텍스트만 사용.
    # 값이 전달됐는데 정수가 아니거나 범위(1~1억 만원)를 벗어나면 400 (조용한 유실 방지).
    def _parse_krw(field, allowed):
        v = data.get(field)
        if v is None or v == "":
            return None, None
        if not allowed:
            return None, f"{field}는 이 거래유형에서 사용할 수 없습니다."
        try:
            n = int(v)
        except (TypeError, ValueError):
            return None, "희망가는 만원 단위 숫자로 입력해주세요."
        if not (0 < n <= 1_000_000):
            return None, "입력 가능한 최대 금액을 초과했습니다 (최대 100억 만원)."
        return n, None
    if transaction_target == "whole":
        price_krw = whole_values["price_krw"]
        price_krw_max = None
        monthly_rent_krw = whole_values["monthly_rent_krw"]
        deposit_krw = None
        yield_rent_krw = None
        err1 = err2 = err3 = err4 = err5 = None
    else:
        price_krw, err1 = _parse_krw(
            "price_krw",
            deal_type in ("매매", "전세", "월세")
            or (registrant_type == "business" and deal_type == "단기임대"),
        )
        price_krw_max, err2 = _parse_krw(
            "price_krw_max", registrant_type == "business" and deal_type in ("월세", "단기임대")
        )
        monthly_rent_krw, err3 = _parse_krw("monthly_rent_krw", deal_type in ("월세", "매매"))
        deposit_krw, err4 = _parse_krw("deposit_krw", True)
        yield_rent_krw, err5 = _parse_krw("yield_rent_krw", True)
    try:
        room_count_value = data.get("room_count")
        room_count = int(room_count_value) if room_count_value not in (None, "") else None
        if room_count is not None and not (0 < room_count <= 100_000):
            raise ValueError
    except (TypeError, ValueError):
        return jsonify({"ok": False, "message": "총 호실수는 1~100,000 사이의 숫자로 입력해주세요."}), 400
    if registrant_type != "business" and transaction_target != "whole":
        room_count = None
    if err1 or err2 or err3 or err4 or err5:
        return jsonify({"ok": False, "message": err1 or err2 or err3 or err4 or err5}), 400
    if price_krw_max is not None and price_krw is None:
        return jsonify({"ok": False, "message": "가격범위의 최저가를 먼저 입력해주세요."}), 400
    if price_krw_max is not None and price_krw_max < price_krw:
        return jsonify({"ok": False, "message": "최고가는 최저가 이상으로 입력해주세요."}), 400
    description = (str(data.get("description") or "").strip()[:500]) or None
    # 클라이언트가 보낸 수익률은 신뢰하지 않는다. 매매가/보증금/월 임대료로 서버에서 재계산한다.
    yield_base_price = price_krw if deal_type == "매매" else None
    yield_base_rent = yield_rent_krw if yield_rent_krw is not None else monthly_rent_krw
    yield_rate = (
        round((yield_base_rent * 12) / max(yield_base_price - (deposit_krw or 0), 1) * 100, 1)
        if yield_base_price and yield_base_rent else None
    )
    if transaction_target == "whole":
        desired_price = (str(data.get("desired_price") or "").strip()[:100] or
                         f"{deal_type} {price_krw:,}만원" if price_krw else deal_type)
        area_sqm = None
        dong = ho = None
        yield_rate = None

    if not mb_id:
        return jsonify({"ok": False, "message": "건물 정보가 없습니다."}), 400
    if transaction_target == "unit" and deal_type not in _LISTING_DEAL_TYPES:
        return jsonify({"ok": False, "message": "거래유형은 매매/전세/월세/단기임대 중 하나여야 합니다."}), 400

    # 진행 방식과 무관하게 인증된 계정 전화번호만 매물 연락처로 사용한다.
    # 클라이언트가 임의로 보낸 contact_phone은 신뢰하지 않는다.
    _conn2 = get_conn(); _cur2 = _conn2.cursor()
    try:
        _cur2.execute("SELECT phone, phone_verified FROM users WHERE id=%s", [user["id"]])
        _urow = _cur2.fetchone()
    finally:
        _cur2.close(); _conn2.close()
    if not _urow or not _urow.get("phone_verified") or not _urow.get("phone"):
        return jsonify({"ok": False, "message": "매물 등록은 휴대폰 인증이 필요합니다. 인증 후 다시 시도해주세요."}), 400
    verified_phone = _urow["phone"]
    contact_phone = verified_phone

    urgent_email_jobs = []
    new_listing_email_jobs = []
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute("""
            SELECT id, building_name, sgg_text, road_address, jibun_address, umd_nm, jibun
              FROM master_buildings
             WHERE id = %s
        """, [mb_id])
        bld = cur.fetchone()
        if not bld:
            return jsonify({"ok": False, "message": "등록되지 않은 건물입니다."}), 404

        # 사업주 매물은 현재 대표 영업신고와 사용자·건물별 인증 캐시를
        # 서버에서 다시 확인한다. 클라이언트가 인증 단계를 건너뛰어도 우회할 수 없다.
        matched_permit_number = None
        if registrant_type == "business":
            verification = _business_verification_context(cur, mb_id, user["id"])
            if verification["representative"]:
                current_permit = verification["representative_permit"]
                cached = verification["cached"]
                if not current_permit:
                    return jsonify({
                        "ok": False,
                        "message": "이 건물의 영업신고번호를 확인할 수 없습니다. 관리자에게 문의해주세요.",
                    }), 503
                if not cached or cached.get("permit_number") != current_permit:
                    return jsonify({
                        "ok": False,
                        "message": "사업주 영업신고번호 인증이 필요합니다. 인증 후 다시 시도해주세요.",
                        "requires_business_verification": True,
                    }), 403
                matched_permit_number = current_permit

        # 직거래는 중개사 라우팅 없이 공개 등록만
        if deal_mode == "broker":
            routed_agent_id, routed_reason, notify_agents = _route_lead(cur, mb_id)
        else:
            routed_agent_id, routed_reason, notify_agents = None, "direct", []

        # 표시번호 채번 — deal_mode별 독립 시퀀스 (시퀀스명은 위 검증된 deal_mode로만 결정)
        seq_name = "listing_seq_direct" if deal_mode == "direct" else "listing_seq_broker"
        cur.execute(f"""
            INSERT INTO listing_requests
                (user_id, master_building_id, deal_type, desired_price, contact_phone,
                 routed_agent_id, routed_reason, price_krw, price_krw_max, monthly_rent_krw, room_count,
                  deal_mode, verified_phone, area_sqm, dong, ho, registrant_type,
                 description, deposit_krw, yield_rate, yield_rent_krw, display_seq,
                  matched_permit_number, transaction_target, succession_loan_krw, key_money_krw,
                  monthly_revenue_krw, annual_revenue_krw, short_stay_ratio, ota_revenue_ratio,
                  operation_status, closed_at, remodeling_info, is_urgent, disclosure_scope,
                  building_info_overrides)
            VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s,
                    nextval('{seq_name}'),
                    %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
            RETURNING id
        """, [user["id"], mb_id, deal_type, desired_price or None, contact_phone,
               routed_agent_id, routed_reason, price_krw, price_krw_max, monthly_rent_krw, room_count,
               deal_mode, verified_phone, area_sqm, dong, ho, registrant_type,
               description, deposit_krw, yield_rate, yield_rent_krw,
                matched_permit_number, transaction_target,
               whole_values["succession_loan_krw"] if whole_values else None,
               whole_values["key_money_krw"] if whole_values else None,
               whole_values["monthly_revenue_krw"] if whole_values else None,
               whole_values["annual_revenue_krw"] if whole_values else None,
                whole_values["short_stay_ratio"] if whole_values else None,
                whole_values["ota_revenue_ratio"] if whole_values else None,
               whole_values["operation_status"] if whole_values else None,
               whole_values["closed_at"] if whole_values else None,
               whole_values["remodeling_info"] if whole_values else None,
               whole_values["is_urgent"] if whole_values else False,
               whole_values["disclosure_scope"] if whole_values else None,
               json.dumps(whole_values["building_info_overrides"]) if whole_values else "{}"])
        req_id = cur.fetchone()["id"]
        # 이력 기록 — 최초 접수
        cur.execute(
            "INSERT INTO listing_request_history (listing_request_id, action, after_data) "
            "VALUES (%s, 'created', %s)",
            [req_id, json.dumps({
                "deal_type": deal_type, "desired_price": desired_price,
                "price_krw": price_krw, "price_krw_max": price_krw_max,
                "monthly_rent_krw": monthly_rent_krw, "room_count": room_count,
                "contact_phone": contact_phone, "area_sqm": area_sqm, "dong": dong, "ho": ho,
                "registrant_type": registrant_type, "description": description,
                "deposit_krw": deposit_krw, "yield_rent_krw": yield_rent_krw,
                "yield_rate": yield_rate,
                "matched_permit_number": matched_permit_number,
                "transaction_target": transaction_target,
                "succession_loan_krw": whole_values["succession_loan_krw"] if whole_values else None,
                "key_money_krw": whole_values["key_money_krw"] if whole_values else None,
                "monthly_revenue_krw": whole_values["monthly_revenue_krw"] if whole_values else None,
                "annual_revenue_krw": whole_values["annual_revenue_krw"] if whole_values else None,
                "short_stay_ratio": whole_values["short_stay_ratio"] if whole_values else None,
                "ota_revenue_ratio": whole_values["ota_revenue_ratio"] if whole_values else None,
                "operation_status": whole_values["operation_status"] if whole_values else None,
                "closed_at": str(whole_values["closed_at"]) if whole_values and whole_values["closed_at"] else None,
                "remodeling_info": whole_values["remodeling_info"] if whole_values else None,
                "is_urgent": whole_values["is_urgent"] if whole_values else False,
                "disclosure_scope": whole_values["disclosure_scope"] if whole_values else None,
                "building_info_overrides": whole_values["building_info_overrides"] if whole_values else {},
            })]
        )
        _best_effort_weekly_email_opt_in(cur, user["id"], "listing_request")
        # 신규 공개 건물전체 직거래는 급매 또는 일반 신규매물 중 한 신호만 예약한다.
        # 알림 저장 실패는 SAVEPOINT로 격리해 매물 등록·이력 커밋을 되돌리지 않는다.
        listing_alert_values = {
            "deal_mode": deal_mode, "transaction_target": transaction_target,
            "disclosure_scope": (whole_values or {}).get("disclosure_scope"),
            "status": "submitted", "master_building_id": mb_id,
            "deal_type": deal_type, "is_urgent": (whole_values or {}).get("is_urgent"),
            "price_krw": price_krw,
        }
        if _is_public_whole_direct_listing(listing_alert_values):
            urgent_tier = _urgent_tier_for_listing(cur, listing_alert_values)
            if urgent_tier:
                cur.execute("SAVEPOINT urgent_listing_alerts")
                try:
                    urgent_email_jobs = _queue_urgent_listing_alerts(
                        cur, req_id, mb_id, bld["building_name"],
                        bld.get("road_address") or bld.get("jibun_address"),
                        price_krw, urgent_tier, deal_type,
                    )
                    cur.execute("RELEASE SAVEPOINT urgent_listing_alerts")
                except Exception:
                    cur.execute("ROLLBACK TO SAVEPOINT urgent_listing_alerts")
                    cur.execute("RELEASE SAVEPOINT urgent_listing_alerts")
                    urgent_email_jobs = []
                    app.logger.exception("급매 알림 예약 실패(listing_id=%s)", req_id)
            else:
                cur.execute("SAVEPOINT new_listing_alerts")
                try:
                    new_listing_email_jobs = _queue_new_listing_alerts(
                        cur, req_id, mb_id, bld["building_name"],
                        bld.get("road_address") or bld.get("jibun_address"),
                        price_krw, deal_type,
                    )
                    cur.execute("RELEASE SAVEPOINT new_listing_alerts")
                except Exception:
                    cur.execute("ROLLBACK TO SAVEPOINT new_listing_alerts")
                    cur.execute("RELEASE SAVEPOINT new_listing_alerts")
                    new_listing_email_jobs = []
                    app.logger.exception("신규매물 알림 예약 실패(listing_id=%s)", req_id)
        conn.commit()
    finally:
        cur.close()
        conn.close()

    # SMS 알림 — 실패해도 접수 자체는 성공 처리 (send_sms는 예외를 던지지 않음)
    sms_body = (
        f"[홈앤스테이] 매물의뢰 접수 — {bld['building_name']} / {deal_type}"
        + (f" / 희망가 {desired_price}" if desired_price else "")
        + f" / 연락처 {contact_phone}"
    )
    # 배정자에게는 배정 문자, 나머지 담당중개사에게는 참고용 문자만 보낸다.
    # 단축 링크 생성·SMS·이메일은 모두 best-effort 알림 단계다.
    sms_results, _ = _notify_lead_agents(
        notify_agents, routed_agent_id, sms_body, "listing",
        f"/agent/dashboard?tab=leads-sell&request_id={req_id}",
        bld["building_name"], deal_type, desired_price, contact_phone,
    )
    for urgent_email_job in urgent_email_jobs:
        _send_urgent_listing_email(urgent_email_job)
    for new_listing_email_job in new_listing_email_jobs:
        _send_new_listing_email(new_listing_email_job)

    return jsonify({
        "ok": True, "id": req_id,
        "routed_reason": routed_reason, "routed_agent_id": routed_agent_id,
        "notified": len([r for r in sms_results if r["sent"]]),
    })


@app.route("/api/buy-requests", methods=["POST"])
@limiter.limit("5 per hour")
def create_buy_request():
    """매수의뢰 접수 + 중개사 라우팅 — listing_requests와 동일 라우팅 로직."""
    user = current_user()
    if not user:
        return jsonify({"ok": False, "message": "로그인이 필요합니다."}), 401

    data = request.get_json(force=True, silent=True) or {}
    try:
        mb_id = int(data.get("master_building_id") or 0)
    except (TypeError, ValueError):
        mb_id = 0
    deal_type = (data.get("deal_type") or "").strip()
    desired_price = (data.get("desired_price") or "").strip()[:100]
    contact_phone = (data.get("contact_phone") or "").strip()

    def _parse_krw(field, allowed):
        v = data.get(field)
        if v is None or v == "":
            return None, None
        if not allowed:
            return None, f"{field}는 이 거래유형에서 사용할 수 없습니다."
        try:
            n = int(v)
        except (TypeError, ValueError):
            return None, "희망가는 만원 단위 숫자로 입력해주세요."
        if not (0 < n <= 1_000_000):
            return None, "입력 가능한 최대 금액을 초과했습니다 (최대 100억 만원)."
        return n, None
    price_krw, err1 = _parse_krw("price_krw", deal_type in ("매매", "전세", "월세"))
    monthly_rent_krw, err2 = _parse_krw("monthly_rent_krw", deal_type == "월세")
    if err1 or err2:
        return jsonify({"ok": False, "message": err1 or err2}), 400

    if not mb_id:
        return jsonify({"ok": False, "message": "건물 정보가 없습니다."}), 400
    if deal_type not in _LISTING_DEAL_TYPES:
        return jsonify({"ok": False, "message": "거래유형은 매매/전세/월세/단기임대 중 하나여야 합니다."}), 400
    if not _PHONE_RE.match(contact_phone):
        return jsonify({"ok": False, "message": "연락처 형식이 올바르지 않습니다. 예) 010-1234-5678"}), 400
    contact_phone = _digits_only(contact_phone)
    verified_phone = _digits_only(user.get("phone") or "")
    if not user.get("phone_verified") or not verified_phone or contact_phone != verified_phone:
        return jsonify({"ok": False, "message": "휴대폰 인증을 완료한 연락처로만 매수의뢰할 수 있습니다."}), 400

    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute("SELECT id, building_name, sgg_text FROM master_buildings WHERE id = %s", [mb_id])
        bld = cur.fetchone()
        if not bld:
            return jsonify({"ok": False, "message": "등록되지 않은 건물입니다."}), 404

        routed_agent_id, routed_reason, notify_agents = _route_lead(cur, mb_id)

        cur.execute("""
            INSERT INTO buy_requests
                (user_id, master_building_id, deal_type, desired_price, contact_phone,
                 routed_agent_id, routed_reason, price_krw, monthly_rent_krw)
            VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s)
            RETURNING id
        """, [user["id"], mb_id, deal_type, desired_price or None, contact_phone,
              routed_agent_id, routed_reason, price_krw, monthly_rent_krw])
        req_id = cur.fetchone()["id"]
        _best_effort_weekly_email_opt_in(cur, user["id"], "buy_request")
        conn.commit()
    finally:
        cur.close()
        conn.close()

    sms_body = (
        f"[홈앤스테이] 매수의뢰 접수 — {bld['building_name']} / {deal_type}"
        + (f" / 희망가 {desired_price}" if desired_price else "")
        + f" / 연락처 {contact_phone}"
    )
    sms_results, _ = _notify_lead_agents(
        notify_agents, routed_agent_id, sms_body, "buy",
        f"/agent/dashboard?tab=leads-buy&request_id={req_id}",
        bld["building_name"], deal_type, desired_price, contact_phone,
    )

    return jsonify({
        "ok": True, "id": req_id,
        "routed_reason": routed_reason, "routed_agent_id": routed_agent_id,
        "notified": len([r for r in sms_results if r["sent"]]),
    })


@app.route("/api/buy-requests/mine")
def my_buy_requests():
    """내가 접수한 매수의뢰 목록 — 마이페이지용."""
    user = current_user()
    if not user:
        return jsonify({"ok": False, "message": "로그인이 필요합니다."}), 401
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute("""
            SELECT br.id, br.deal_type, br.desired_price, br.status, br.routed_agent_id,
                   to_char(br.created_at, 'YYYY-MM-DD') AS created_date,
                   mb.id AS building_id, mb.building_name,
                   a.office_name AS agent_office_name, a.subdomain_slug AS agent_slug
            FROM buy_requests br
            JOIN master_buildings mb ON mb.id = br.master_building_id
            LEFT JOIN agents a ON a.id = br.routed_agent_id
            WHERE br.user_id = %s
            ORDER BY br.created_at DESC
        """, [user["id"]])
        items = [dict(r) for r in cur.fetchall()]
    finally:
        cur.close()
        conn.close()
    return jsonify({"ok": True, "items": items})


@app.route("/api/buy-requests/<int:req_id>", methods=["DELETE"])
def withdraw_buy_request(req_id):
    """본인이 접수한 매수의뢰를 철회 상태로 전환한다."""
    user = current_user()
    if not user:
        return jsonify({"ok": False, "message": "로그인이 필요합니다."}), 401
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute("""
            SELECT status
              FROM buy_requests
             WHERE id = %s AND user_id = %s
             FOR UPDATE
        """, [req_id, user["id"]])
        row = cur.fetchone()
        if not row:
            conn.rollback()
            return jsonify({"ok": False, "message": "존재하지 않거나 권한이 없는 매수의뢰입니다."}), 404
        if row["status"] == "done":
            conn.rollback()
            return jsonify({"ok": False, "message": "완료된 매수의뢰는 철회할 수 없습니다."}), 400
        cur.execute("UPDATE buy_requests SET status = %s WHERE id = %s", ["철회됨", req_id])
        conn.commit()
    finally:
        cur.close()
        conn.close()
    return jsonify({"ok": True, "status": "철회됨"})


@app.route("/api/listing-requests/mine")
def my_listing_requests():
    """내가 접수한 매물의뢰 목록 — 마이페이지 '매물의뢰 현황'용 (건물명/거래유형/상태)."""
    user = current_user()
    if not user:
        return jsonify({"ok": False, "message": "로그인이 필요합니다."}), 401
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute("""
            SELECT lr.id, lr.deal_type, lr.desired_price, lr.status,
                   lr.price_krw, lr.price_krw_max, lr.monthly_rent_krw, lr.room_count,
                   lr.contact_phone, lr.deal_mode, lr.area_sqm, lr.dong, lr.ho, lr.registrant_type,
                    lr.description, lr.deposit_krw, lr.yield_rent_krw, lr.yield_rate,
                    COALESCE(lr.transaction_target, 'unit') AS transaction_target,
                    lr.succession_loan_krw, lr.key_money_krw, lr.monthly_revenue_krw,
                     lr.annual_revenue_krw, lr.short_stay_ratio, lr.ota_revenue_ratio,
                     lr.matched_permit_number, lr.operation_status,
                    to_char(lr.closed_at, 'YYYY-MM-DD') AS closed_at,
                    lr.remodeling_info, COALESCE(lr.is_urgent, FALSE) AS is_urgent,
                    COALESCE(lr.disclosure_scope, 'limited') AS disclosure_scope,
                    COALESCE(lr.building_info_overrides, '{}'::jsonb) AS building_info_overrides,
                   (SELECT COUNT(*) FROM chat_rooms cr
                    WHERE cr.listing_request_id = lr.id) AS chat_room_count,
                    to_char(COALESCE(lr.updated_at, lr.created_at), 'YYYY-MM-DD') AS created_date,
                   mb.id AS building_id, mb.building_name,
                   a.office_name AS agent_office_name, a.subdomain_slug AS agent_slug,
                   COALESCE((
                     SELECT json_agg(json_build_object(
                        'id', lp.id, 'url', '/api/listing-photos/img/' || lp.image_key,
                        'is_public', COALESCE(lp.is_public, TRUE)
                     ) ORDER BY lp.sort_order ASC, lp.id ASC)
                     FROM listing_photos lp WHERE lp.listing_request_id = lr.id
                   ), '[]'::json) AS photos
            FROM listing_requests lr
            JOIN master_buildings mb ON mb.id = lr.master_building_id
            LEFT JOIN agents a ON a.id = lr.routed_agent_id
            WHERE lr.user_id = %s
            ORDER BY COALESCE(lr.updated_at, lr.created_at) DESC
        """, [user["id"]])
        items = [dict(r) for r in cur.fetchall()]
    finally:
        cur.close()
        conn.close()
    return jsonify({"ok": True, "items": items})


_ROOM_INVENTORY_STATUSES = {"입실", "공실"}
_ROOM_INVENTORY_CHANNELS = {"OTA전용", "장박가능"}
_ROOM_INVENTORY_MAX_FLOOR = 999
_ROOM_INVENTORY_MAX_ROOMS_PER_FLOOR = 99


def _parse_room_monthly_rent(value):
    """방별 월세(만원)는 비워둘 수 있고, 입력하면 양의 정수만 허용한다."""
    if value is None or value == "":
        return None, None
    if isinstance(value, bool) or not isinstance(value, int) or value < 1:
        return None, "월세는 1만원 이상의 숫자로 입력해주세요."
    return value, None


def _parse_room_deposit(value):
    """방별 보증금(만원)은 비워둘 수 있고, 입력하면 양의 정수만 허용한다."""
    if value is None or value == "":
        return None, None
    if isinstance(value, bool) or not isinstance(value, int) or value < 1:
        return None, "보증금은 1만원 이상의 숫자로 입력해주세요."
    return value, None


def _parse_contract_end_date(value):
    """YYYY-MM-DD 계약만기일만 허용한다. 빈 값은 만기일 미입력으로 본다."""
    if value is None or value == "":
        return None, None
    if not isinstance(value, str):
        return None, "계약만기일은 YYYY-MM-DD 형식으로 입력해주세요."
    try:
        return datetime.strptime(value.strip(), "%Y-%m-%d").date(), None
    except ValueError:
        return None, "계약만기일은 YYYY-MM-DD 형식으로 입력해주세요."


def _parse_room_floor(value, *, required=False):
    """방 재고 층은 1~999 정수만 허용한다. 단건 생성에서는 생략할 수 있다."""
    if value is None or value == "":
        return (None, "층 번호를 입력해주세요.") if required else (None, None)
    if isinstance(value, bool) or not isinstance(value, int):
        return None, "층 번호는 숫자로 입력해주세요."
    if not 1 <= value <= _ROOM_INVENTORY_MAX_FLOOR:
        return None, f"층 번호는 1~{_ROOM_INVENTORY_MAX_FLOOR} 사이로 입력해주세요."
    return value, None


def _parse_room_channel(value, *, default=None):
    """OTA전용 또는 장박가능 채널만 허용한다."""
    if value is None:
        return default, None
    if not isinstance(value, str):
        return None, "채널은 OTA전용 또는 장박가능만 선택할 수 있습니다."
    channel = value.strip()
    if channel not in _ROOM_INVENTORY_CHANNELS:
        return None, "채널은 OTA전용 또는 장박가능만 선택할 수 있습니다."
    return channel, None


def _owned_listing_request(cur, listing_request_id, user_id):
    """매물의뢰가 존재하는지와 현재 사용자의 소유 여부를 분리해 확인한다."""
    cur.execute(
        "SELECT id, user_id FROM listing_requests WHERE id = %s",
        [listing_request_id],
    )
    row = cur.fetchone()
    if not row:
        return None, (jsonify({"ok": False, "message": "매물의뢰를 찾을 수 없습니다."}), 404)
    if row["user_id"] != user_id:
        return None, (jsonify({"ok": False, "message": "권한이 없습니다."}), 403)
    return row, None


