@app.route("/api/loan-consultant/me", methods=["PUT"])
@require_loan_consultant
def loan_consultant_me_update():
    """phone / intro_text / consultant_products / kakao_chat_url 부분 업데이트 — 전달된 키만 수정."""
    lc_id = session["loan_consultant_id"]
    data = request.get_json(force=True, silent=True) or {}
    sets, params = [], []
    # 상담 가능 상품 — 허용 목록 내 다중 선택, 콤마구분 텍스트로 저장
    if "consultant_products" in data:
        v = data.get("consultant_products")
        if v is None:
            v = []
        if not isinstance(v, list) or any(not isinstance(x, str) for x in v):
            return jsonify({"ok": False, "message": "상담 가능 상품 값이 올바르지 않습니다."}), 400
        invalid = [x for x in v if x not in LOAN_CONSULTANT_PRODUCTS]
        if invalid:
            return jsonify({"ok": False, "message": "허용되지 않은 상담 상품이 포함되어 있습니다."}), 400
        # 허용 목록 순서대로 정렬해 저장 (생활숙박시설 담보대출이 항상 앞)
        ordered = [p for p in LOAN_CONSULTANT_PRODUCTS if p in v]
        sets.append("consultant_products = %s")
        params.append(",".join(ordered) or None)
    # 취급지역 — 허용 목록 내 값만 (신청서와 동일 검증)
    if "service_region" in data:
        v = data.get("service_region")
        if v is not None and not isinstance(v, str):
            return jsonify({"ok": False, "message": "취급지역 값이 올바르지 않습니다."}), 400
        v = (v or "").strip()
        if not v or v not in LOAN_SERVICE_REGIONS:
            return jsonify({"ok": False, "message": "취급지역은 다음 중 하나여야 합니다: " + ", ".join(LOAN_SERVICE_REGIONS)}), 400
        sets.append("service_region = %s")
        params.append(v)
    license_changes = {}
    for k in ["phone", "intro_text", "kakao_chat_url", "office_name", "owner_name", "email",
              "logo_url", "license_number", "biz_reg_number"]:
        if k in data:
            v = data.get(k)
            if v is not None and not isinstance(v, str):
                return jsonify({"ok": False, "message": f"{k} 값이 올바르지 않습니다."}), 400
            v = (v or "").strip() or None
            if k == "phone":
                # 하이픈 유무와 무관하게 숫자만 저장 + 자릿수 검증 (표시할 때 재포맷)
                v = _digits_only(v) or None
                if v and not _validate_phone_digits(v):
                    return jsonify({"ok": False, "message": "전화번호 형식이 올바르지 않습니다. (숫자 10~11자리)"}), 400
            if k == "kakao_chat_url" and v and not _validate_kakao_chat_url(v):
                return jsonify({"ok": False, "message": "카카오톡 상담 링크는 open.kakao.com 주소여야 합니다."}), 400
            if k == "intro_text" and v and len(v) > 5000:
                return jsonify({"ok": False, "message": "소개글은 5000자 이내로 입력해주세요."}), 400
            if k == "logo_url" and v and not (v.startswith("http://") or v.startswith("https://")):
                return jsonify({"ok": False, "message": "로고 URL은 http(s)://로 시작해야 합니다."}), 400
            if k in ("office_name", "owner_name") and not v:
                return jsonify({"ok": False, "message": ("소속 회사/법인명" if k == "office_name" else "상담사 성명") + "은(는) 비울 수 없습니다."}), 400
            if k == "email":
                if not v or not _EMAIL_RE.match(v):
                    return jsonify({"ok": False, "message": "이메일 형식이 올바르지 않습니다."}), 400
                v = v.lower()
            if k == "license_number":
                v = _digits_only(v) or None
                if not v:
                    return jsonify({"ok": False, "message": "대출모집인 등록번호는 비울 수 없습니다."}), 400
                license_changes[k] = v
            if k == "biz_reg_number":
                # 대출상담사 사업자등록번호는 선택 항목 — 비우는 것도 허용.
                # ※ 정책 확정: 사업자등록번호 변경은 재검토 대상 아님 → license_changes에 넣지 않음.
                v = _digits_only(v) or None
                if v and len(v) != 10:
                    return jsonify({"ok": False, "message": "사업자등록번호 형식이 올바르지 않습니다. (숫자 10자리)"}), 400
                # (license_changes에 추가하지 않음 — pending 전환 미트리거)
            sets.append(f"{k} = %s")
            params.append(v)
    if not sets:
        return jsonify({"ok": False, "message": "수정할 항목이 없습니다."}), 400
    conn = get_conn()
    cur = conn.cursor()
    try:
        extra_sets, extra_params, reapproval = _reapply_if_license_changed(cur, "loan_consultants", lc_id, license_changes)
        cur.execute(f"UPDATE loan_consultants SET {', '.join(sets + extra_sets)} WHERE id = %s",
                    params + extra_params + [lc_id])
        conn.commit()
    except psycopg2_errors.UniqueViolation:
        conn.rollback()
        return jsonify({"ok": False, "message": "이미 사용 중인 이메일 또는 등록번호입니다."}), 400
    finally:
        cur.close()
        conn.close()
    return jsonify({"ok": True, "reapproval_required": reapproval})


