@app.route("/api/loan-consultant/buildings", methods=["POST"])
@require_loan_consultant
def loan_consultant_building_add():
    lc_id = session["loan_consultant_id"]
    data = request.get_json(force=True, silent=True) or {}
    try:
        mbid = int(data.get("master_building_id"))
    except (TypeError, ValueError):
        return jsonify({"ok": False, "message": "건물 ID가 올바르지 않습니다."}), 400
    conn = get_conn()
    cur = conn.cursor()
    try:
        # 같은 상담사의 병렬 등록 요청이 담당단지 10개 한도를 우회하지 않게 한다.
        cur.execute("SELECT pg_advisory_xact_lock(%s, %s)", [911004, lc_id])
        cur.execute("SELECT 1 FROM master_buildings WHERE id = %s", [mbid])
        if not cur.fetchone():
            return jsonify({"ok": False, "message": "존재하지 않는 건물입니다."}), 404
        cur.execute("SELECT COUNT(*) c FROM loan_consultant_buildings WHERE loan_consultant_id = %s", [lc_id])
        if cur.fetchone()["c"] >= MAX_FREE_BUILDINGS:
            return jsonify({
                "ok": False,
                "message": f"무료 등록 가능 건물 수({MAX_FREE_BUILDINGS}개)를 초과했습니다.",
            }), 400
        cur.execute("SELECT pg_advisory_xact_lock(%s, %s)", [911010, mbid])
        cur.execute("""
            SELECT COUNT(*) c FROM loan_consultant_buildings
            WHERE master_building_id = %s
              AND has_priority_badge
              AND (premium_expires_at IS NULL OR premium_expires_at > NOW())
              AND loan_consultant_id <> %s
        """, [mbid, lc_id])
        if cur.fetchone()["c"] >= LOAN_BUILDING_BADGE_SLOT_CAP:
            return jsonify({
                "ok": False,
                "message": f"이 단지는 대출상담사 단지뱃지가 이미 {LOAN_BUILDING_BADGE_SLOT_CAP}명 등록되어 있습니다.",
            }), 400
        try:
            cur.execute("""
                INSERT INTO loan_consultant_buildings
                    (loan_consultant_id, master_building_id, has_priority_badge,
                     premium_granted_at, premium_expires_at)
                VALUES (%s, %s, TRUE, NOW(), %s::timestamp)
            """, [lc_id, mbid, PARTNER_BADGE_FREE_EXPIRES_AT])
            conn.commit()
        except psycopg2_errors.UniqueViolation:
            conn.rollback()
            return jsonify({"ok": False, "message": "이미 등록된 단지입니다."}), 400
    finally:
        cur.close()
        conn.close()
    return jsonify({"ok": True})


