@app.route("/api/operator/buildings", methods=["POST"])
@require_operator
def operator_building_add():
    operator_id = session["operator_id"]
    data = request.get_json(force=True, silent=True) or {}
    try:
        mbid = int(data.get("master_building_id"))
    except (TypeError, ValueError):
        return jsonify({"ok": False, "message": "건물 ID가 올바르지 않습니다."}), 400
    note = data.get("note")
    if note is not None and not isinstance(note, str):
        return jsonify({"ok": False, "message": "메모 값이 올바르지 않습니다."}), 400
    note = (note or "").strip() or None
    conn = get_conn()
    cur = conn.cursor()
    try:
        # 같은 업체의 병렬 등록 요청이 담당단지 10개 한도를 우회하지 않게 한다.
        cur.execute("SELECT pg_advisory_xact_lock(%s, %s)", [911005, operator_id])
        cur.execute("SELECT 1 FROM master_buildings WHERE id = %s", [mbid])
        if not cur.fetchone():
            return jsonify({"ok": False, "message": "존재하지 않는 건물입니다."}), 404
        # 무료 담당단지 한도는 파트너 유형별로 동일하게 10개다.
        cur.execute("SELECT COUNT(*) c FROM operator_buildings WHERE operator_id = %s", [operator_id])
        if cur.fetchone()["c"] >= MAX_FREE_BUILDINGS:
            return jsonify({
                "ok": False,
                "message": f"무료 등록 가능 건물 수({MAX_FREE_BUILDINGS}개)를 초과했습니다. 추가 등록은 준비 중입니다.",
            }), 400
        try:
            cur.execute(
                "INSERT INTO operator_buildings (operator_id, master_building_id, note) VALUES (%s, %s, %s)",
                [operator_id, mbid, note],
            )
            conn.commit()
        except psycopg2_errors.UniqueViolation:
            conn.rollback()
            return jsonify({"ok": False, "message": "이미 등록된 단지입니다."}), 400
    finally:
        cur.close()
        conn.close()
    _mark_master_stats_invalidated_safely("operator_building_add")
    return jsonify({"ok": True})


@app.route("/api/operator/buildings/<int:mbid>/claim-premium", methods=["POST"])
@require_operator
def operator_building_claim_premium(mbid):
    """전속 단지를 무료 단지뱃지로 즉시 승격 — 단지당 1회 한정,
    같은 업종은 건물당 두 곳까지 허용한다."""
    operator_id = session["operator_id"]
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute("SELECT category FROM operators WHERE id=%s", [operator_id])
        me = cur.fetchone()
        if not me:
            return jsonify({"ok": False, "message": "운영업체 정보를 찾을 수 없습니다."}), 404
        my_category = me["category"]

        cur.execute(
            "SELECT premium_granted_at FROM operator_buildings WHERE operator_id=%s AND master_building_id=%s",
            [operator_id, mbid])
        row = cur.fetchone()
        if not row:
            return jsonify({"ok": False, "message": "본인의 담당 단지만 신청할 수 있습니다."}), 400
        if row["premium_granted_at"]:
            return jsonify({"ok": False, "message": "이미 이 단지는 단지뱃지 혜택을 사용했습니다."}), 400

        # 같은 단지·업종의 동시 신청도 두 자리 정원을 우회하지 않게 직렬화한다.
        cur.execute("SELECT pg_advisory_xact_lock(%s, hashtext(%s))",
                    [911008, f"{mbid}:{my_category}"])
        cur.execute("""
            SELECT COUNT(*) c
            FROM operator_buildings ob
            JOIN operators o ON o.id = ob.operator_id
            WHERE ob.master_building_id=%s AND ob.operator_id<>%s
              AND o.category = %s
              AND ob.has_priority_badge
              AND (ob.premium_expires_at IS NULL OR ob.premium_expires_at > NOW())
        """, [mbid, operator_id, my_category])
        if cur.fetchone()["c"] >= OPERATOR_BUILDING_BADGE_SLOT_CAP:
            return jsonify({
                "ok": False,
                "message": f"이 단지는 해당 업종의 단지뱃지가 이미 {OPERATOR_BUILDING_BADGE_SLOT_CAP}개 등록되어 있습니다.",
            }), 400

        cur.execute("""
            SELECT COUNT(*) c FROM operator_buildings
            WHERE operator_id=%s AND has_priority_badge
              AND (premium_expires_at IS NULL OR premium_expires_at > NOW())
        """, [operator_id])
        if cur.fetchone()["c"] >= OPERATOR_PREMIUM_BADGE_CAP:
            return jsonify({
                "ok": False,
                "message": f"단지뱃지는 최대 {OPERATOR_PREMIUM_BADGE_CAP}개까지 보유할 수 있습니다. "
                           f"{OPERATOR_PREMIUM_BADGE_CAP}개를 초과하는 대량 등록이 필요하시면 관리자에게 별도로 문의해주세요.",
            }), 400

        cur.execute("""
            UPDATE operator_buildings
            SET has_priority_badge = TRUE, premium_granted_at = NOW(),
                premium_expires_at = %s::timestamp
            WHERE operator_id=%s AND master_building_id=%s
        """, [PARTNER_BADGE_FREE_EXPIRES_AT, operator_id, mbid])
        # 단지뱃지 입점 성공 시 지역담당단지 목록에서 중복 제거
        cur.execute("DELETE FROM operator_region_buildings WHERE operator_id=%s AND master_building_id=%s",
                    [operator_id, mbid])
        conn.commit()
    finally:
        cur.close()
        conn.close()
    return jsonify({"ok": True})


@app.route("/api/operator/service-regions", methods=["GET"])
@require_operator
def operator_service_regions_mine():
    """현재 운영업체의 시군구 지역뱃지 등록 상태를 반환한다."""
    operator_id = session["operator_id"]
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute("""
            SELECT sgg_text, granted_at, expires_at
            FROM operator_service_regions
            WHERE operator_id=%s AND expires_at > NOW()
            ORDER BY granted_at DESC
        """, [operator_id])
        regions = [dict(row) for row in cur.fetchall()]
    finally:
        cur.close()
        conn.close()
    for region in regions:
        for key in ("granted_at", "expires_at"):
            if region.get(key):
                region[key] = region[key].isoformat()
    return jsonify({"ok": True, "regions": regions})


@app.route("/api/operator/service-regions", methods=["POST"])
@require_operator
def operator_service_region_claim():
    """시군구 단위 지역뱃지를 업종별 활성 정원 안에서 즉시 등록한다."""
    operator_id = session["operator_id"]
    data = request.get_json(force=True, silent=True) or {}
    sgg = (data.get("sgg_text") or "").strip()
    if not sgg:
        return jsonify({"ok": False, "message": "지역을 입력해주세요."}), 400
    conn = get_conn()
    cur = conn.cursor()
    try:
        # 서로 다른 지역을 동시에 등록해도 운영업체별 담당 지역 1개 제한을 지킨다.
        cur.execute("SELECT pg_advisory_xact_lock(%s, %s)", [911007, operator_id])
        cur.execute("""
            SELECT COUNT(*) c
            FROM operator_service_regions
            WHERE operator_id=%s AND expires_at > NOW()
        """, [operator_id])
        if cur.fetchone()["c"] >= OPERATOR_REGION_CAP:
            return jsonify({"ok": False, "message": "담당 지역은 1개만 등록할 수 있습니다. 지역을 바꾸려면 먼저 기존 지역을 삭제해주세요."}), 400
        cur.execute("SELECT category FROM operators WHERE id=%s", [operator_id])
        operator_row = cur.fetchone()
        if not operator_row:
            return jsonify({"ok": False, "message": "운영업체 정보를 찾을 수 없습니다."}), 404
        category = operator_row["category"]
        cur.execute("SELECT pg_advisory_xact_lock(%s, hashtext(%s))",
                    [911011, f"{sgg}\x1f{category}"])
        cur.execute("""
            SELECT COUNT(*) c
            FROM operator_service_regions osr
            JOIN operators o ON o.id = osr.operator_id
            WHERE osr.sgg_text = %s
              AND o.category = %s
              AND osr.expires_at > NOW()
              AND osr.operator_id <> %s
        """, [sgg, category, operator_id])
        if cur.fetchone()["c"] >= OPERATOR_REGION_CATEGORY_SLOT_CAP:
            return jsonify({
                "ok": False,
                "message": f"이 지역은 해당 업종의 지역뱃지 정원({OPERATOR_REGION_CATEGORY_SLOT_CAP}개)이 찼습니다. 다른 지역을 선택해주세요.",
            }), 400
        cur.execute("""
            INSERT INTO operator_service_regions (operator_id, sgg_text, expires_at)
            VALUES (%s, %s, %s::timestamp)
            ON CONFLICT (operator_id, sgg_text) DO UPDATE
            SET granted_at=NOW(), expires_at=EXCLUDED.expires_at
        """, [operator_id, sgg, PARTNER_BADGE_FREE_EXPIRES_AT])
        conn.commit()
    finally:
        cur.close()
        conn.close()
    return jsonify({"ok": True})


