# ── OTA 링크 신청 (위탁운영업체 → 관리자 승인) ────────────────────────────────

@app.route("/api/operator/booking-url-requests", methods=["GET"])
@require_operator
def operator_booking_url_requests_list():
    """내 모든 OTA 링크 신청 내역 — 건물별 최신 1건."""
    operator_id = session["operator_id"]
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute("""
            SELECT DISTINCT ON (bur.master_building_id)
                   bur.id, bur.master_building_id, mb.building_name,
                   bur.booking_url, bur.status,
                   bur.admin_note,
                   to_char(bur.submitted_at, 'YYYY-MM-DD HH24:MI') AS submitted_at,
                   to_char(bur.reviewed_at,  'YYYY-MM-DD HH24:MI') AS reviewed_at,
                   mb.booking_url_expires_at
            FROM booking_url_requests bur
            JOIN master_buildings mb ON mb.id = bur.master_building_id
            WHERE bur.operator_id = %s
            ORDER BY bur.master_building_id, bur.submitted_at DESC
        """, [operator_id])
        import datetime as _dt
        items = []
        for r in cur.fetchall():
            d = dict(r)
            exp = d.pop("booking_url_expires_at", None)
            if exp:
                d["expires_at"] = exp.isoformat()
                d["is_expired"] = exp < _dt.datetime.utcnow()
            else:
                d["expires_at"] = None
                d["is_expired"] = False
            items.append(d)
    finally:
        cur.close()
        conn.close()
    return jsonify({"ok": True, "items": items})


@app.route("/api/operator/booking-url-requests", methods=["POST"])
@require_operator
def operator_booking_url_request_submit():
    """담당 건물의 OTA 링크 신청 — 기존 pending 취소 후 새 신청 삽입."""
    operator_id = session["operator_id"]
    data = request.get_json(force=True, silent=True) or {}
    try:
        mbid = int(data.get("master_building_id"))
    except (TypeError, ValueError):
        return jsonify({"ok": False, "message": "건물 ID가 올바르지 않습니다."}), 400
    booking_url = (data.get("booking_url") or "").strip()
    if not booking_url.lower().startswith(("http://", "https://")):
        return jsonify({"ok": False, "message": "OTA 링크는 http(s)://로 시작해야 합니다."}), 400
    conn = get_conn()
    cur = conn.cursor()
    try:
        # 담당 건물인지 확인
        cur.execute("""
            SELECT 1 FROM operator_buildings
            WHERE operator_id = %s AND master_building_id = %s
        """, [operator_id, mbid])
        if not cur.fetchone():
            return jsonify({"ok": False, "message": "담당 단지가 아닙니다."}), 403
        # 재신청 횟수 확인 (총 2회: 최초 1회 + 재신청 1회)
        cur.execute("""
            SELECT COALESCE(MAX(renewal_count), -1) AS max_renewal
            FROM booking_url_requests
            WHERE operator_id = %s AND master_building_id = %s AND status = 'approved'
        """, [operator_id, mbid])
        row = cur.fetchone()
        max_renewal = row["max_renewal"] if row else -1
        if max_renewal >= 1:
            return jsonify({"ok": False,
                            "message": "무료 이용 기간이 모두 소진되었습니다. 더 이상 신청하실 수 없습니다."}), 400
        # 이번 신청의 renewal_count: 첫 신청=0, 재신청=1
        new_renewal_count = 0 if max_renewal < 0 else 1
        # 기존 pending 신청 취소 (동일 건물에 중복 pending 방지)
        cur.execute("""
            UPDATE booking_url_requests
            SET status = 'cancelled'
            WHERE operator_id = %s AND master_building_id = %s AND status = 'pending'
        """, [operator_id, mbid])
        cur.execute("""
            INSERT INTO booking_url_requests
                (operator_id, master_building_id, booking_url, status, submitted_at, renewal_count)
            VALUES (%s, %s, %s, 'pending', NOW(), %s)
        """, [operator_id, mbid, booking_url, new_renewal_count])
        conn.commit()
    finally:
        cur.close()
        conn.close()
    return jsonify({"ok": True, "message": "신청이 접수되었습니다. 관리자 검토 후 반영됩니다."})


# ── OTA 링크 신청 관리자 심사 ────────────────────────────────────────────────

@app.route("/api/admin/booking-url-requests/export.xlsx")
@require_admin
def admin_booking_url_requests_export():
    """OTA 신청 전체 이력 엑셀 다운로드 — 신청일 내림차순."""
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute("""
            SELECT bur.id, bur.status, bur.renewal_count,
                   bur.booking_url, bur.admin_note,
                   bur.submitted_at, bur.reviewed_at,
                   mb.building_name, mb.road_address,
                   mb.booking_url_expires_at,
                   o.company_name, o.category,
                   au.email AS reviewed_by_email
            FROM booking_url_requests bur
            JOIN master_buildings mb ON mb.id = bur.master_building_id
            JOIN operators o ON o.id = bur.operator_id
            LEFT JOIN admin_users au ON au.id = bur.reviewed_by
            ORDER BY bur.submitted_at DESC
        """)
        rows = cur.fetchall()
    finally:
        cur.close()
        conn.close()

    from openpyxl import Workbook
    from openpyxl.styles import Font, PatternFill, Alignment
    wb = Workbook()
    ws = wb.active
    ws.title = "OTA신청이력"

    headers = ["번호", "신청일", "건물명", "도로명주소", "업체명", "업종",
               "차수", "OTA 링크", "상태", "만료일", "처리일", "처리자", "거절사유"]
    ws.append(headers)
    # 헤더 스타일
    hdr_fill = PatternFill("solid", fgColor="F9F5EE")
    for cell in ws[1]:
        cell.font = Font(bold=True)
        cell.fill = hdr_fill
        cell.alignment = Alignment(horizontal="center")

    status_map = {"pending": "검토중", "approved": "승인됨", "rejected": "거절됨", "cancelled": "취소됨"}
    for i, r in enumerate(rows, 1):
        exp = r["booking_url_expires_at"]
        if exp and r["status"] == "approved":
            from datetime import datetime, timezone
            now = datetime.now(timezone.utc).replace(tzinfo=None)
            status_label = "운영중" if exp > now else "만료됨"
        else:
            status_label = status_map.get(r["status"], r["status"])
        ws.append([
            i,
            r["submitted_at"].strftime("%Y-%m-%d %H:%M") if r["submitted_at"] else "",
            r["building_name"],
            r["road_address"] or "",
            r["company_name"],
            r["category"] or "",
            "1차" if (r["renewal_count"] or 0) == 0 else "연장(2차)",
            r["booking_url"],
            status_label,
            r["booking_url_expires_at"].strftime("%Y-%m-%d") if r["booking_url_expires_at"] else "",
            r["reviewed_at"].strftime("%Y-%m-%d %H:%M") if r["reviewed_at"] else "",
            r["reviewed_by_email"] or "",
            r["admin_note"] or "",
        ])

    # 열 너비 자동 조정
    col_widths = [6, 16, 24, 30, 20, 12, 8, 50, 8, 12, 16, 20, 30]
    for col, w in zip(ws.columns, col_widths):
        ws.column_dimensions[col[0].column_letter].width = w
    # OTA 링크 열 셀 서식 (문자열로 강제)
    for row in ws.iter_rows(min_row=2):
        row[7].number_format = "@"

    buf = io.BytesIO()
    wb.save(buf)
    buf.seek(0)
    from datetime import date
    fname = f"OTA신청이력_{date.today().strftime('%Y%m%d')}.xlsx"
    return send_file(buf,
                     mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                     as_attachment=True,
                     download_name=fname)


@app.route("/api/admin/booking-url-requests/summary")
@require_admin
def admin_booking_url_requests_summary():
    """OTA 신청 현황 요약: 대기중/운영중/만료임박(7일) 카운트."""
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute("""
            SELECT
                COUNT(*) FILTER (WHERE bur.status = 'pending')                                          AS pending_count,
                COUNT(*) FILTER (WHERE bur.status = 'approved'
                                   AND mb.booking_url_expires_at > NOW())                               AS active_count,
                COUNT(*) FILTER (WHERE bur.status = 'approved'
                                   AND mb.booking_url_expires_at > NOW()
                                   AND mb.booking_url_expires_at <= NOW() + INTERVAL '7 days')          AS expiring_count
            FROM booking_url_requests bur
            JOIN master_buildings mb ON mb.id = bur.master_building_id
        """)
        row = cur.fetchone()
    finally:
        cur.close()
        conn.close()
    return jsonify({"ok": True,
                    "pending": row["pending_count"],
                    "active": row["active_count"],
                    "expiring": row["expiring_count"]})


@app.route("/api/admin/booking-url-requests")
@require_admin
def admin_booking_url_requests_list():
    """OTA 링크 신청 목록 — 기본 pending만, ?status=all 로 전체 조회."""
    status_filter = request.args.get("status", "pending").strip()
    conn = get_conn()
    cur = conn.cursor()
    try:
        if status_filter == "all":
            where = "1=1"
            params = []
        else:
            where = "bur.status = %s"
            params = [status_filter]
        cur.execute(f"""
            SELECT bur.id, bur.status, bur.renewal_count,
                   bur.booking_url, bur.admin_note,
                   to_char(bur.submitted_at, 'YYYY-MM-DD HH24:MI') AS submitted_at,
                   to_char(bur.reviewed_at,  'YYYY-MM-DD HH24:MI') AS reviewed_at,
                   mb.id AS building_id, mb.building_name, mb.road_address,
                   mb.booking_url_expires_at,
                   o.id AS operator_id, o.company_name, o.category
            FROM booking_url_requests bur
            JOIN master_buildings mb ON mb.id = bur.master_building_id
            JOIN operators o ON o.id = bur.operator_id
            WHERE {where}
            ORDER BY bur.submitted_at DESC
            LIMIT 200
        """, params)
        items = [dict(r) for r in cur.fetchall()]
    finally:
        cur.close()
        conn.close()
    return jsonify({"ok": True, "items": items})


@app.route("/api/admin/booking-url-requests/<int:req_id>/approve", methods=["POST"])
@require_admin
def admin_booking_url_request_approve(req_id):
    """OTA 링크 승인 — master_buildings 반영 + 3개월 만료일 설정."""
    admin_id = session.get("admin_user_id")
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute("""
            SELECT id, operator_id, master_building_id, booking_url, status
            FROM booking_url_requests WHERE id = %s FOR UPDATE
        """, [req_id])
        req = cur.fetchone()
        if not req:
            return jsonify({"ok": False, "message": "존재하지 않는 신청입니다."}), 404
        if req["status"] != "pending":
            return jsonify({"ok": False, "message": f"이미 처리된 신청입니다 (상태: {req['status']})."}), 400
        # master_buildings 반영 (booking_url_source='operator', 3개월 만료)
        cur.execute("""
            UPDATE master_buildings
            SET booking_url = %s,
                booking_url_source = 'operator',
                booking_url_updated_at = NOW(),
                booking_url_expires_at = NOW() + INTERVAL '3 months'
            WHERE id = %s
        """, [req["booking_url"], req["master_building_id"]])
        cur.execute("""
            UPDATE booking_url_requests
            SET status = 'approved', reviewed_at = NOW(), reviewed_by = %s,
                expires_at = NOW() + INTERVAL '3 months'
            WHERE id = %s
        """, [admin_id, req_id])
        conn.commit()
    finally:
        cur.close()
        conn.close()
    return jsonify({"ok": True})


