# ---- 건물마스터 CRUD (모두 require_admin) ----
# 정렬 허용 컬럼 화이트리스트 (SQL 인젝션 방지 — 목록에 없으면 id로 폴백)
# key → ORDER BY SQL expression (화이트리스트 겸 식 맵)
# 서브쿼리 식은 항상 mb 별칭을 사용해야 한다.
# key → ORDER BY SQL expression (화이트리스트 겸 식 맵)
# ※ 모든 식에 NULLS LAST를 적용하고, 숫자 컬럼은 NULLIF(..., 0)으로 0도 뒤로 밀어낸다.
#   → 정렬 방향(오름차/내림차) 무관하게 빈값·0이 항상 맨 끝에 위치한다.
ADMIN_BLD_SORT = {
    "id":             "mb.id",
    # 문자열: NULL/빈문자열을 NULL로 통일해 NULLS LAST 처리
    "building_name":  "NULLIF(mb.building_name, '')",
    "road_address":   "NULLIF(mb.road_address, '')",
    "lodging_type":   "NULLIF(mb.lodging_type, '')",
    "sgg_text":       "NULLIF(mb.sgg_text, '')",
    "umd_nm":         "NULLIF(mb.umd_nm, '')",
    "jibun":          "NULLIF(mb.jibun, '')",
    # 숫자: 0 → NULL로 치환해 NULLS LAST 처리
    "units":          "NULLIF(mb.units, 0)",
    # SELECT alias를 NULLIF 감싸면 동작 안 함 → 직접 서브쿼리로 작성
    "favorite_count": (
        "NULLIF((SELECT COUNT(*) FROM user_favorites uf"
        " WHERE uf.master_building_id = mb.id"
        "    OR (uf.master_building_id IS NULL"
        "        AND (uf.address = mb.road_address"
        "             OR REPLACE(mb.umd_nm || mb.jibun, ' ', '') = REPLACE(uf.address, ' ', ''))"
        "        AND (uf.building_name IS NULL OR uf.building_name = mb.building_name))), 0)"
    ),
    "store_count": (
        "NULLIF((SELECT COUNT(*) FROM building_stores bs"
        " WHERE bs.master_building_id = mb.id), 0)"
    ),
    # 입점부동산·신고율·영업신고호실은 주소 정규화 매칭 결과로 계산한다.
    # SQL만으로 현재 Python 정규화 규칙을 정확히 재현할 수 없어 목록 서버 정렬에는 제공하지 않는다.
}
# 생성/수정 가능한 컬럼 화이트리스트 (이 목록의 키만 반영)
ADMIN_BLD_EDITABLE = [
    "building_name", "road_address", "jibun_address", "sgg_text", "sgg_cd",
    "umd_nm", "jibun", "units", "biz_units", "lodging_type", "lodging_type_detail",
    "building_status", "completion_expected_date",
    "booking_url",
]
# biz_units는 과거 엑셀 스냅샷 참고값이다. 신고율·영업신고호실 계산에는 절대 사용하지 않는다.
ADMIN_BLD_INT_COLS = {"units", "biz_units"}


def _parse_int_or_none(v):
    if v is None or v == "":
        return None
    try:
        return int(v)
    except (ValueError, TypeError):
        return None


def _clean_bld_value(col, v):
    """편집 컬럼 값을 DB 저장형으로 정규화 (숫자 컬럼은 int/None, 그 외 문자열/None)."""
    if col in ADMIN_BLD_INT_COLS:
        return _parse_int_or_none(v)
    if v is None:
        return None
    s = str(v).strip()
    return s or None


def _building_ids_by_lodging_status(where_sql, params, status_filter):
    """현재 건물 목록과 같은 주소 정규화 규칙으로 영업상태별 건물 ID를 찾는다.

    lodging_registry.applied_building_id는 신규 등록 후보를 수동 적용할 때만
    채워진다. 일반 건물마스터 목록의 신고 매칭은 road_norm 우선, 해당 신고가
    전혀 없을 때만 jibun_norm을 보조로 쓰므로, 상태 필터도 그 규칙을 그대로
    따라야 목록의 영업사업장 표시와 결과가 일치한다.
    """
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(f"""
            SELECT mb.id, mb.road_address, mb.jibun_address
            FROM master_buildings mb
            WHERE {where_sql}
        """, params)
        buildings = [dict(row) for row in cur.fetchall()]
        if not buildings:
            return []

        road_keys_by_id = {}
        jibun_keys_by_id = {}
        road_keys, jibun_keys = set(), set()
        for building in buildings:
            building_id = building["id"]
            road_key = addr_norm.normalize_road_prefix(building.get("road_address"))
            # 관리자 목록의 영업신고 attach 로직과 동일: 지번주소가 없으면
            # road_address도 지번 형식일 수 있으므로 보조 키로 시도한다.
            jibun_key = addr_norm.normalize_jibun_prefix(
                building.get("jibun_address") or building.get("road_address")
            )
            road_keys_by_id[building_id] = road_key
            jibun_keys_by_id[building_id] = jibun_key
            if road_key:
                road_keys.add(road_key)
            if jibun_key:
                jibun_keys.add(jibun_key)

        cur.execute("""
            SELECT biz_status_name, road_norm, jibun_norm
            FROM lodging_registry
            WHERE road_norm = ANY(%s) OR jibun_norm = ANY(%s)
        """, [list(road_keys) or ["__none__"], list(jibun_keys) or ["__none__"]])
        road_statuses, jibun_statuses = {}, {}
        for row in cur.fetchall():
            if row["road_norm"]:
                road_statuses.setdefault(row["road_norm"], []).append(
                    row["biz_status_name"]
                )
            if row["jibun_norm"]:
                jibun_statuses.setdefault(row["jibun_norm"], []).append(
                    row["biz_status_name"]
                )

        matching_ids = []
        for building in buildings:
            building_id = building["id"]
            # 도로명 키에 매칭된 신고가 하나라도 있으면 도로명 결과만 사용한다.
            # 그렇지 않을 때만 지번 결과를 사용해야 목록의 사업장 수와 같아진다.
            statuses = road_statuses.get(road_keys_by_id[building_id], [])
            if not statuses:
                statuses = jibun_statuses.get(jibun_keys_by_id[building_id], [])
            has_active = ACTIVE_LODGING_STATUS in statuses
            if ((status_filter == "active" and has_active)
                    or (status_filter == "closed" and statuses and not has_active)):
                matching_ids.append(building_id)
        return matching_ids
    finally:
        cur.close()
        conn.close()


def _admin_bld_filters():
    """목록/엑셀 공용: q, sort, order, WHERE절, 파라미터를 계산."""
    q = (request.args.get("q") or "").strip()
    sort = (request.args.get("sort") or "id").strip()
    if sort not in ADMIN_BLD_SORT:
        sort = "id"
    order = "DESC" if (request.args.get("order") or "asc").strip().lower() == "desc" else "ASC"
    # 복합시설 자동 제외분은 건물마스터 목록/엑셀에도 표시하지 않는다 (DB에는 보존)
    where = "lodging_type IS DISTINCT FROM 'mixed_use_excluded'"
    params = []
    if q:
        where += " AND (building_name ILIKE %s OR road_address ILIKE %s)"
        params = [f"%{q}%", f"%{q}%"]
    # 명칭 미확정 건물만 필터 (관리자 주기 점검용)
    if (request.args.get("name_pending") or "").strip() == "1":
        where += " AND name_pending IS TRUE"
    # 용도(lodging_type) 필터 — 건물마스터 드롭다운
    lt_filter = (request.args.get("lodging_type_filter") or "").strip()
    if lt_filter == "미분류":
        # 준공전 제외: building_status가 허가/착공인 행은 별도 분류
        where += (
            " AND (lodging_type IS NULL OR lodging_type = '')"
            " AND building_status NOT IN ('허가','착공')"
        )
    elif lt_filter == "준공전":
        where += (
            " AND building_status IN ('허가','착공')"
            " AND (use_apr_day IS NULL OR use_apr_day = '')"
        )
    elif lt_filter in ("생활", "관광", "일반", "복합"):
        where += " AND lodging_type = %s"
        params.append(lt_filter)
    # 지역 검색 필터 — 시/도(LIKE 전두), 시/군/구(exact), 읍/면/동(exact)
    sido_tf = (request.args.get("sido_filter") or "").strip()
    if sido_tf:
        where += " AND sgg_text LIKE %s"
        params.append(f"{sido_tf} %")
    sgg_tf = (request.args.get("sgg_text_filter") or "").strip()
    if sgg_tf:
        where += " AND sgg_text = %s"
        params.append(sgg_tf)
    umd_tf = (request.args.get("umd_nm_filter") or "").strip()
    if umd_tf:
        where += " AND umd_nm = %s"
        params.append(umd_tf)
    # 매칭된 영업신고 사업장의 영업상태 필터. 목록과 동일한 주소 정규화
    # (도로명 우선·지번 보조)는 SQL만으로 정확히 재현하기 어려워 ID를 먼저 계산한다.
    biz_status_filter = (request.args.get("biz_status_filter") or "").strip()
    if biz_status_filter in ("active", "closed"):
        matched_ids = _building_ids_by_lodging_status(
            where, params, biz_status_filter
        )
        if matched_ids:
            where += " AND mb.id = ANY(%s)"
            params.append(matched_ids)
        else:
            where += " AND FALSE"
    return q, sort, order, where, params


@app.route("/api/admin/buildings")
@require_admin
def admin_buildings_list():
    q, sort, order, where_sql, params = _admin_bld_filters()
    try:
        page = max(int(request.args.get("page", 1)), 1)
    except (ValueError, TypeError):
        page = 1
    try:
        size = min(max(int(request.args.get("size", 50)), 1), 200)
    except (ValueError, TypeError):
        size = 50
    offset = (page - 1) * size
    conn = get_conn()
    cur = conn.cursor()
    cur.execute(f"SELECT COUNT(*) c FROM master_buildings mb WHERE {where_sql}", params)
    total = cur.fetchone()["c"]
    # sort/order는 화이트리스트 맵(ADMIN_BLD_SORT)으로만 정해지므로 f-string 삽입이 안전하다.
    sort_expr = ADMIN_BLD_SORT[sort]
    cur.execute(f"""
        SELECT mb.id, mb.building_name, mb.name_pending,
               mb.building_name_source, mb.building_name_candidate_count,
               mb.road_address, mb.jibun_address,
               mb.sgg_text, mb.sgg_cd, mb.umd_nm, mb.jibun, mb.units,
               mb.biz_units AS biz_units_snapshot_legacy,
               mb.lodging_type, mb.lodging_type_detail,
               (SELECT COUNT(*) FROM user_favorites uf
                WHERE uf.master_building_id = mb.id
                   OR (uf.master_building_id IS NULL
                       AND (uf.address = mb.road_address
                            OR REPLACE(mb.umd_nm || mb.jibun, ' ', '') = REPLACE(uf.address, ' ', ''))
                       AND (uf.building_name IS NULL OR uf.building_name = mb.building_name))
               ) AS favorite_count,
               (SELECT COUNT(*) FROM agent_buildings ab
                WHERE ab.master_building_id = mb.id
                  AND COALESCE(ab.has_priority_badge, FALSE)
                  AND (ab.premium_expires_at IS NULL OR ab.premium_expires_at > NOW())
               ) AS priority_badge_count,
               (SELECT to_char(MIN(ab.premium_expires_at), 'YYYY-MM-DD')
                FROM agent_buildings ab
                WHERE ab.master_building_id = mb.id
                  AND COALESCE(ab.has_priority_badge, FALSE)
                  AND (ab.premium_expires_at IS NULL OR ab.premium_expires_at > NOW())
                  AND ab.premium_expires_at IS NOT NULL
               ) AS premium_expires_at
        FROM master_buildings mb
        WHERE {where_sql}
        ORDER BY {sort_expr} {order} NULLS LAST, mb.id ASC
        LIMIT %s OFFSET %s
    """, params + [size, offset])
    items = [dict(r) for r in cur.fetchall()]
    cur.close()
    conn.close()

    # 단지부동산(이 건물 주소와 정확히 일치하는 broker_registry 원본) —
    # 현재 페이지(최대 200건) 한정으로 매칭. 도로명 결과가 있으면 그것만
    # 사용하고, 도로명 결과가 없을 때만 지번 결과를 보조로 사용한다.
    # 정규화 매칭이라 서버사이드 정렬은 지원하지 않는다.
    # 상가정보 API(storeListInPnu) 방식은 건당 평균 3초로 200건 시 ≈600초 —
    # gunicorn 30초 timeout 초과 확정이라 broker_registry 로컬 DB 배치 방식 유지.
    if items:
        road_key_map, jibun_key_map = {}, {}
        rkeys, jkeys = [], []
        for it in items:
            rk = addr_norm.normalize_road_prefix(it.get("road_address"))
            jk = addr_norm.normalize_jibun_prefix(it.get("jibun_address") or it.get("road_address"))
            if rk:
                road_key_map.setdefault(rk, []).append(it)
            if jk:
                jibun_key_map.setdefault(jk, []).append(it)
        rkeys, jkeys = list(road_key_map.keys()), list(jibun_key_map.keys())
        if rkeys or jkeys:
            conn2 = get_conn()
            cur2 = conn2.cursor()
            cur2.execute("""
                SELECT id, office_name, road_norm, jibun_norm
                FROM broker_registry
                WHERE road_norm = ANY(%s) OR jibun_norm = ANY(%s)
            """, (rkeys, jkeys))
            broker_road_groups, broker_jibun_groups = {}, {}
            for br in cur2.fetchall():
                if br["road_norm"]:
                    broker_road_groups.setdefault(br["road_norm"], []).append(dict(br))
                if br["jibun_norm"]:
                    broker_jibun_groups.setdefault(br["jibun_norm"], []).append(dict(br))
            cur2.close()
            conn2.close()
            for it in items:
                road_matches = broker_road_groups.get(
                    addr_norm.normalize_road_prefix(it.get("road_address")), []
                )
                matches = road_matches or broker_jibun_groups.get(
                    addr_norm.normalize_jibun_prefix(
                        it.get("jibun_address") or it.get("road_address")
                    ), []
                )
                it["broker_realty_count"] = len({row["id"] for row in matches})
                it["matched_broker_name"] = ", ".join(
                    row["office_name"] for row in matches if row.get("office_name")
                ) or None
        else:
            for it in items:
                it["broker_realty_count"] = 0
                it["matched_broker_name"] = None

    # ── 입점상가/입점부동산 — building_stores 캐시 배치 조회 ──────────────────
    if items:
        bld_ids = [it["id"] for it in items]
        conn_bs = get_conn()
        cur_bs = conn_bs.cursor()
        # 전체 상가 수
        cur_bs.execute(
            "SELECT master_building_id, COUNT(*) AS cnt FROM building_stores "
            "WHERE master_building_id = ANY(%s) GROUP BY master_building_id",
            (bld_ids,)
        )
        store_cnt_map = {row["master_building_id"]: row["cnt"] for row in cur_bs.fetchall()}
        # 부동산 업종 목록 (호번호 순 정렬)
        cur_bs.execute(
            "SELECT master_building_id, store_name, ho_no FROM building_stores "
            "WHERE master_building_id = ANY(%s) AND category = '부동산' "
            "ORDER BY master_building_id, ho_no NULLS LAST, store_name",
            (bld_ids,)
        )
        realty_map = {}
        for row in cur_bs.fetchall():
            realty_map.setdefault(row["master_building_id"], []).append(
                {"name": row["store_name"], "ho_no": row["ho_no"]}
            )
        cur_bs.close()
        conn_bs.close()
        for it in items:
            it["store_count"] = store_cnt_map.get(it["id"], 0)
            it["store_realty_list"] = realty_map.get(it["id"], [])
            legacy_realty_count = len(it["store_realty_list"])
            broker_realty_count = int(it.get("broker_realty_count") or 0)
            it["store_realty_count"] = broker_realty_count or legacy_realty_count
            it["store_realty_source"] = (
                "broker_registry" if broker_realty_count
                else "상권정보" if legacy_realty_count
                else None
            )

    # ── lodging_registry 영업신고 배치 매칭 ──────────────────────────────────
    # road_key_map / jibun_key_map은 위 broker 매칭 블록에서 이미 계산됨.
    if items and (rkeys or jkeys):
        conn3 = get_conn()
        cur3 = conn3.cursor()
        cur3.execute("""
            SELECT biz_name, permit_number, permit_date, biz_status_name,
                   room_count, hygiene_type, phone,
                   road_address  AS lr_road_address,
                   jibun_address AS lr_jibun_address,
                   source_updated_at,
                   road_norm, jibun_norm
            FROM lodging_registry
            WHERE road_norm = ANY(%s) OR jibun_norm = ANY(%s)
            ORDER BY source_updated_at DESC NULLS LAST
        """, (rkeys, jkeys))
        lr_road_grp, lr_jibun_grp = {}, {}
        for lr in cur3.fetchall():
            lr_d = dict(lr)
            if lr_d.get("road_norm"):
                lr_road_grp.setdefault(lr_d["road_norm"], []).append(lr_d)
            if lr_d.get("jibun_norm"):
                lr_jibun_grp.setdefault(lr_d["jibun_norm"], []).append(lr_d)
        cur3.close()
        conn3.close()
        # road_key_map: norm → [building dicts]  →  attach lodging list per building
        for rk_norm, bld_list in road_key_map.items():
            lr_list = lr_road_grp.get(rk_norm, [])
            for it in bld_list:
                it["_lr_list"] = lr_list
        for jk_norm, bld_list in jibun_key_map.items():
            lr_list = lr_jibun_grp.get(jk_norm, [])
            for it in bld_list:
                # 도로명 키는 있어도 해당 신고가 없을 수 있다. 이때 빈 목록을
                # 이미 붙였다는 이유로 지번 보조 매칭을 건너뛰면 상세 API와
                # 목록의 판정이 달라진다.
                if not it.get("_lr_list"):  # road 매칭 결과가 없는 경우만
                    it["_lr_list"] = lr_list
    for it in items:
        lr_list = it.pop("_lr_list", [])
        # 객실수 큰 순으로 정렬
        lr_list.sort(key=lambda x: (
            int(x.get("room_count") or 0),
            str(x.get("permit_date") or ""),
        ), reverse=True)
        cnt = len(lr_list)
        it["lodging_count"] = cnt
        active_lodgings = [
            lr for lr in lr_list
            if lr.get("biz_status_name") == ACTIVE_LODGING_STATUS
        ]
        it["building_name_auto"] = (
            it.get("building_name_source") == "lodging_report"
        )
        it["building_name_auto_representative"] = (
            it["building_name_auto"]
            and int(it.get("building_name_candidate_count") or 0) > 1
        )
        # 후보 수가 아직 저장되지 않은 기존 행도 목록에서 현재 상태를
        # 설명할 수 있도록, 매칭된 활성 사업장 기준으로 보정한다.
        if it["building_name_auto"] and not it.get("building_name_candidate_count"):
            it["building_name_candidate_count"] = len(active_lodgings)
        it["lodging_list"] = [
            {
                "permit_number":     lr.get("permit_number"),
                "room_count":        lr.get("room_count"),
                "biz_status_name":   lr.get("biz_status_name"),
                "permit_date":       lr.get("permit_date"),
                "phone":             lr.get("phone"),
                "road_address":      lr.get("lr_road_address") or lr.get("lr_jibun_address"),
                "source_updated_at": lr.get("source_updated_at"),
                "biz_name":          lr.get("biz_name"),
                "hygiene_type":      lr.get("hygiene_type"),
            }
            for lr in lr_list
        ]
        # 영업신고호실은 주소 매칭된 lodging_registry의 비폐업 객실수 합계만 사용한다.
        # legacy 스냅샷이 0/NULL이거나 다른 값이어도 화면·신고율 계산에 영향 주지 않는다.
        it["lodging_room_total"] = sum(
            (lr.get("room_count") or 0)
            for lr in lr_list
            if "폐업" not in (lr.get("biz_status_name") or "")
        )
        it["lodging_metric"] = (
            "report_rate" if uses_lodging_report_rate(it.get("lodging_type")) else "room_count"
        )

    # ── 합계(totals) 집계 — 현재 필터 기준 전체 결과 ────────────────────────────
    # 페이지네이션된 items가 아닌, 동일 WHERE절에 해당하는 전체 건물 기준으로 집계.
    # 신고율은 전체 영업신고호실 합 ÷ 전체 호실 합의 가중평균으로 모든 요약 화면과 통일한다.
    totals = None
    try:
        conn_t = get_conn()
        cur_t = conn_t.cursor()

        # 매칭 건물 전체의 id + 집계에 필요한 최소 컬럼 fetch
        cur_t.execute(f"""
            SELECT id, lodging_type, units, road_address, jibun_address
            FROM master_buildings mb WHERE {where_sql}
        """, params)
        all_blds_t = cur_t.fetchall()
        all_ids_t = [b["id"] for b in all_blds_t]

        total_units_t = sum(int(b["units"] or 0) for b in all_blds_t)
        report_rate_blds_t = [
            b for b in all_blds_t if uses_lodging_report_rate(b.get("lodging_type"))
        ]
        report_rate_units_t = sum(int(b["units"] or 0) for b in report_rate_blds_t)

        # 관심저장 합계 — 개별 행 표시와 동일한 correlated 서브쿼리(master_building_id OR 주소매칭)
        # master_building_id IS NULL인 주소기반 favorites를 누락하지 않기 위해 per-row 쿼리와 동일 로직 사용.
        cur_t.execute(f"""
            SELECT COALESCE(SUM(
                (SELECT COUNT(*) FROM user_favorites uf
                 WHERE uf.master_building_id = mb.id
                    OR (uf.master_building_id IS NULL
                        AND (uf.address = mb.road_address
                             OR REPLACE(mb.umd_nm || mb.jibun, ' ', '') = REPLACE(uf.address, ' ', ''))
                        AND (uf.building_name IS NULL OR uf.building_name = mb.building_name)))
            ), 0) AS s
            FROM master_buildings mb WHERE {where_sql}
        """, params)
        total_favorites_t = int(cur_t.fetchone()["s"])

        # 단지뱃지 합계 — 활성 has_priority_badge=TRUE 기준 (full-stats 동일)
        cur_t.execute("""
            SELECT COALESCE(SUM(a.cnt), 0) AS s
            FROM (SELECT master_building_id, COUNT(*) AS cnt
                  FROM agent_buildings
                  WHERE master_building_id = ANY(%s)
                    AND COALESCE(has_priority_badge, FALSE)
                    AND (premium_expires_at IS NULL OR premium_expires_at > NOW())
                  GROUP BY master_building_id) a
        """, [all_ids_t or [0]])
        total_badges_t = int(cur_t.fetchone()["s"])

        # 입점부동산 / 입점상가 합계 — building_stores 테이블 집계
        cur_t.execute("""
            SELECT COALESCE(SUM(cnt_all), 0) AS store_total,
                   COALESCE(SUM(cnt_realty), 0) AS store_realty
            FROM (SELECT master_building_id,
                         COUNT(*) AS cnt_all,
                         COUNT(*) FILTER (WHERE category = '부동산') AS cnt_realty
                  FROM building_stores WHERE master_building_id = ANY(%s)
                  GROUP BY master_building_id) s
        """, [all_ids_t or [0]])
        store_agg_t = cur_t.fetchone()
        total_store_count_t = int(store_agg_t["store_total"])
        total_store_realty_t = int(store_agg_t["store_realty"])
        cur_t.execute("""
            SELECT master_building_id, COUNT(*) FILTER (WHERE category = '부동산') AS cnt
            FROM building_stores
            WHERE master_building_id = ANY(%s)
            GROUP BY master_building_id
        """, [all_ids_t or [0]])
        legacy_realty_by_building_t = {
            row["master_building_id"]: int(row["cnt"]) for row in cur_t.fetchall()
        }

        # 영업사업장(lodging_registry) — 주소 정규화 후 매칭 (full-stats와 동일 로직)
        t_road_norms: list = []
        t_jibun_norms: list = []
        bld_rk_t: dict = {}
        bld_jk_t: dict = {}
        for b in all_blds_t:
            rk = addr_norm.normalize_road_prefix(b["road_address"])
            jk = addr_norm.normalize_jibun_prefix(b.get("jibun_address") or b["road_address"])
            bld_rk_t[b["id"]] = rk
            bld_jk_t[b["id"]] = jk
            if rk: t_road_norms.append(rk)
            if jk: t_jibun_norms.append(jk)

        # 목록의 입점부동산 합계도 브로커 표준데이터 우선·상권정보 보조
        # 정책을 그대로 사용한다. 같은 브로커가 도로명·지번 양쪽에 걸려도
        # 도로명 결과만 사용하므로 중복 집계하지 않는다.
        broker_road_map_t, broker_jibun_map_t = {}, {}
        if t_road_norms or t_jibun_norms:
            cur_t.execute("""
                SELECT id, road_norm, jibun_norm
                FROM broker_registry
                WHERE road_norm = ANY(%s) OR jibun_norm = ANY(%s)
            """, [
                list(set(t_road_norms)) or ["__none__"],
                list(set(t_jibun_norms)) or ["__none__"],
            ])
            for broker in cur_t.fetchall():
                if broker["road_norm"]:
                    broker_road_map_t.setdefault(broker["road_norm"], set()).add(broker["id"])
                if broker["jibun_norm"]:
                    broker_jibun_map_t.setdefault(broker["jibun_norm"], set()).add(broker["id"])
        total_store_realty_t = sum(
            len(
                broker_road_map_t.get(bld_rk_t[b["id"]], set())
                or broker_jibun_map_t.get(bld_jk_t[b["id"]], set())
            ) or legacy_realty_by_building_t.get(b["id"], 0)
            for b in all_blds_t
        )

        lr_road_map_t: dict = {}
        lr_jibun_map_t: dict = {}
        if t_road_norms or t_jibun_norms:
            cur_t.execute(
                "SELECT permit_number, room_count, biz_status_name, road_norm, jibun_norm "
                "FROM lodging_registry WHERE road_norm = ANY(%s) OR jibun_norm = ANY(%s)",
                [t_road_norms or ["__none__"], t_jibun_norms or ["__none__"]]
            )
            for r in cur_t.fetchall():
                rr = dict(r)
                if rr.get("road_norm"):
                    lr_road_map_t.setdefault(rr["road_norm"], {})[rr["permit_number"]] = rr
                if rr.get("jibun_norm"):
                    lr_jibun_map_t.setdefault(rr["jibun_norm"], {})[rr["permit_number"]] = rr
        cur_t.close()
        conn_t.close()

        # permit_number 중복 제거 후 전체 집계 (full-stats _row() 로직 동일)
        all_permits_t: dict = {}
        report_rate_permits_t: dict = {}
        for b in all_blds_t:
            rk = bld_rk_t[b["id"]]
            jk = bld_jk_t[b["id"]]
            bld_permits: dict = {}
            if rk and rk in lr_road_map_t:
                bld_permits.update(lr_road_map_t[rk])
            elif jk and jk in lr_jibun_map_t:
                bld_permits.update(lr_jibun_map_t[jk])
            all_permits_t.update(bld_permits)
            if uses_lodging_report_rate(b.get("lodging_type")):
                report_rate_permits_t.update(bld_permits)

        active_permits_t = [v for v in all_permits_t.values()
                            if "폐업" not in (v["biz_status_name"] or "")]
        report_rate_active_permits_t = [
            v for v in report_rate_permits_t.values()
            if "폐업" not in (v["biz_status_name"] or "")
        ]
        total_biz_units_t  = sum(int(v["room_count"] or 0) for v in report_rate_active_permits_t)
        total_lodging_t    = len(active_permits_t)
        # 가중평균: 일반숙박을 제외한 영업신고호실 합 ÷ 호실 합 × 100.
        weighted_report_rate_t = (
            round(total_biz_units_t / report_rate_units_t * 100, 1)
            if report_rate_units_t else None
        )

        totals = {
            "total_units":         total_units_t,
            "total_favorites":     total_favorites_t,
            "total_badges":        total_badges_t,
            "total_store_realty":  total_store_realty_t,
            "total_store_count":   total_store_count_t,
            "total_biz_units":     total_biz_units_t,
            "weighted_report_rate": weighted_report_rate_t,
            "total_lodging_count": total_lodging_t,
            "report_rate_units":   report_rate_units_t,
            "report_rate_buildings": len(report_rate_blds_t),
            "report_rate_excludes_general": True,
        }
    except Exception as _e:
        import traceback as _tb
        app.logger.error(f"admin buildings totals error: {_e}\n{_tb.format_exc()}")
        totals = None

    return jsonify({"total": total, "page": page, "size": size, "items": items, "totals": totals})


_bld_full_stats_cache: dict = {"ts": 0.0, "data": None}
_BLD_FULL_STATS_TTL = 300  # 5분 캐시

# 통계 화면은 여러 무거운 집계를 동시에 사용한다. 개별 캐시가 서로 다른 시점의
# 값을 내놓지 않도록, 데이터랩과 관리자용 원본은 이 캐시에서 한 번에 만든다.
# 기존 개별 캐시는 [LEGACY] 폴백 경로로 남겨 둔다.
_MASTER_STATS_CACHE_TTL = 30 * 60
_MASTER_STATS_REFRESH_LEAD = 10 * 60
_MASTER_STATS_BACKGROUND_POLL = 30
_MASTER_STATS_INVALIDATION_KEY = "master_stats_invalidation"
_MASTER_STATS_INVALIDATION_CHECK_TTL = 10
_MASTER_STATS_CACHE: dict = {
    "ts": 0.0,
    "data": {},
    "sections": {},
    "invalidation_token": None,
}
_MASTER_STATS_LOCK = threading.RLock()
_MASTER_STATS_REBUILDING = threading.local()
_MASTER_STATS_REVALIDATION_PENDING = False
_MASTER_STATS_NEEDS_REFRESH = threading.Event()
_MASTER_STATS_INVALIDATION_STATE = {"checked_at": 0.0, "token": None}


def _master_stats_is_rebuilding():
    return bool(getattr(_MASTER_STATS_REBUILDING, "active", False))


def _master_stats_invalidation_token():
    """별도 수집 프로세스가 남긴 무효화 신호를 짧게 폴링한다.

    Gunicorn 워커와 수집 워크플로는 메모리를 공유하지 않는다. app_meta의 갱신
    시각을 토큰으로 사용하면 새 스키마나 외부 비밀값 없이 다음 읽기에서 캐시를
    안전하게 다시 만들 수 있다.
    """
    now = time.time()
    state = _MASTER_STATS_INVALIDATION_STATE
    if now - state["checked_at"] < _MASTER_STATS_INVALIDATION_CHECK_TTL:
        return state["token"]
    conn = cur = None
    try:
        conn = get_conn()
        cur = conn.cursor()
        cur.execute(
            "SELECT value, updated_at::text AS updated_at FROM app_meta WHERE key=%s",
            (_MASTER_STATS_INVALIDATION_KEY,),
        )
        row = cur.fetchone()
        token = (
            f"{row.get('updated_at') or ''}:{row.get('value') or ''}"
            if row else None
        )
        state.update({"checked_at": now, "token": token})
        return token
    except Exception:
        # 무효화 표식을 읽지 못해도 마지막으로 알던 값은 유지하고, 기존 TTL이
        # 만료되면 재계산한다. 통계 화면을 표식 조회 장애로 멈추지 않는다.
        app.logger.warning("[master-stats] invalidation token read failed", exc_info=True)
        state["checked_at"] = now
        return state["token"]
    finally:
        if cur:
            cur.close()
        if conn:
            conn.close()


def _master_stats_cache_is_valid():
    if not _MASTER_STATS_CACHE["ts"]:
        return False
    if time.time() - _MASTER_STATS_CACHE["ts"] >= _MASTER_STATS_CACHE_TTL:
        return False
    return _MASTER_STATS_CACHE["invalidation_token"] == _master_stats_invalidation_token()


def _master_stats_cold_starting():
    """워커가 아직 정밀 마스터 통계를 보유하지 않은지 반환한다."""
    cache = _MASTER_STATS_CACHE
    return (
        not _master_stats_is_rebuilding()
        and not cache.get("ts")
        and not cache.get("data")
    )


def _master_stats_add_section(data, sections, name, builder):
    try:
        result = builder()
        required_keys = {
            "lodging_stats": ("rows", "total_building_cnt"),
            "consign_stats": ("items", "total"),
            "closure_stats": ("items",),
            "transaction_stats": ("volume_top", "price_change", "highest_price", "ranking"),
            "collection_stats": ("lodging", "brhub"),
        }
        if name == "region_match":
            if not isinstance(result, tuple) or len(result) != 6:
                raise RuntimeError("주소 매칭 원본 형식이 올바르지 않습니다.")
        elif (
            not isinstance(result, dict)
            or not all(key in result for key in required_keys.get(name, ()))
            or (result.get("ok") is False)
        ):
            raise RuntimeError("통계 원본 응답 형식이 올바르지 않습니다.")
        data[name] = result
        sections[name] = {"status": "ok", "error": None}
    except BackgroundConnectionUnavailable as exc:
        # 지도 등 사용자 요청용 연결을 확보하지 못한 상태다. 실패 결과로 캐시를
        # 덮지 않고, 기존 통계를 유지한 채 다음 백그라운드 주기에 다시 시도한다.
        app.logger.info("[master-stats] %s rebuild deferred: %s", name, exc)
        sections[name] = {"status": "deferred", "error": str(exc)[:240]}
    except Exception as exc:
        # 한 섹션 실패가 나머지 통계를 버리게 하지 않는다. 호출 API는 이 상태를
        # 보고 각각의 [LEGACY] 로직으로 폴백한다.
        app.logger.exception("[master-stats] %s rebuild failed", name)
        sections[name] = {"status": "error", "error": str(exc)[:240]}


def _master_stats_build_section(name, builder):
    """별도 작업 스레드에서 섹션 하나를 계산하고 결과를 호출 스레드에 돌려준다."""
    data = {}
    sections = {}
    previous_rebuilding = _master_stats_is_rebuilding()
    try:
        # Flask 앱 컨텍스트와 재빌드 플래그는 작업 스레드에 자동 전파되지 않는다.
        # 둘 다 여기서 준비해야 내부 통계 API가 마스터 캐시를 재귀 호출하지 않는다.
        with app.app_context():
            _MASTER_STATS_REBUILDING.active = True
            with background_connection_priority():
                _master_stats_add_section(data, sections, name, builder)
    except Exception as exc:
        app.logger.exception("[master-stats] %s worker failed", name)
        sections[name] = {"status": "error", "error": str(exc)[:240]}
    finally:
        _MASTER_STATS_REBUILDING.active = previous_rebuilding
    return name, data.get(name), sections[name]


def _master_stats_add_parallel_sections(data, sections, specs):
    """독립적인 통계 섹션을 함께 계산하되 결과 반영은 호출 스레드에서 직렬화한다."""
    # 통계 작업은 DB 풀에 예약된 백그라운드 예산 안에서만 동시에 시작한다.
    # 예산이 0인 작은 풀에서는 한 작업이 즉시 deferred가 되어 사용자 요청을
    # 기다리게 하지 않는다.
    worker_limit = max(1, min(len(specs), background_connection_limit() or 1))
    with ThreadPoolExecutor(
        max_workers=worker_limit,
        thread_name_prefix="master-stats",
    ) as executor:
        futures = [
            executor.submit(_master_stats_build_section, name, builder)
            for name, builder in specs
        ]
        for future in futures:
            name, result, section = future.result()
            sections[name] = section
            if result is not None:
                data[name] = result


def _rebuild_master_stats(*, force=False):
    """통계 원본을 단계별 병렬 재계산하고 섹션별 성공 여부를 남긴다."""
    with _MASTER_STATS_LOCK:
        if not force and _master_stats_cache_is_valid():
            return _MASTER_STATS_CACHE

        previous_data = dict(_MASTER_STATS_CACHE.get("data") or {})
        # 무효화 뒤 마스터의 특정 섹션만 실패한 경우에도 [LEGACY] 폴백이
        # 무효화 이전의 개별 캐시를 내놓지 않도록 함께 비운다.
        global _bld_full_stats_cache
        _bld_full_stats_cache = {"ts": 0.0, "data": None}
        _matched_lodging_region_cache.clear()
        if hasattr(get_ranking, "_cache"):
            delattr(get_ranking, "_cache")

        _MASTER_STATS_REBUILDING.active = True
        data = {}
        sections = {}
        try:
            # 1단계: 서로의 원본에 의존하지 않는 무거운 집계를 동시에 실행한다.
            _master_stats_add_parallel_sections(
                data,
                sections,
                (
                    ("lodging_stats", lambda: _lodging_full_stats_payload().get_json() or {}),
                    ("region_match", _matched_lodging_by_region),
                    ("transaction_stats", _transaction_master_stats_payload),
                    ("collection_stats", _collection_stats_payload),
                ),
            )
            # 2단계: 주소 매칭 결과를 재사용하는 섹션을 병렬로 계산한다.
            _master_stats_add_parallel_sections(
                data,
                sections,
                (
                    ("consign_stats", _consign_by_sido_payload),
                    ("closure_stats", lambda: _closure_rate_payload(data.get("region_match"))),
                ),
            )
        finally:
            _MASTER_STATS_REBUILDING.active = False

        if any(section.get("status") == "deferred" for section in sections.values()):
            _MASTER_STATS_NEEDS_REFRESH.set()
            app.logger.info(
                "[master-stats] DB capacity reserved for user requests; refresh deferred"
            )
            return _MASTER_STATS_CACHE

        # 백그라운드 재검증 중 일부 섹션만 실패해도 직전 성공값을 stale 값으로
        # 유지한다. sections의 error 상태는 관리자 화면과 다음 재시도를 위해
        # 보존하고, 공개 API는 해당 섹션의 stale 데이터를 즉시 제공한다.
        for name, section in sections.items():
            if section.get("status") == "error" and name in previous_data:
                data[name] = previous_data[name]

        _MASTER_STATS_CACHE.update({
            "ts": time.time(),
            "data": data,
            "sections": sections,
            "invalidation_token": _master_stats_invalidation_token(),
        })
        return _MASTER_STATS_CACHE


def _master_stats_schedule_revalidation():
    """이전 통계를 유지한 채 중복 없는 백그라운드 재계산을 예약한다."""
    global _MASTER_STATS_REVALIDATION_PENDING
    with _MASTER_STATS_LOCK:
        if _MASTER_STATS_REVALIDATION_PENDING:
            return False
        _MASTER_STATS_REVALIDATION_PENDING = True
        _MASTER_STATS_NEEDS_REFRESH.clear()

    def revalidate():
        global _MASTER_STATS_REVALIDATION_PENDING
        try:
            with app.app_context():
                # 섹션 계산뿐 아니라 캐시 발행 시 무효화 토큰을 읽는 DB 작업도
                # 지도 등 사용자 요청용 마지막 연결을 빌리지 않게 한다.
                with background_connection_priority():
                    _rebuild_master_stats(force=True)
            app.logger.info("[master-stats] stale cache revalidated")
        except Exception:
            # _rebuild_master_stats는 섹션별 실패를 자체 기록하지만, 스레드
            # 바깥의 예외도 다음 폴링에서 재시도할 수 있도록 pending을 해제한다.
            app.logger.exception("[master-stats] stale cache revalidation failed")
        finally:
            with _MASTER_STATS_LOCK:
                _MASTER_STATS_REVALIDATION_PENDING = False

    try:
        threading.Thread(
            target=revalidate,
            daemon=True,
            name="master-stats-revalidation",
        ).start()
    except Exception:
        with _MASTER_STATS_LOCK:
            _MASTER_STATS_REVALIDATION_PENDING = False
        app.logger.exception("[master-stats] stale cache revalidation thread start failed")
        return False
    return True


def _master_stats_section(name):
    """통계 섹션을 반환하고, 빈 캐시는 비차단 워밍업으로 넘긴다."""
    if _master_stats_is_rebuilding():
        return None
    cache = _MASTER_STATS_CACHE
    section_data = cache.get("data", {}).get(name)
    if section_data is None:
        # 배포 직후 어떤 공개 통계 API가 먼저 와도 요청 워커가 전체 마스터
        # 집계나 그 전역 락을 기다리지 않는다. 단일 비동기 재검증만 예약하고
        # 라우트별 경량/준비 상태 응답으로 넘긴다.
        _MASTER_STATS_NEEDS_REFRESH.set()
        _master_stats_schedule_revalidation()
        return None
    if _master_stats_cache_is_valid():
        if cache["sections"].get(name, {}).get("status") == "ok":
            return section_data
        if section_data is not None:
            _MASTER_STATS_NEEDS_REFRESH.set()
            return section_data
        return None
    if section_data is not None:
        # 만료된 데이터는 바로 돌려주고 다음 백그라운드 폴링에 재계산만 맡긴다.
        _MASTER_STATS_NEEDS_REFRESH.set()
        return section_data
    return None


def _master_stats_background_loop():
    """부팅 직후와 캐시 만료 전 통계 원본을 미리 갱신한다.

    통계 집계는 요청 스레드에서 선행하되, 실패가 앱 기동이나 일반 요청을
    방해하지 않도록 daemon 스레드에서 best effort로 실행한다.
    """
    first_run = True
    while True:
        try:
            # app_meta 무효화 표식 조회도 공유 풀을 사용한다. 이 루프는 사용자
            # 요청과 경쟁하는 백그라운드 작업이므로 마지막 연결은 항상 남긴다.
            with background_connection_priority():
                cache_ts = _MASTER_STATS_CACHE["ts"]
                now = time.time()
                refresh_due = (
                    first_run
                    or not cache_ts
                    or now - cache_ts >= _MASTER_STATS_CACHE_TTL - _MASTER_STATS_REFRESH_LEAD
                )
                invalidated = bool(cache_ts) and not _master_stats_cache_is_valid()
                refresh_requested = _MASTER_STATS_NEEDS_REFRESH.is_set()
                if refresh_due or invalidated or refresh_requested:
                    if _master_stats_schedule_revalidation():
                        reason = "requested" if refresh_requested else "scheduled"
                        app.logger.info("[master-stats] background refresh %s", reason)
            first_run = False
        except Exception:
            app.logger.exception("[master-stats] background refresh failed")
            first_run = False
        time.sleep(_MASTER_STATS_BACKGROUND_POLL)


def _master_stats_warm_then_loop():
    """워커 기동 뒤 정밀 통계를 채우고 이후 주기 갱신을 계속한다."""
    try:
        with app.app_context():
            # 워밍업도 지도·검색 요청보다 낮은 우선순위의 DB 예산 안에서만 돈다.
            # fork 훅의 호출 스레드를 막지 않도록 이 함수는 daemon에서 실행된다.
            with background_connection_priority():
                _rebuild_master_stats(force=True)
        app.logger.info("[master-stats] worker cache warmup completed")
    except Exception:
        # 콜드스타트 API는 COUNT 요약을 반환하므로 워밍업 장애가 워커 기동이나
        # 사용자 요청을 막지 않는다. 주기 루프가 다음 간격에 재시도한다.
        app.logger.exception("[master-stats] worker cache warmup failed")
    finally:
        _master_stats_background_loop()


def start_master_stats_worker():
    """Gunicorn 워커별 통계 워밍업·갱신 서비스를 비차단으로 시작한다."""
    worker_thread = threading.Thread(
        target=_master_stats_warm_then_loop,
        daemon=True,
        name="master-stats-worker",
    )
    worker_thread.start()
    return worker_thread


GENERAL_LODGING_SUB_TYPES = ("일반호텔", "여관업", "여인숙업", "숙박업(생활)")


def _capped_active_report_rooms_by_building(buildings, road_matches, jibun_matches):
    """신고 객실을 한 대표 건물에만 귀속해, 건물 호실수를 넘지 않게 집계한다.

    한 영업신고 주소가 여러 건물마스터에 매칭될 수 있다. 이 경우 같은 신고 객실을
    모든 후보 건물에 더하면 지역별 신고율이 100%를 넘을 수 있으므로, 호실 수가
    가장 큰 후보(동률이면 낮은 id)를 대표로 택한다. 대표 건물 안에서도 여러
    신고의 객실 합계는 마스터 호실 수까지만 신고율 분자로 인정한다.
    """
    candidates_by_permit = {}
    building_by_id = {}
    for building in buildings:
        building_by_id[building["id"]] = building
        road_key = addr_norm.normalize_road_prefix(building["road_address"])
        jibun_key = addr_norm.normalize_jibun_prefix(
            building["jibun_address"] or building["road_address"]
        )
        matches = road_matches.get(road_key) if road_key else None
        if not matches:
            matches = jibun_matches.get(jibun_key) if jibun_key else None
        if not matches:
            continue
        for permit, lodging in matches.items():
            if "폐업" in (lodging["biz_status_name"] or ""):
                continue
            entry = candidates_by_permit.setdefault(permit, {"lodging": lodging, "buildings": []})
            entry["buildings"].append(building)

    raw_rooms_by_building = {}
    for entry in candidates_by_permit.values():
        candidates = entry["buildings"]
        representative = max(
            candidates,
            key=lambda building: (int(building["units"] or 0), -int(building["id"])),
        )
        building_id = representative["id"]
        raw_rooms_by_building[building_id] = (
            raw_rooms_by_building.get(building_id, 0)
            + int(entry["lodging"]["room_count"] or 0)
        )

    return {
        building_id: min(room_count, max(0, int(building_by_id[building_id]["units"] or 0)))
        for building_id, room_count in raw_rooms_by_building.items()
    }


def _lodging_count_summary_payload():
    """콜드스타트에 공개할 가벼운 용도별 건물 요약을 만든다.

    정밀 통계는 주소 정규화와 영업신고·상가·매물 데이터를 모두 결합한다. 캐시가
    비어 있는 첫 요청에는 그 작업 대신 건물마스터의 분류별 COUNT/SUM 한 번만
    수행해, 공개 API의 행 구조를 유지하면서 워커를 빠르게 반환시킨다.
    """
    conn = cur = None
    try:
        conn = get_conn()
        cur = conn.cursor()
        cur.execute("""
            WITH classified AS (
                SELECT
                    CASE
                        WHEN building_status IN ('허가', '착공')
                             AND use_apr_day IS NULL THEN '준공전'
                        WHEN lodging_type IN ('생활', '관광', '일반') THEN lodging_type
                        WHEN lodging_type = '복합' OR lodging_type LIKE '%%·%%' THEN '복합'
                        WHEN COALESCE(lodging_type, '') = '' THEN '미분류'
                        ELSE NULL
                    END AS map_type,
                    COALESCE(units, 0) AS units
                FROM master_buildings
                WHERE lodging_type IS DISTINCT FROM 'mixed_use_excluded'
            )
            SELECT
                map_type,
                COUNT(*) AS building_count,
                COALESCE(SUM(units), 0) AS units
            FROM classified
            GROUP BY map_type
        """)
        count_rows = cur.fetchall()
    except Exception:
        # DB 연결 자체가 지연·장애여도 정밀 레거시 쿼리로 확대하지 않는다.
        # 공개 API는 명시적인 준비 상태로 응답하고 다음 백그라운드 주기에 재시도한다.
        app.logger.warning("[master-stats] cold-start COUNT summary failed", exc_info=True)
        return {
            "ok": False,
            "status": "warming",
            "rows": [],
        }
    finally:
        if cur:
            cur.close()
        if conn:
            conn.close()

    counts = {}
    total_building_cnt = total_units = 0
    for raw in count_rows:
        label = raw.get("map_type") or "기타"
        building_count = int(raw.get("building_count") or 0)
        units = int(raw.get("units") or 0)
        counts[label] = {
            "building_count": building_count,
            "units": units,
        }
        total_building_cnt += building_count
        total_units += units

    def summary_row(label):
        values = counts.get(label, {})
        row = {
            "type": label,
            "building_count": values.get("building_count", 0),
            "units": values.get("units", 0),
            "favorites": 0,
            "listing_requests": 0,
            "broker_badge": 0,
            "store_realty": 0,
            "store_total": 0,
            "report_rate": None,
            "permit_count": 0,
            "room_count": 0,
            "closed_rate": None,
            "lodging_metric": (
                "businesses_per_building"
                if label == REPORT_RATE_EXCLUDED_LODGING_TYPE
                else "report_rate"
            ),
            "report_rate_numerator": 0,
            "report_rate_denominator": 0,
            "report_rate_basis": (
                "businesses_per_building"
                if label == REPORT_RATE_EXCLUDED_LODGING_TYPE
                else "reported_rooms_per_units"
            ),
            "report_rate_room_count": 0,
            "report_rate_units": 0,
            "report_rate_building_count": 0,
            "report_rate_excludes_general": False,
        }
        if label == REPORT_RATE_EXCLUDED_LODGING_TYPE:
            row["sub_rows"] = [
                {
                    "type": hygiene_type,
                    "building_count": 0,
                    "permit_count": 0,
                    "room_count": 0,
                    "report_rate": None,
                }
                for hygiene_type in GENERAL_LODGING_SUB_TYPES
            ]
        return row

    rows = [
        {
            **summary_row("전체"),
            "building_count": total_building_cnt,
            "units": total_units,
            "lodging_metric": "type_weighted",
            "report_rate_basis": "type_weighted",
        },
        *[
            summary_row(label)
            for label in ("생활", "관광", REPORT_RATE_EXCLUDED_LODGING_TYPE, "복합", "준공전", "미분류")
        ],
    ]
    return {
        "ok": True,
        "status": "warming",
        "rows": rows,
        "total_building_cnt": total_building_cnt,
        "building_count_by_type": {
            label: values["building_count"]
            for label, values in counts.items()
            if label != "기타"
        },
    }


def _lodging_full_stats_payload():
    """건물마스터 용도별 세부 통계표 — 항상 전체 데이터 기준 (필터 무관, 5분 캐시)."""
    global _bld_full_stats_cache
    master_payload = _master_stats_section("lodging_stats")
    if master_payload is not None:
        # total_building_cnt는 지도와 관리자 통계가 공유하는 내부 기준값이다.
        # 기존 관리자/공개 응답 구조는 유지하기 위해 외부 응답에서는 숨긴다.
        response_payload = dict(master_payload)
        response_payload.pop("total_building_cnt", None)
        response_payload.pop("building_count_by_type", None)
        return jsonify(response_payload)

    # [LEGACY] 마스터 캐시를 만들 수 없을 때도 기존 상세 집계를 그대로 제공한다.
    now = time.time()
    if (
        not _master_stats_is_rebuilding()
        and _bld_full_stats_cache["data"]
        and now - _bld_full_stats_cache["ts"] < _BLD_FULL_STATS_TTL
    ):
        response_payload = dict(_bld_full_stats_cache["data"])
        response_payload.pop("total_building_cnt", None)
        response_payload.pop("building_count_by_type", None)
        return jsonify(response_payload)

    if (
        not _master_stats_is_rebuilding()
        and not _MASTER_STATS_CACHE.get("data", {}).get("lodging_stats")
    ):
        # 정밀 마스터 통계가 아직 없는 콜드스타트에는 전체 건물을 모두 읽고
        # 주소·신고·상가를 조합하는 레거시 집계를 실행하지 않는다. 이 요약은
        # 지도와 같은 건물 분류 기준만 사용하며, 상세 값은 백그라운드 워밍업
        # 완료 뒤 다음 요청에서 자동으로 교체된다.
        summary = _lodging_count_summary_payload()
        _MASTER_STATS_NEEDS_REFRESH.set()
        return jsonify(summary)

    conn = get_conn()
    cur = conn.cursor()

    # 1. 전체 건물
    cur.execute("""
        SELECT COUNT(*) AS total_building_cnt
        FROM master_buildings
        WHERE lodging_type IS DISTINCT FROM 'mixed_use_excluded'
    """)
    total_building_cnt = int(cur.fetchone()["total_building_cnt"])
    cur.execute("""
        SELECT id, lodging_type, building_status, use_apr_day,
               units, road_address, jibun_address
        FROM master_buildings WHERE lodging_type IS DISTINCT FROM 'mixed_use_excluded'
    """)
    all_blds = cur.fetchall()
    all_ids  = [b["id"] for b in all_blds]

    # 2. 관심저장 수 per building
    cur.execute(
        "SELECT master_building_id, COUNT(*) AS cnt FROM user_favorites "
        "WHERE master_building_id = ANY(%s) GROUP BY master_building_id", [all_ids]
    )
    fav_map = {r["master_building_id"]: int(r["cnt"]) for r in cur.fetchall()}

    # 3. 매물내놓기 수 per building (철회됨 제외)
    cur.execute(
        "SELECT master_building_id, COUNT(*) AS cnt FROM listing_requests "
        "WHERE master_building_id = ANY(%s) AND COALESCE(status, '') NOT IN ('withdrawn', '철회됨') "
        "GROUP BY master_building_id", [all_ids]
    )
    lr_req_map = {r["master_building_id"]: int(r["cnt"]) for r in cur.fetchall()}

    # 4. 입점상가 전체 + 부동산 업소 수
    cur.execute(
        "SELECT master_building_id, COUNT(*) AS total, "
        "COUNT(*) FILTER (WHERE category = '부동산') AS realty "
        "FROM building_stores WHERE master_building_id = ANY(%s) "
        "GROUP BY master_building_id", [all_ids]
    )
    store_map = {r["master_building_id"]: {"total": int(r["total"]), "realty": int(r["realty"])} for r in cur.fetchall()}

    # 5. 주소 정규화 (전체 1회)
    bld_rk = {}; bld_jk = {}
    all_road_norms = []; all_jibun_norms = []
    for b in all_blds:
        rk = addr_norm.normalize_road_prefix(b["road_address"])
        jk = addr_norm.normalize_jibun_prefix(b.get("jibun_address") or b["road_address"])
        bld_rk[b["id"]] = rk
        bld_jk[b["id"]] = jk
        if rk: all_road_norms.append(rk)
        if jk: all_jibun_norms.append(jk)

    # 6. 단지뱃지 — agent_buildings 실승인 건수 (has_priority_badge=TRUE, 미만료)
    #    기존 broker_registry 주소매칭 방식은 "중개업소가 같은 주소에 있는 건물 수"였으나
    #    실제 단지뱃지 승인 건수와 무관했으므로 교체.
    cur.execute("""
        SELECT ab.master_building_id, COUNT(*) AS cnt
        FROM agent_buildings ab
        WHERE ab.master_building_id = ANY(%s)
          AND COALESCE(ab.has_priority_badge, FALSE)
          AND (ab.premium_expires_at IS NULL OR ab.premium_expires_at > NOW())
        GROUP BY ab.master_building_id
    """, [all_ids])
    badge_map = {r["master_building_id"]: int(r["cnt"]) for r in cur.fetchall()}

    # 7. 영업신고 (lodging_registry 배치)
    lr_road_map: dict = {}   # road_norm → {permit_number → row}
    lr_jibun_map: dict = {}
    if all_road_norms or all_jibun_norms:
        cur.execute(
            "SELECT permit_number, room_count, biz_status_name, hygiene_type, road_norm, jibun_norm "
            "FROM lodging_registry WHERE road_norm = ANY(%s) OR jibun_norm = ANY(%s)",
            [all_road_norms or ["__none__"], all_jibun_norms or ["__none__"]]
        )
        for r in cur.fetchall():
            rr = dict(r)
            if rr.get("road_norm"):
                lr_road_map.setdefault(rr["road_norm"], {})[rr["permit_number"]] = rr
            if rr.get("jibun_norm"):
                lr_jibun_map.setdefault(rr["jibun_norm"], {})[rr["permit_number"]] = rr
    cur.close(); conn.close()

    # 그룹화
    TYPES = ["생활", "관광", "일반", "복합", "준공전", "미분류"]
    by_type: dict = {t: [] for t in TYPES}
    all_list: list = []
    building_count_by_type: dict = {}

    def _map_lodging_type(building: dict) -> str:
        """지도와 건물마스터 통계표가 공유하는 건물 분류 기준."""
        if (
            building.get("building_status") in ("허가", "착공")
            and not building.get("use_apr_day")
        ):
            return "준공전"
        if building.get("lodging_type") in ("생활", "관광", "일반"):
            return building["lodging_type"]
        if (
            building.get("lodging_type") == "복합"
            or "·" in (building.get("lodging_type") or "")
        ):
            return "복합"
        if not building.get("lodging_type"):
            return "미분류"
        return "미분류"

    for b in all_blds:
        all_list.append(b)
        map_type = _map_lodging_type(b)
        if map_type not in by_type:
            map_type = "미분류"
        by_type[map_type].append(b)
        building_count_by_type[map_type] = building_count_by_type.get(map_type, 0) + 1

    def _permits_for(blds: list) -> dict:
        permits: dict = {}
        for b in blds:
            rk = bld_rk[b["id"]]; jk = bld_jk[b["id"]]
            if rk and rk in lr_road_map:
                permits.update(lr_road_map[rk])
            elif jk and jk in lr_jibun_map:
                permits.update(lr_jibun_map[jk])
        return permits

    report_rate_blds = [
        building for building in all_blds
        if uses_lodging_report_rate(building.get("lodging_type"))
    ]
    capped_report_rooms_by_building = _capped_active_report_rooms_by_building(
        report_rate_blds, lr_road_map, lr_jibun_map
    )

    def _row(blds: list, type_label: str) -> dict:
        if not blds:
            is_general = type_label == REPORT_RATE_EXCLUDED_LODGING_TYPE
            empty_row = {
                "type": type_label, "building_count": 0, "units": 0,
                "favorites": 0, "listing_requests": 0, "broker_badge": 0,
                "store_realty": 0, "store_total": 0,
                "report_rate": None, "permit_count": 0, "room_count": 0, "closed_rate": None,
                "lodging_metric": "businesses_per_building" if is_general else "report_rate",
                "report_rate_numerator": 0, "report_rate_denominator": 0,
                "report_rate_basis": "businesses_per_building" if is_general else "reported_rooms_per_units",
                "report_rate_room_count": 0, "report_rate_units": 0, "report_rate_building_count": 0,
                "report_rate_excludes_general": False,
            }
            if is_general:
                empty_row["sub_rows"] = [
                    {
                        "type": hygiene_type, "building_count": 0,
                        "permit_count": 0, "room_count": 0, "report_rate": None,
                    }
                    for hygiene_type in GENERAL_LODGING_SUB_TYPES
                ]
            return empty_row
        tu = sum(int(b["units"] or 0) for b in blds)
        broker_c = sum(badge_map.get(b["id"], 0) for b in blds)
        permits = _permits_for(blds)
        # 폐업 제외: 영업신고업체·영업신고호실은 현재 운영 중인 사업장만 집계한다.
        total_pc = len(permits)
        cc       = sum(1 for v in permits.values() if "폐업" in (v["biz_status_name"] or ""))
        active_vals = [v for v in permits.values() if "폐업" not in (v["biz_status_name"] or "")]
        pc = len(active_vals)   # 현재 운영 영업신고업체 수 (폐업 제외)
        rc = sum(int(v["room_count"] or 0) for v in active_vals)  # 현재 운영 영업신고호실 (폐업 제외)
        is_general = type_label == REPORT_RATE_EXCLUDED_LODGING_TYPE
        is_total = type_label == "전체"

        # 생활·관광·복합은 기존처럼 신고 객실수 ÷ 건물 호실수로 계산한다.
        # 일반숙박은 건축물대장 호실수와 객실수가 같은 모집단이 아니므로, 사용자 요청에
        # 따라 현재 영업신고업체 수 ÷ 일반숙박 건물 수를 신고율로 사용한다.
        if is_total:
            room_rate_blds = [
                building for building in blds
                if uses_lodging_report_rate(building.get("lodging_type"))
            ]
            general_blds = [
                building for building in blds
                if building.get("lodging_type") == REPORT_RATE_EXCLUDED_LODGING_TYPE
            ]
            legacy_rate_rc = sum(
                capped_report_rooms_by_building.get(building["id"], 0)
                for building in room_rate_blds
            )
            legacy_rate_tu = sum(int(building["units"] or 0) for building in room_rate_blds)
            general_active_count = sum(
                1 for permit in _permits_for(general_blds).values()
                if "폐업" not in (permit["biz_status_name"] or "")
            )
            rate_numerator = legacy_rate_rc + general_active_count
            rate_denominator = legacy_rate_tu + len(general_blds)
            rate_basis = "type_weighted"
            lodging_metric = "type_weighted"
        elif is_general:
            legacy_rate_rc = 0
            legacy_rate_tu = 0
            rate_numerator = pc
            rate_denominator = len(blds)
            rate_basis = "businesses_per_building"
            lodging_metric = "businesses_per_building"
        else:
            legacy_rate_rc = sum(capped_report_rooms_by_building.get(b["id"], 0) for b in blds)
            legacy_rate_tu = tu
            rate_numerator = legacy_rate_rc
            rate_denominator = legacy_rate_tu
            rate_basis = "reported_rooms_per_units"
            lodging_metric = "report_rate"

        row = {
            "type": type_label,
            "building_count": len(blds),
            "units": tu,
            "favorites": sum(fav_map.get(b["id"], 0) for b in blds),
            "listing_requests": sum(lr_req_map.get(b["id"], 0) for b in blds),
            "broker_badge": broker_c,
            "store_realty": sum(store_map.get(b["id"], {}).get("realty", 0) for b in blds),
            "store_total": sum(store_map.get(b["id"], {}).get("total", 0) for b in blds),
            "report_rate": round(rate_numerator / rate_denominator * 100, 1) if rate_denominator else None,
            "permit_count": pc,
            "room_count": rc,
            "closed_rate": round(cc / total_pc * 100, 1) if total_pc else None,
            "lodging_metric": lodging_metric,
            "report_rate_numerator": rate_numerator,
            "report_rate_denominator": rate_denominator,
            "report_rate_basis": rate_basis,
            # 기존 지역별 신고율 API용 일반숙박 제외 분자·분모는 별도 유지한다.
            "report_rate_room_count": legacy_rate_rc,
            "report_rate_units": legacy_rate_tu,
            "report_rate_building_count": (
                len(room_rate_blds) if is_total
                else (len(blds) if not is_general else 0)
            ),
            "report_rate_excludes_general": False,
        }
        if is_general:
            sub_stats = {
                hygiene_type: {"building_ids": set(), "permits": {}}
                for hygiene_type in GENERAL_LODGING_SUB_TYPES
            }
            for building in blds:
                road_key = bld_rk[building["id"]]
                jibun_key = bld_jk[building["id"]]
                building_permits = lr_road_map.get(road_key) if road_key else None
                if not building_permits:
                    building_permits = lr_jibun_map.get(jibun_key) if jibun_key else None
                for permit_number, permit in (building_permits or {}).items():
                    hygiene_type = permit.get("hygiene_type")
                    if hygiene_type not in sub_stats:
                        continue
                    # 분모는 해당 세부 업태로 매칭된 일반숙박 건물 수이며, 폐업 신고도
                    # 기존 건물이므로 분모에 남긴다. 분자는 현재 영업 중 신고업체만 센다.
                    sub_stats[hygiene_type]["building_ids"].add(building["id"])
                    if "폐업" not in (permit.get("biz_status_name") or ""):
                        sub_stats[hygiene_type]["permits"][permit_number] = permit
            row["sub_rows"] = [
                {
                    "type": hygiene_type,
                    "building_count": len(sub_stats[hygiene_type]["building_ids"]),
                    "permit_count": len(sub_stats[hygiene_type]["permits"]),
                    "room_count": sum(
                        int(permit["room_count"] or 0)
                        for permit in sub_stats[hygiene_type]["permits"].values()
                    ),
                    "report_rate": (
                        round(
                            len(sub_stats[hygiene_type]["permits"])
                            / len(sub_stats[hygiene_type]["building_ids"]) * 100,
                            1,
                        )
                        if sub_stats[hygiene_type]["building_ids"] else None
                    ),
                }
                for hygiene_type in GENERAL_LODGING_SUB_TYPES
            ]
            sub_room_total = sum(sub_row["room_count"] for sub_row in row["sub_rows"])
            if sub_room_total != rc:
                app.logger.warning(
                    "일반숙박 세분류 합계 불일치: 일반 행 %s실, 세분류 %s실",
                    rc,
                    sub_room_total,
                )
        return row

    rows = [_row(all_list, "전체")] + [_row(by_type[t], t) for t in TYPES]
    # 전체 행도 지도와 같은 명시적 COUNT 쿼리 결과를 사용한다.
    rows[0]["building_count"] = total_building_cnt
    result = {
        "ok": True,
        "rows": rows,
        # /api/building-count와 관리자 통계 상단이 공유하는 마스터 건물 수.
        "total_building_cnt": total_building_cnt,
        # 지도 범례의 세부 분포도 동일한 캐시 시점으로 유지한다.
        "building_count_by_type": building_count_by_type,
    }
    _bld_full_stats_cache = {"ts": now, "data": result}
    if _master_stats_is_rebuilding():
        return jsonify(result)
    response_payload = dict(result)
    response_payload.pop("total_building_cnt", None)
    response_payload.pop("building_count_by_type", None)
    return jsonify(response_payload)


_PUBLIC_LODGING_STATS_TYPES = {"전체", "생활", "관광", REPORT_RATE_EXCLUDED_LODGING_TYPE, "복합"}
_PUBLIC_LODGING_STATS_FIELDS = ("type", "building_count", "units", "biz_count", "room_count", "report_rate")


def _public_lodging_stats_payload(payload: dict) -> dict:
    """관리자용 원본 통계에서 공개 화면에 필요한 최소 컬럼만 추린다."""
    def compact_row(row: dict, *, is_sub_row=False) -> dict:
        compact = {
            "type": row.get("type"),
            "building_count": row.get("building_count", 0),
            "units": None if is_sub_row else row.get("units", 0),
            "biz_count": row.get("permit_count", 0),
            "room_count": row.get("room_count", 0),
            "report_rate": row.get("report_rate"),
        }
        return compact

    public_rows = []
    for row in payload.get("rows") or []:
        if row.get("type") not in _PUBLIC_LODGING_STATS_TYPES:
            continue
        compact = compact_row(row)
        if row.get("type") == REPORT_RATE_EXCLUDED_LODGING_TYPE:
            compact["sub_rows"] = [
                compact_row(sub, is_sub_row=True)
                for sub in (row.get("sub_rows") or [])
            ]
        public_rows.append(compact)
    response = {"ok": payload.get("ok") is True, "rows": public_rows}
    if payload.get("status"):
        response["status"] = payload["status"]
    return response


def _live_master_building_count():
    """지도와 동일한 기준의 현재 건물 수를 가볍게 조회한다."""
    conn = cur = None
    try:
        conn = get_conn()
        cur = conn.cursor()
        cur.execute("""
            SELECT COUNT(*) AS total_building_cnt
            FROM master_buildings
            WHERE lodging_type IS DISTINCT FROM 'mixed_use_excluded'
        """)
        row = cur.fetchone() or {}
        return int(row.get("total_building_cnt") or 0)
    except Exception:
        # 관리자 통계 화면은 기존 캐시를 우선 반환해야 하므로, 비교용 COUNT 장애가
        # 전체 통계 API를 실패시키지 않게 한다.
        app.logger.warning("[master-stats] live building count check failed", exc_info=True)
        return None
    finally:
        if cur:
            cur.close()
        if conn:
            conn.close()


def _cached_master_building_count():
    """현재 마스터 통계 캐시에 저장된 지도 기준 건물 수를 반환한다."""
    lodging_stats = _MASTER_STATS_CACHE.get("data", {}).get("lodging_stats") or {}
    cached_count = lodging_stats.get("total_building_cnt")
    if cached_count is not None:
        return int(cached_count)
    total_row = next(
        (row for row in (lodging_stats.get("rows") or []) if row.get("type") == "전체"),
        None,
    )
    return int(total_row.get("building_count") or 0) if total_row else None


@app.route("/api/admin/buildings/full-stats")
@require_admin
def admin_buildings_full_stats():
    # 관리자 통계 상단은 현재 캐시를 즉시 돌려준다. 다만 지도 기준 실시간 수치와
    # 50건 이상 차이나면 이벤트만 세워 백그라운드 마스터 재계산을 예약한다.
    cached_count = _cached_master_building_count()
    live_count = _live_master_building_count()
    if (
        cached_count is not None
        and live_count is not None
        and abs(live_count - cached_count) >= 50
    ):
        _MASTER_STATS_NEEDS_REFRESH.set()
    return _lodging_full_stats_payload()


