@app.route("/api/admin/brhub-sync-status")
@require_admin
def admin_brhub_sync_status():
    """건물수집 진행상황 + brhub_bulk 수집 현황 + 체크포인트/오늘 호출량."""
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute("SELECT COUNT(*) AS c FROM master_buildings WHERE source IN ('brhub_bulk', 'api_discovered')")
        total = cur.fetchone()["c"]
        cur.execute("""
            SELECT CASE
                     WHEN lodging_type = '생활' THEN 'living_stay'
                     WHEN lodging_type = '관광' THEN 'tourist'
                     WHEN lodging_type = '일반' THEN 'general'
                     WHEN lodging_type = '복합' THEN 'mixed'
                     WHEN lodging_type = 'mixed_use_excluded' THEN 'excluded'
                     WHEN building_status IN ('허가', '착공') THEN 'pre_completion'
                     ELSE 'unclassified'
                   END AS k, COUNT(*) AS c
            FROM master_buildings WHERE source IN ('brhub_bulk', 'api_discovered') GROUP BY 1
        """)
        by_type = {r["k"]: r["c"] for r in cur.fetchall()}
        cur.execute("SELECT value, updated_at FROM app_meta WHERE key = %s", (_BRHUB_SYNC_META_KEY,))
        meta = cur.fetchone()
        cur.execute("SELECT value FROM app_meta WHERE key = 'brhub_progress'")
        prog_row = cur.fetchone()
    finally:
        cur.close()
        conn.close()

    progress = status = None
    try:
        progress = json.loads(prog_row["value"]) if prog_row and prog_row["value"] else None
    except (TypeError, ValueError):
        pass
    try:
        status = json.loads(meta["value"]) if meta and meta["value"] else None
    except (TypeError, ValueError):
        pass

    calls_today = 0
    if progress and progress.get("calls_date") == datetime.now().strftime("%Y-%m-%d"):
        try:
            calls_today = int(progress.get("calls_today") or 0)
        except (TypeError, ValueError):
            pass

    running = bool(status and status.get("state") == "running")
    stale = False
    if running and meta["updated_at"]:
        age = (datetime.now() - meta["updated_at"]).total_seconds()
        if age > _SYNC_STALE_MIN * 60:
            running, stale = False, True

    return jsonify({
        "ok": True,
        "running": running,
        "state": ("stale" if stale else (status.get("state") if status else None)),
        "started_at": _kst_label(status.get("started_at") if status else None),
        "finished_at": _kst_label(status.get("finished_at") if status else None),
        "processed": (status.get("processed") if status else None),
        "found": (status.get("found") if status else None),
        "completed": (status.get("completed") if status else None),
        "error": ((status.get("error") if status else None)
                  or ("이전 실행이 비정상 종료된 것으로 보입니다(장시간 응답 없음). 다시 실행할 수 있습니다." if stale else None)),
        "brhub_total": total,
        "by_type": by_type,
        "checkpoint_idx": (progress.get("idx") if progress else 0) or 0,
        "total_dongs": _brhub_total_dongs(),
        "progress_by_sido": _brhub_progress_by_sido(
            (progress.get("idx") if progress else 0) or 0
        ),
        "found_total": (progress.get("found_total") if progress else 0) or 0,
        "failed_dongs": (progress.get("failed_dongs") if progress else None) or [],
        "cooldowns": (progress.get("cooldowns") if progress else None) or [],
        "stop_reason": (status.get("stop_reason") if status else None),
        "calls_today": calls_today,
        "calls_remaining": max(0, _BRHUB_DAILY_CAP - calls_today),
        "daily_cap": _BRHUB_DAILY_CAP,
    })


_PERMITS_SYNC_META_KEY     = "permits_sync_status"
_REALTY_SYNC_META_KEY      = "realty_stores_sync_status"
_RECLASSIFY_META_KEY       = "reclassify_unclassified_status"
_STORES_SYNC_META_KEY      = "stores_sync_status"
_STORES_DAILY_CAP          = 500  # sync_stores.py --daily-cap 기본값과 동일 유지


@app.route("/api/admin/sync-stores", methods=["POST"])
@require_admin
@limiter.limit("2 per hour")
def admin_stores_sync_run():
    """상가정보 사전수집(sync_stores.py) 시작 — brhub_sync와 동일한 잠금/러너 패턴."""
    if not os.environ.get("STORE_INFO_SERVICE_KEY", "").strip():
        return jsonify({"ok": False, "message": "STORE_INFO_SERVICE_KEY 시크릿이 등록되어 있지 않습니다."}), 400
    conn = get_conn()
    cur = conn.cursor()
    try:
        status = {
            "run_id": _secrets.token_hex(8),
            "state": "running",
            "started_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            "finished_at": None,
            "processed": None,
            "saved": None,
            "calls_today": None,
            "error": None,
        }
        cur.execute(f"""
            INSERT INTO app_meta (key, value, updated_at)
            VALUES (%s, %s, NOW())
            ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = NOW()
            WHERE ((app_meta.value::jsonb ->> 'state') IS DISTINCT FROM 'running'
                   OR app_meta.updated_at < NOW() - INTERVAL '{int(_SYNC_STALE_MIN)} minutes')
              AND ((app_meta.value::jsonb ->> 'state') IS DISTINCT FROM 'done'
                   OR app_meta.updated_at < NOW() - INTERVAL '5 minutes')
        """, (_STORES_SYNC_META_KEY, json.dumps(status, ensure_ascii=False)))
        acquired = cur.rowcount > 0
        prev_state = None
        if not acquired:
            cur.execute("SELECT value FROM app_meta WHERE key = %s", (_STORES_SYNC_META_KEY,))
            prev = cur.fetchone()
            try:
                prev_state = json.loads(prev["value"]).get("state") if prev and prev["value"] else None
            except (TypeError, ValueError):
                prev_state = None
        conn.commit()
    finally:
        cur.close()
        conn.close()

    if not acquired:
        if prev_state == "done":
            return jsonify({"ok": False, "message": "직전 동기화가 완료된 지 30분이 지나지 않았습니다. 잠시 후 다시 시도해 주세요."}), 429
        return jsonify({"ok": False, "message": "이미 동기화가 실행 중입니다. 완료 후 다시 시도해 주세요."}), 409

    base_dir = os.path.dirname(os.path.abspath(__file__))
    try:
        proc = subprocess.Popen(
            [sys.executable, "-u", os.path.join(base_dir, "sync_stores.py"),
             "--status-key", _STORES_SYNC_META_KEY,
             "--run-id", status["run_id"],
             "--daily-cap", str(_STORES_DAILY_CAP)],
            cwd=base_dir, start_new_session=True,
            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
        )
        threading.Thread(target=proc.wait, daemon=True).start()
    except Exception as e:
        status.update({"state": "failed", "error": f"러너 실행 실패: {e}"[:300],
                       "finished_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S")})
        conn = get_conn()
        cur = conn.cursor()
        try:
            cur.execute("""
                INSERT INTO app_meta (key, value, updated_at) VALUES (%s, %s, NOW())
                ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = NOW()
            """, (_STORES_SYNC_META_KEY, json.dumps(status, ensure_ascii=False)))
            conn.commit()
        finally:
            cur.close()
            conn.close()
        return jsonify({"ok": False, "message": "동기화 프로세스를 시작하지 못했습니다."}), 500

    return jsonify({"ok": True, "message": "상가정보 사전수집을 시작했습니다.", "started_at": status["started_at"]}), 202


@app.route("/api/admin/stores-sync-status")
@require_admin
def admin_stores_sync_status():
    """상가정보 사전수집 진행상황 + 체크포인트/오늘 호출량."""
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute("SELECT COUNT(*) AS c FROM building_stores")
        total_stored = cur.fetchone()["c"]
        cur.execute(
            "SELECT COUNT(DISTINCT master_building_id) AS c FROM building_stores"
        )
        covered_buildings = cur.fetchone()["c"]
        cur.execute(
            "SELECT COUNT(*) AS c FROM master_buildings WHERE sgg_cd IS NOT NULL AND umd_nm IS NOT NULL AND jibun IS NOT NULL AND jibun != ''"
        )
        total_buildings = cur.fetchone()["c"]
        cur.execute("SELECT value, updated_at FROM app_meta WHERE key = %s", (_STORES_SYNC_META_KEY,))
        meta = cur.fetchone()
        cur.execute("SELECT value FROM app_meta WHERE key = %s", ("stores_progress",))
        prog_row = cur.fetchone()
        # 실시간/배치 분리 카운터
        cur.execute("SELECT value FROM app_meta WHERE key = %s", (STORE_DAILY_CALLS_REALTIME_KEY,))
        rt_row = cur.fetchone()
        cur.execute("SELECT value FROM app_meta WHERE key = %s", (STORE_DAILY_CALLS_BATCH_KEY,))
        bt_row = cur.fetchone()
    finally:
        cur.close()
        conn.close()

    progress = status = None
    try:
        progress = json.loads(prog_row["value"]) if prog_row and prog_row["value"] else None
    except (TypeError, ValueError):
        pass
    try:
        status = json.loads(meta["value"]) if meta and meta["value"] else None
    except (TypeError, ValueError):
        pass

    today_str = datetime.now().strftime("%Y-%m-%d")

    # 배치 호출량: stores_progress.calls_today (기존) + store_daily_calls_batch 중 큰 값
    batch_calls_today = 0
    if progress and progress.get("calls_date") == today_str:
        try:
            batch_calls_today = int(progress.get("calls_today") or 0)
        except (TypeError, ValueError):
            pass
    try:
        bt = json.loads(bt_row["value"]) if bt_row and bt_row["value"] else {}
        if bt.get("date") == today_str:
            batch_calls_today = max(batch_calls_today, int(bt.get("count", 0)))
    except (TypeError, ValueError, AttributeError):
        pass

    # 실시간 호출량: store_daily_calls_realtime
    rt_calls_today = 0
    try:
        rt = json.loads(rt_row["value"]) if rt_row and rt_row["value"] else {}
        if rt.get("date") == today_str:
            rt_calls_today = int(rt.get("count", 0))
    except (TypeError, ValueError, AttributeError):
        pass

    # calls_today(배치)는 기존 필드명 유지 (프론트 호환)
    calls_today = batch_calls_today

    running = bool(status and status.get("state") == "running")
    stale = False
    if running and meta and meta["updated_at"]:
        age = (datetime.now() - meta["updated_at"]).total_seconds()
        if age > _SYNC_STALE_MIN * 60:
            running, stale = False, True

    return jsonify({
        "ok": True,
        "running": running,
        "state": ("stale" if stale else (status.get("state") if status else None)),
        "started_at": _kst_label(status.get("started_at") if status else None),
        "finished_at": _kst_label(status.get("finished_at") if status else None),
        "processed": (status.get("processed") if status else None),
        "saved": (status.get("saved") if status else None),
        "error": ((status.get("error") if status else None)
                  or ("이전 실행이 비정상 종료된 것으로 보입니다(장시간 응답 없음). 다시 실행할 수 있습니다." if stale else None)),
        "total_stored": total_stored,
        "covered_buildings": covered_buildings,
        "total_buildings": total_buildings,
        "checkpoint_id": (progress.get("last_id") if progress else 0) or 0,
        # 배치 카운터 (기존 필드명 유지)
        "calls_today": calls_today,
        "calls_remaining": max(0, _STORES_DAILY_CAP - calls_today),
        "daily_cap": _STORES_DAILY_CAP,
        "stop_reason": (status.get("stop_reason") if status else None),
        # 분리 카운터 (신규)
        "batch_calls_today": batch_calls_today,
        "batch_daily_cap": _STORE_BATCH_DAILY_CAP,
        "realtime_calls_today": rt_calls_today,
        "realtime_daily_cap": _STORE_REALTIME_DAILY_CAP,
    })


@app.route("/api/admin/sync-permits", methods=["POST"])
@require_admin
@limiter.limit("2 per hour")
def admin_permits_sync_run():
    """준공전 건물수집(건축인허가) 시작 — brhub 버튼과 동일한 잠금/러너 패턴."""
    if not os.environ.get("DATA_GO_KR_BROKER_API_KEY"):
        return jsonify({"ok": False, "message": "DATA_GO_KR_BROKER_API_KEY 시크릿이 등록되어 있지 않습니다."}), 400
    conn = get_conn()
    cur = conn.cursor()
    try:
        status = {
            "run_id": _secrets.token_hex(8),
            "state": "running",
            "started_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            "finished_at": None,
            "processed": None,
            "found": None,
            "completed": None,
            "calls_today": None,
            "error": None,
        }
        cur.execute(f"""
            INSERT INTO app_meta (key, value, updated_at)
            VALUES (%s, %s, NOW())
            ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = NOW()
            WHERE ((app_meta.value::jsonb ->> 'state') IS DISTINCT FROM 'running'
                   OR app_meta.updated_at < NOW() - INTERVAL '{int(_SYNC_STALE_MIN)} minutes')
              AND ((app_meta.value::jsonb ->> 'state') IS DISTINCT FROM 'done'
                   OR app_meta.updated_at < NOW() - INTERVAL '30 minutes')
        """, (_PERMITS_SYNC_META_KEY, json.dumps(status, ensure_ascii=False)))
        acquired = cur.rowcount > 0
        prev_state = None
        if not acquired:
            cur.execute("SELECT value FROM app_meta WHERE key = %s", (_PERMITS_SYNC_META_KEY,))
            prev = cur.fetchone()
            try:
                prev_state = json.loads(prev["value"]).get("state") if prev and prev["value"] else None
            except (TypeError, ValueError):
                prev_state = None
        conn.commit()
    finally:
        cur.close()
        conn.close()

    if not acquired:
        if prev_state == "done":
            return jsonify({"ok": False, "message": "직전 동기화가 완료된 지 30분이 지나지 않았습니다. 잠시 후 다시 시도해 주세요."}), 429
        return jsonify({"ok": False, "message": "이미 동기화가 실행 중입니다. 완료 후 다시 시도해 주세요."}), 409

    # reset=true 이면 permits_progress 체크포인트를 초기화해 처음부터 재수집한다.
    # 필터 버그 수정 후 이미 건너뛴 법정동을 재처리할 때 사용.
    do_reset = request.json.get("reset") if request.is_json else False
    if do_reset:
        conn2 = get_conn()
        cur2 = conn2.cursor()
        try:
            cur2.execute(
                "DELETE FROM app_meta WHERE key = 'permits_progress'"
            )
            conn2.commit()
        finally:
            cur2.close()
            conn2.close()

    base_dir = os.path.dirname(os.path.abspath(__file__))
    cmd = [sys.executable, "-u", os.path.join(base_dir, "sync_permits.py"),
           "--status-key", _PERMITS_SYNC_META_KEY]
    if do_reset:
        cmd.append("--reset")
    try:
        proc = subprocess.Popen(
            cmd,
            cwd=base_dir, start_new_session=True,
            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
        )
        threading.Thread(target=proc.wait, daemon=True).start()
    except Exception as e:
        status.update({"state": "failed", "error": f"러너 실행 실패: {e}"[:300],
                       "finished_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S")})
        conn = get_conn()
        cur = conn.cursor()
        try:
            cur.execute("""
                INSERT INTO app_meta (key, value, updated_at) VALUES (%s, %s, NOW())
                ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = NOW()
            """, (_PERMITS_SYNC_META_KEY, json.dumps(status, ensure_ascii=False)))
            conn.commit()
        finally:
            cur.close()
            conn.close()
        return jsonify({"ok": False, "message": "동기화 프로세스를 시작하지 못했습니다."}), 500

    return jsonify({"ok": True, "message": "준공전 건물수집을 시작했습니다.", "started_at": status["started_at"]}), 202


