@app.route("/api/admin/listings/export.xlsx")
@require_admin
def admin_listings_export():
    """직거래 매물 엑셀 다운로드 — listing_requests, deal_mode='direct'."""
    sort_expr, order, where_sql, params = _admin_lst_filters()
    conn = get_conn()
    cur = conn.cursor()
    cur.execute(f"""
        SELECT lr.id, lr.master_building_id, mb.building_name,
               lr.deal_type, lr.price_krw, lr.price_krw_max, lr.monthly_rent_krw,
               lr.room_count, lr.area_sqm, lr.contact_phone, lr.status,
               to_char(COALESCE(lr.updated_at, lr.created_at), 'YYYY-MM-DD HH24:MI') AS created_at
        FROM listing_requests lr
        LEFT JOIN master_buildings mb ON mb.id = lr.master_building_id
        WHERE lr.deal_mode = 'direct' AND {where_sql}
        ORDER BY {sort_expr} {order}, lr.id DESC
    """, params)
    rows = cur.fetchall()
    cur.close()
    conn.close()

    from openpyxl import Workbook
    wb = Workbook()
    ws = wb.active
    ws.title = "직거래매물"
    ws.append(["ID", "건물ID", "건물명", "거래유형",
                "최저가(만원)", "최고가(만원)", "월세(만원)", "총 호실수", "면적(㎡)",
                "연락처", "상태", "최근 수정일"])
    for r in rows:
        ph = format_phone(r["contact_phone"]) if r["contact_phone"] else ""
        ws.append([
            r["id"], r["master_building_id"], r["building_name"], r["deal_type"],
            r["price_krw"], r["price_krw_max"], r["monthly_rent_krw"], r["room_count"],
            float(r["area_sqm"]) if r["area_sqm"] else "",
            ph, r["status"], r["created_at"],
        ])
    buf = io.BytesIO()
    wb.save(buf)
    buf.seek(0)
    resp = Response(
        buf.read(),
        mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
    )
    resp.headers["Content-Disposition"] = "attachment; filename=listings.xlsx"
    resp.headers["Cache-Control"] = "no-cache, no-store, must-revalidate"
    return resp


# ---- 매물의뢰(listing_requests) 관리 (모두 require_admin) ----
# 관리자는 조회 + 비고(admin_note) 수정만 가능. status는 중개사 API에서만 변경(여기서는 읽기전용).
_ADMIN_LREQ_SORT = {
    "id": "lr.id",
    "created_at": "COALESCE(lr.updated_at, lr.created_at)",
    "status": "lr.status",
}


@app.route("/api/admin/listing-requests")
@require_admin
def admin_listing_requests_list():
    q = (request.args.get("q") or "").strip()
    sort_key = (request.args.get("sort") or "id").strip()
    sort_expr = _ADMIN_LREQ_SORT.get(sort_key, "lr.id")
    order = "DESC" if (request.args.get("order") or "asc").strip().lower() == "desc" else "ASC"
    page, size, offset = _admin_paging()
    where = "1=1"
    params = []
    if q:
        where = "(mb.building_name ILIKE %s OR u.name ILIKE %s OR lr.contact_phone ILIKE %s OR a.office_name ILIKE %s)"
        like = f"%{q}%"
        params = [like, like, like, like]
    # 전체/직거래/중개 탭 필터 — direct/broker 외 값은 무시(전체)
    deal_mode_filter = (request.args.get("deal_mode") or "").strip()
    if deal_mode_filter in ("direct", "broker"):
        where += " AND lr.deal_mode = %s"
        params.append(deal_mode_filter)
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(f"""
            SELECT COUNT(*) c
            FROM listing_requests lr
            LEFT JOIN master_buildings mb ON mb.id = lr.master_building_id
            LEFT JOIN agents a ON a.id = lr.routed_agent_id
            LEFT JOIN users u ON u.id = lr.user_id
            WHERE {where}
        """, params)
        total = cur.fetchone()["c"]
        # sort_expr/order는 화이트리스트로만 정해지므로 f-string 삽입이 안전하다.
        cur.execute(f"""
            SELECT lr.id, lr.master_building_id, mb.building_name,
                   u.name AS requester_name,
                   lr.deal_type, lr.desired_price, lr.price_krw, lr.price_krw_max,
                   lr.monthly_rent_krw, lr.room_count, lr.area_sqm, lr.deal_mode, lr.display_seq,
                   lr.contact_phone, lr.routed_reason, lr.status, lr.admin_note,
                   CASE
                     WHEN lr.routed_reason = 'exclusive' AND COALESCE(ab.has_priority_badge, FALSE)
                          AND (ab.premium_expires_at IS NULL OR ab.premium_expires_at > NOW())
                       THEN 'premium'
                     WHEN lr.routed_reason = 'exclusive' THEN 'free'
                     ELSE lr.routed_reason
                   END AS routed_tier,
                   (lr.status = 'submitted' AND lr.created_at < NOW() - INTERVAL '7 days') AS is_delayed,
                   a.office_name AS agent_office_name, a.phone AS agent_phone,
                   to_char(COALESCE(lr.updated_at, lr.created_at), 'YYYY-MM-DD HH24:MI') AS created_at
            FROM listing_requests lr
            LEFT JOIN master_buildings mb ON mb.id = lr.master_building_id
            LEFT JOIN agents a ON a.id = lr.routed_agent_id
            LEFT JOIN users u ON u.id = lr.user_id
            LEFT JOIN agent_buildings ab
              ON ab.master_building_id = lr.master_building_id AND ab.agent_id = lr.routed_agent_id
            WHERE {where}
            ORDER BY {sort_expr} {order}, lr.id ASC
            LIMIT %s OFFSET %s
        """, params + [size, offset])
        items = [dict(r) for r in cur.fetchall()]
    finally:
        cur.close()
        conn.close()
    for it in items:
        if it.get("contact_phone"):
            it["contact_phone"] = format_phone(it["contact_phone"])
        if it.get("agent_phone"):
            it["agent_phone"] = format_phone(it["agent_phone"])
        it["listing_number"] = format_listing_number(it.get("deal_mode"), it.pop("display_seq", None))
    return jsonify({"total": total, "page": page, "size": size, "items": items})


@app.route("/api/admin/partner-building-counts")
@require_admin
def admin_partner_building_counts():
    """중개사/운영업체별 담당 건물 수 목록 (무료 캡 대비 현황 파악용)."""
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute("""
            SELECT a.id, a.office_name AS name, a.phone, a.status,
                   COUNT(ab.master_building_id) AS building_count
            FROM agents a
            LEFT JOIN agent_buildings ab ON ab.agent_id = a.id
            GROUP BY a.id, a.office_name, a.phone, a.status
            ORDER BY building_count DESC, a.id ASC
        """)
        agents = [dict(r) for r in cur.fetchall()]
        cur.execute("""
            SELECT o.id, o.company_name AS name, o.phone, o.status,
                   COUNT(ob.master_building_id) AS building_count
            FROM operators o
            LEFT JOIN operator_buildings ob ON ob.operator_id = o.id
            GROUP BY o.id, o.company_name, o.phone, o.status
            ORDER BY building_count DESC, o.id ASC
        """)
        operators = [dict(r) for r in cur.fetchall()]
    finally:
        cur.close()
        conn.close()
    return jsonify({"ok": True, "max_free_buildings": MAX_FREE_BUILDINGS,
                    "agents": agents, "operators": operators})


@app.route("/api/admin/listing-requests/<int:req_id>", methods=["PUT"])
@require_admin
def admin_listing_requests_update(req_id):
    """관리자 수정은 admin_note만 허용 — status 등 다른 필드는 값이 와도 무시한다."""
    data = request.get_json(force=True, silent=True) or {}
    if "admin_note" not in data:
        return jsonify({"ok": False, "message": "수정할 항목이 없습니다. (비고만 수정 가능)"}), 400
    note = data.get("admin_note")
    note = str(note).strip() if note is not None else None
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute("SELECT 1 FROM listing_requests WHERE id = %s", [req_id])
        if not cur.fetchone():
            return jsonify({"ok": False, "message": "존재하지 않는 의뢰입니다."}), 404
        cur.execute("UPDATE listing_requests SET admin_note = %s WHERE id = %s", [note or None, req_id])
        conn.commit()
    finally:
        cur.close()
        conn.close()
    return jsonify({"ok": True})


@app.route("/api/admin/listing-requests/bulk-delete", methods=["POST"])
@require_admin
def admin_listing_requests_bulk_delete():
    """관리자가 선택한 테스트/오등록 매물의뢰를 연관 데이터와 함께 영구 삭제한다."""
    data = request.get_json(force=True, silent=True) or {}
    raw_ids = data.get("ids")
    if not isinstance(raw_ids, list):
        return jsonify({"ok": False, "message": "삭제할 의뢰를 선택해주세요."}), 400
    ids = []
    for value in raw_ids:
        try:
            value = int(value)
        except (TypeError, ValueError):
            continue
        if value > 0 and value not in ids:
            ids.append(value)
    if not ids:
        return jsonify({"ok": False, "message": "삭제할 의뢰를 선택해주세요."}), 400
    if len(ids) > 200:
        return jsonify({"ok": False, "message": "한 번에 최대 200건까지 삭제할 수 있습니다."}), 400

    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute("SELECT id FROM listing_requests WHERE id = ANY(%s) FOR UPDATE", [ids])
        existing_ids = [row["id"] for row in cur.fetchall()]
        if not existing_ids:
            conn.rollback()
            return jsonify({"ok": False, "message": "삭제할 매물의뢰를 찾을 수 없습니다."}), 404
        # chat_rooms와 listing_request_history는 FK가 NO ACTION이므로 자식부터 지운다.
        # listing_photos/listing_likes는 ON DELETE CASCADE로 함께 삭제된다.
        cur.execute("""
            DELETE FROM chat_messages
            WHERE room_id IN (
                SELECT id FROM chat_rooms WHERE listing_request_id = ANY(%s)
            )
        """, [existing_ids])
        cur.execute("DELETE FROM chat_rooms WHERE listing_request_id = ANY(%s)", [existing_ids])
        cur.execute("DELETE FROM listing_request_history WHERE listing_request_id = ANY(%s)", [existing_ids])
        cur.execute("DELETE FROM listing_requests WHERE id = ANY(%s)", [existing_ids])
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    finally:
        cur.close()
        conn.close()
    return jsonify({"ok": True, "deleted": len(existing_ids), "skipped": len(ids) - len(existing_ids)})


