@app.route("/api/admin/listing-requests/export.xlsx")
@require_admin
def admin_listing_requests_export():
    """매물의뢰 전체 엑셀 다운로드 — 접수일 내림차순."""
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute("""
            SELECT lr.id, mb.building_name, u.name AS requester_name,
                   lr.contact_phone, lr.deal_type,
                   lr.desired_price, lr.area_sqm, lr.deal_mode,
                   lr.routed_reason, a.office_name AS agent_name,
                   a.phone AS agent_phone, lr.status, lr.admin_note,
                   COALESCE(lr.updated_at, lr.created_at) AS created_at
            FROM listing_requests lr
            LEFT JOIN master_buildings mb ON mb.id = lr.master_building_id
            LEFT JOIN agents a ON a.id = lr.routed_agent_id
            LEFT JOIN users u ON u.id = lr.user_id
            ORDER BY COALESCE(lr.updated_at, lr.created_at) DESC
        """)
        rows = cur.fetchall()
    finally:
        cur.close()
        conn.close()
    from openpyxl import Workbook
    from openpyxl.styles import Font, PatternFill, Alignment
    wb = Workbook()
    ws = wb.active
    ws.title = "매물의뢰"
    headers = ["번호", "건물명", "회원닉네임(이름)", "의뢰자 연락처", "거래유형", "희망가", "전용㎡", "진행방식",
               "전달구분", "전달중개사", "중개사 연락처", "상태", "비고", "최근 수정일"]
    ws.append(headers)
    hdr_fill = PatternFill("solid", fgColor="F9F5EE")
    for cell in ws[1]:
        cell.font = Font(bold=True); cell.fill = hdr_fill
        cell.alignment = Alignment(horizontal="center")
    reason_map = {"exclusive": "전속", "region": "관할", "house": "제휴"}
    status_map = {"submitted": "신규", "in_progress": "처리중", "done": "완료"}
    mode_map = {"direct": "직거래", "broker": "중개사연결"}
    for r in rows:
        ws.append([
            r["id"], r["building_name"] or "", r["requester_name"] or "",
            format_phone(r["contact_phone"]) if r["contact_phone"] else "",
            r["deal_type"] or "", r["desired_price"] or "",
            float(r["area_sqm"]) if r["area_sqm"] else "",
            mode_map.get(r["deal_mode"], r["deal_mode"] or ""),
            reason_map.get(r["routed_reason"], r["routed_reason"] or ""),
            r["agent_name"] or "", format_phone(r["agent_phone"]) if r["agent_phone"] else "",
            status_map.get(r["status"], r["status"] or ""),
            r["admin_note"] or "",
            r["created_at"].strftime("%Y-%m-%d %H:%M") if r["created_at"] else "",
        ])
    col_widths = [6, 20, 16, 16, 10, 18, 8, 10, 8, 22, 14, 8, 20, 16]
    for col, w in zip(ws.columns, col_widths):
        ws.column_dimensions[col[0].column_letter].width = w
    buf = io.BytesIO(); wb.save(buf); buf.seek(0)
    from datetime import date as _date
    fname = f"매물의뢰_{_date.today().strftime('%Y%m%d')}.xlsx"
    return send_file(buf, mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                     as_attachment=True, download_name=fname)


